pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted
    let waste_frac = pr / cap;
    score += 60.0 * waste_frac * waste_frac;

    // Modulo-class penalty: residues in awkward bands (e.g. 1..10, 11..20) are near-useless
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0; // dead space
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 35 {
        score -= 4.0; // still usable for small items
    } else {
        score -= 8.0; // large residual is valuable
    }

    // Perfect fit reward (harmonic alignment)
    if post_residual == 0 {
        score -= 40.0;
    }
    // Exact next-item fit reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Next item fits comfortably: reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize blocking
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap).min(1.0);
        // opening a new bin is cheap when few bins or when open bins are fragmented
        score = 45.0 - 30.0 * crowded - (open_bins_count as f64).ln() * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming, fresh capacity is good
        }
    }

    // Stream progression: early on, be more willing to open bins (long horizon to fill them)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress * (1.0 - (pr / cap));
    }

    // Mean residual coupling: if mean residual is low (bins mostly full), avoid wasting
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // gap too small for next item: penalize proportionally
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation;
    // when few bins are open, tolerate spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * (2.0 + 3.0 * (1.0 - progress));

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e., when mean residual is small relative to item or item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = 60.0
            - 0.5 * mean_residual
            - 0.2 * item_size as f64
            + (open_bins_count as f64).ln() * 4.0;
        score -= fresh_bonus.max(0.0);
    }

    // Mild reward for using large residual space efficiently.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    if !is_new_bin {
        // Dead-space avoidance with a modular "clean residual" bonus.
        let q = post_residual / 25;
        let r = post_residual % 25;
        if post_residual == 0 {
            score -= 40.0;
        } else if r <= 5 {
            score -= (5 - r) as f64 * 1.55;
        } else if r >= 20 {
            score -= (r - 20) as f64 * 1.55;
        } else {
            score += 3.0 + q as f64;
        }

        if post_residual > 0 && post_residual < 10 {
            score += 60.0 * (1.0 - progress * 0.5);
        } else if post_residual >= 10 && post_residual < 20 {
            score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
        }

        // Lookahead on next item fit.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
                if post_residual % next_item_size == 0 {
                    score -= 10.0;
                }
                let slack_after = post_residual - next_item_size;
                if slack_after > 0 && slack_after < 14 {
                    score += slack_after as f64 * 1.15;
                }
                if slack_after >= next_item_size {
                    score -= 5.0;
                    if slack_after % next_item_size == 0 {
                        score -= 4.5;
                    }
                }
                if slack_after > 0 && slack_after < 6 {
                    score -= 4.0;
                }
                if next_item_size > 60 {
                    score -= 5.0;
                }
            } else {
                score += (next_item_size - post_residual) as f64 * 0.65;
            }
        } else {
            score -= 10.0;
        }

        // Tightness: reward using a large fraction of the bin.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 10.0 * tightness;

        // Open-bin pressure: compact when many bins are open.
        score += open_bins_count as f64 * (0.6 + 0.8 * progress) * (1.0 - progress * 0.5);

        // Last-chance bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Mean-residual alignment.
        let drift = (bin_residual as f64 - mean_residual).abs();
        score += drift * 0.15;
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;

        let dead_ratio = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
        score -= 3.0 * dead_ratio * dead_ratio;
    } else {
        // New-bin candidate: attractive only when existing fits are poor.
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size) < 14);
        let awkward = post_residual > 0
            && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;

        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;

        if awkward || tight {
            score -= 10.0 + 0.05 * post_residual as f64;
        } else if good_fit_exists {
            score += 45.0;
        } else {
            score += 14.0;
        }

        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 && fitting_bins_count > 0 {
            score -= 10.0;
        }
        if progress > 0.5 && next_item_size > bin_capacity / 2 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full (small residual before placement).
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits (small post-residual relative to bin residual).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Mod-25 bucket shaping: reward post-residuals near bucket boundaries so
    // future small items can still tile the leftover space.
    if post_residual == 0 {
        score -= 18.0;
    } else {
        let q = post_residual / 25;
        let r = post_residual % 25;
        if r <= 5 {
            score -= (5 - r) as f64 * 1.55;
        } else if r >= 20 {
            score -= (r - 20) as f64 * 1.55;
        } else {
            score += 3.0 + q as f64;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting: reward bins whose
    // post-residual can host the next item, more so if it can host several.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // New-bin candidate handling.
    if is_new_bin {
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) < 0.25 * item_size as f64
            || mean_residual < item_size as f64 * 0.5;
        if desperate {
            score -= 45.0;
        } else {
            // Keep using existing bins when they fit reasonably.
            score += 20.0 + 0.3 * open_bins_count as f64 + progress * 6.0;
            if mean_residual > 30.0 {
                score += 8.0;
            }
            // A fresh bin is also attractive if the next item is large and
            // would otherwise fragment an existing bin.
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 6.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Perfect fit for the lookahead item: strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: penalize adding more bins when many are open,
    // but exempt the brand-new empty bin candidate (residual == capacity).
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    } else {
        // New bin: penalize more when few bins are open relative to stream length.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
    }

    // Slight bias toward tighter bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
