        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 5.0;
        }
        // stranded-residual coupling for new-bin decision
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64;
            score += stranded * 0.35 * (1.0 - progress);
            if stranded <= 6.0 {
