        if open_bins_count > 4 && post_residual > 20 && post_residual < 60 {
            score += 0.25 * open_bins_count as f64 * progress;
        }
        // mutation: reward near-perfect fills harder when few bins fit
        if post_residual <= 2 && fitting_bins_count <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead space penalty: residuals below the minimum item size are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class logic: bucket post_residual into capacity fractions
    let frac = post_residual as f64 / cap; // 0..1
    // Class boundaries at 1/8 fractions; small classes (<1/4) are hard to fill
    if frac < 0.125 {
        score += 25.0;
    } else if frac < 0.25 {
        score += 12.0;
    } else if frac < 0.5 {
        score += 4.0;
    }

    // Integer-division thresholds on post_residual vs next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong chaining reward
            score -= 18.0;
            // Extra reward if next item would leave a "good" harmonic class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            if next_post == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize if it creates a lonely small residual
            score += 8.0;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean (best-fit style)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for consolidating when many bins are open
    score += open_bins_count as f64 * 0.3;

    // Slight stream-awareness: later in the stream, be more greedy about exact fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual == 0) as i32 as f64 * 20.0;

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score = cap * 0.55 - item_size as f64 * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
