    }

    // Mean-residual alignment: prefer bins whose residual tracks the average.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15;

    // New-bin candidate handling.
    if is_new_bin {
        score = (bin_capacity - post_residual) as f64 + 1.0;
        score += mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        score += progress * 6.0;
