                score += 45.0; // discourage opening when fits are fine
            } else if mean_residual > 30.0 {
                score -= 8.0; // allow opening on poor fits with fragmented bins
            } else {
                score += 20.0;
            }
        }
    }

    // Late-stream compaction: reward exact-fill candidates more as stream ends.
    if post_residual == 0 {
        score -= 15.0 * (0.5 + progress);
    }

    score
}

