        } else {
            // Keep using existing bins when they fit reasonably.
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later,
    // with a graded band instead of a hard threshold.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 15.0;
    } else if r <= 5 {
        score -= (5 - r) as f64;
    } else if r >= 20 {
        score -= (r - 20) as f64;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus: avoid opening a new bin when fits are scarce.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            // Penalize slack after the next item that is too small for anything.
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 12 {
                score += slack_after as f64 * 0.8;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if next_item_size > 60 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        score -= 20.0;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;

    // Global state: many open bins -> consolidate.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: open a fresh bin only when truly beneficial.
    if is_new_bin {
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0;
        score += progress * 6.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: nearly full bin is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize slack after the lookahead item lands
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item won't fit here; dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare residual to mean residual across open bins.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a large awkward residual relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = post_residual as f64 / bin_capacity as f64;
        score += 60.0;
        // late in the stream, be more conservative about opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * 40.0 * (1.0 - progress);
        // if many bins are open with small residuals, opening fresh is fine
        if mean_residual < 30.0 && open_bins_count > 3 {
            score -= 80.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

