pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual < 10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space (10..25) is partially reusable; mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits: the smaller post_residual is relative to item,
    // the better the packing density.
    score -= 0.5 * (item_size as f64);

    // Pressure from open bin count: prefer existing bins when many are open.
    score += 3.0 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item does NOT fit and post_residual is small, slight penalty (dead end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // item is large (leaves a big reusable residual) or no good existing fit.
    if bin_residual == bin_capacity {
        score -= 20.0 + 0.3 * (item_size as f64);
        // Discard new-bin option early in the stream when few bins are open.
        if (step_index as f64) / (total_items as f64).max(1.0) < 0.2 {
            score += 15.0;
        }
    }

    // Alignment with mean residual: bins deviating far below mean residual
    // (already dense) are good targets.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post == nxt {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if nxt < post {
            let gap = post - nxt;
            // reward leaving just enough room for the next item
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // extra reward if after placing next item, residual would be tiny (<10)
            if gap >= 10.0 && post - nxt <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportional to slack
            score += 0.5 * (nxt - post);
        }
    } else {
        // last item: prefer tightest fit (smallest post_residual already base)
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when existing
    // bins would leave large dead space.
    if bin_residual == bin_capacity {
        // base attractiveness for a fresh bin
        score -= 10.0;
        // but if some open bin fits the item well (post_residual small), discourage new bin
        if next_item_size > 0 && (post_residual as f64) <= next_item_size as f64 {
            score += 25.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize creating residuals that are awkwardly small (dead space < 10 is waste,
    // but 0 is perfect). Non-linear dead-space penalty.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5;
    }

    // Slight preference to fill bins that are already more full than average
    // (keeps mean_residual low, consolidating waste).
    let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 8.0 * fullness;

    // Mild pressure to reduce number of open bins when many are open.
    if open_bins_count > 5 {
        score -= 0.5 * (open_bins_count as f64).min(20.0);
    }

    // Tie-break toward bins below mean residual (less-full bins get slightly favored
    // to balance, but only weakly so tight fits dominate).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor bins where the next item also fits (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: subtract proportionally to how well the leftover
            // after the next item is also small (tight packing chain).
            let after_next = post_residual - next_item_size;
            score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
            if after_next == 0 {
                score -= 25.0; // exact double fit is excellent
            }
        } else {
