    // Smooth reward for near-perfect fits using a smooth polynomial well.
    let waste = prn * (1.0 - prn);
    score -= 3.0 * (1.0 - 4.0 * waste) * prn; // rewards prn near 0 or 1 smoothly

    // Last-chance bin: strong smooth bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 2.0 * (1.0 - t);
    }

    // Lookahead: penalize leaving residual too small for next item,
    // reward when next item fits exactly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_gap = (pr - ni) / cap;
            score -= 2.0 * (1.0 - fit_gap * fit_gap);
        } else {
            let overflow = (ni - pr) / cap;
            score += 3.0 * overflow;
        }
    }

    // Mild penalty when this bin's residual deviates from mean residual (balance).
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // New-bin candidate: baseline cost so it's only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 act as "waste classes".
    let post_class = post_residual % 10;
    // Residue 0 is perfect packing; small residues 1..5 are near-perfect; large residues 6..9 are dead space.
    let class_penalty = match post_class {
        0 => -14.0,
        1 => -9.0,
        2 => -6.0,
        3 => -3.0,
        4 => -1.0,
        5 => 0.0,
        6 => 2.5,
        7 => 5.0,
        8 => 8.0,
        _ => 11.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: does the leftover still admit
    // a "harmonic" chunk of the capacity (50, 25, 20, 10)?
    if post_residual >= 50 {
        score -= 6.0;
    } else if post_residual >= 25 {
        score -= 3.0;
    } else if post_residual >= 20 {
        score -= 2.0;
    } else if post_residual >= 10 {
        score -= 1.0;
    }

    // Coupling with lookahead: reward leftovers that can absorb the next item exactly
    // or into a low-waste class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect lookahead fit
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            let nxt_class = nxt_post % 10;
            score -= match nxt_class {
                0 => 10.0,
                1 | 2 => 6.0,
                3 | 4 => 3.0,
                _ => 0.0,
            };
            // Harmonic divisibility: leftover divisible by common item sizes
            if nxt_post % 20 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the waste gap.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Progress-aware conservatism: late in the stream, prefer tight fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.15;

    // Avoid fragmenting many open bins when mean residual is already small.
    if (post_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a good fit (residual far larger than item) or few bins are open.
    if bin_residual == bin_capacity {
        let spread = (bin_residual as f64) - (item_size as f64);
        score = score.max(0.0);
        score += 8.0;
        if open_bins_count <= 2 {
            score -= 10.0; // early: opening bins is fine
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else if spread > 40.0 {
            score -= 6.0; // existing bins are very loose; fresh bin competitive
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin guarantees room for next item
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse if it cannot host the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual alignment: prefer bins whose residual tracks the average.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual);
        if !good_fit_exists && fitting_bins_count > 0 {
            score -= 8.0; // allow opening new bin on poor fits
        } else {
            score += 45.0; // discourage opening bins when fits are fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: bin can almost take the next item (wasted space is small).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - slack * 2.0;
        }
    }
    // Penalize post_residual just below next item size (dead space blocks lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 10.0 {
            score += 20.0 - gap * 2.0;
        }
    }
    // Dead space: tiny unusable residual that no item can fill.
    if post_residual < 10 {
        score += 30.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // Compare against mean residual: bins with residuals below mean are tighter;
    // filling them first keeps loose bins flexible.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: baseline so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, closing out bins matters more; discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Penalize dead space that is too small to be useful (below min item size 1..100 -> penalize residuals < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 18.0 * (1.0 - progress);
        // If mean residual across open bins can't fit the item, opening new bin is reasonable.
        if (mean_residual < item_size as f64) && fitting_bins_count == 0 {
            score -= 22.0;
        }
    }

    // Slight preference for bins below mean residual (balance load, keep big holes available).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild reward for using bins with smaller residuals first (best-fit bias).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear in progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Smooth coupling: penalize large residuals more as stream progresses
    score += 20.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (small post_residual), stronger later in stream
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 8.0 * (diff / cap) * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (-diff / cap);
        }
    }

    // Discourage spreading across many open bins when residuals are high
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" classes (multiples of small denominators) are preferred.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -50.0 // perfect fit, ideal
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr < 10 {
        15.0 // tiny dead space, nearly unusable
    } else {
        0.0
    };
    score += class_penalty;

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good existing option exists (or many bins are already open).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 25.0
            + 15.0 * (1.0 - progress)
            + if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score -= new_bin_bonus;
    } else {
        // Mildly penalize stuffing bins when many are open and residual is
        // far from mean (fragmentation risk).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer filling bins with larger items tightly (tightness reward).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Integer division threshold: leftover in [10,25] is a "sweet spot"
    // usable by most future items.
    if pr >= 10 && pr <= 25 {
        score -= 6.0;
    } else if pr > 60 {
        score += 2.0; // large leftover means item was small; keep for bigger items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness ratio: reward filling the bin proportionally.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Dead-space coupling: residual that no future item (min size 1..10 band) can use.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Open bins pressure: penalize placements into already-crowded sets mildly,
    // but reward consolidating when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Mean residual deviation: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // would leave a large, useful residual and open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin when it creates a clean large residual for lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // Late in stream, prefer closing out bins tightly instead of opening new.
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Lookahead: reward residual that exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with mismatch.
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).powi(8);
        // Extra bonus for an exact chain fit (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Penalize small unusable post-residuals (waste).
    if post_residual < 10 {
        score += 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits relative to mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with less residual among equally good fits (best-fit bias).
    score += 0.2 * (bin_residual as f64 - post_residual as f64);

    // Early in stream: be slightly more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large or few bins fit it.
        let mut new_bin_penalty = 12.0;
        if item_size >= 60 { new_bin_penalty -= 8.0; }
        if fitting_bins_count <= 1 { new_bin_penalty -= 20.0; }
        if progress < 0.2 { new_bin_penalty += 5.0; }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared penalty on leftover space (dead space is doubly bad).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a gap slightly too small for the next item (wasted sliver).
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += gap * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins fit the item
    // or when mean residual across open bins is large (existing space is underused).
    if bin_residual == bin_capacity {
        score += 15.0
            + 2.0 * open_bins_count as f64
            + mean_residual * 0.3
            + if fitting_bins_count > 1 { 20.0 } else { 0.0 };
    } else {
        // Prefer bins with residual close to item_size (best-fit shaping) among open bins.
        let slack = (bin_residual - item_size) as f64;
        score += (slack / bin_capacity as f64) * 10.0;
        // Slight preference for older/denser bins: align with mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins; late in the
    // stream, prioritize closing out bins tightly (larger endgame tightness weight).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (bin_capacity - post_residual.min(bin_capacity)) as f64 / bin_capacity as f64;

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let tight = 1.0 - fit_ratio; // how full the bin becomes

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * tight * tight);

    // Non-linear interaction of tightness with stream progress:
    // late in the stream, favor tighter fills more aggressively
    let progress_coupling = progress * (1.0 - progress).powi(2);
    score -= 30.0 * progress_coupling * tight * tight * tight;

    // Penalize residual that is unusably small relative to typical item sizes
    let dead = ((pr - 1.0).max(0.0) / cap).powi(2);
    score += 40.0 * (1.0 - dead) * tight * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // penalize blocking the next item mildly
        score += 8.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap).abs();

    // Smooth penalty for very loose fits early on
    score += 10.0 * (1.0 - tight) * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes (hard to reuse) are penalized.
    let cap_frac = bin_capacity / 10; // 10-unit harmonic lattice
    let residue_class = post_residual / cap_frac; // 0..10 class index
    // Penalize mid classes (residues 30-60 are awkward), reward tiny or large.
    let class_penalty: f64 = match residue_class {
        0 => -6.0,                       // near-perfect fit
        1 => -3.0,                       // small usable residue
        2 | 3 => 4.0,                    // dead-space zone
        4 | 5 => 6.0,
        6 | 7 => 2.0,
        _ => -2.0,                       // large residue, still flexible
    };
    score += class_penalty;

    // Exact modular harmony: post_residual divisible by common size steps
    // (10, 20, 25) tends to be reusable by future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 2.5;
    }
    // Odd, prime-ish residues are dead weight.
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 10 {
        score += 3.0;
    }

    // Lookahead: does next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 5.0 - (gap as f64) * 0.15; // tighter follow-up fit is better
        } else {
            // next item cannot use this bin's residue; penalize proportionally
            score += ((next_item_size - post_residual) as f64).min(10.0) * 0.4;
        }
        // Harmonic divisibility: next item divides the residue evenly
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give the empty bin a mild penalty that scales with how
    // fragmented the open bins are.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score += 15.0 - fragmentation.min(15.0);
        // Late in the stream, avoid opening bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    } else {
