    // Harmonic dead-space penalty: small unusable residues are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - post / 10.0);
    }

    // Next-item lookahead: reward keeping residual usable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).powf(2.0));
