        if post_residual >= 20 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the next item fits the post residual exactly-ish, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0 * (post_residual as f64 / 10.0);
    }

    // Prefer bins below the mean residual (tighter bins) to keep large residuals available.
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Late in the stream, tighten up: avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 500.0;
        return score;
    }

    // 2-step lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.3;
        } else {
            // Dead space: next item can't use the leftover. Penalize small leftovers.
            let waste = post_residual as f64;
            score += waste * 0.8;
            // Extra penalty if leftover is tiny (nearly perfect but useless).
            if waste < 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare against mean residual: bins with residual far below mean are tighter;
    // placing into tighter bins preserves loose capacity elsewhere.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many options exist, to prefer the best fit only.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Brand-new empty bin candidate: should only win if item is large / poor fits elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 120.0;
        // Large items justify a fresh bin.
        score -= (item_size as f64) * 0.6;
        // If no open bin fits (this is the only candidate), opening is necessary.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins that are already fairly full (small residual before placement).
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits (small post-residual relative to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling: reward a bin whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            // Post-residual too small for the next item: penalize proportionally.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
        // If next item is large, prefer spreading load (higher post-residual ok).
        if next_item_size > 60 && post_residual >= next_item_size as u32 {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, just consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate; few open bins -> new bins are cheap.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is well below the mean,
    // it's a "rich" bin; prefer filling those to keep the pool uniform.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to typical residuals or fits are terrible.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) < 0.25 * item_size as f64
            || avg_waste < item_size as f64 * 0.5;
        if desperate {
            score -= 45.0;
        } else {
            // Keep using existing bins when they fit reasonably.
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space avoidance bands (borrowed from best-known, tuned).
    let band = post_residual / 20;
    score += band as f64 * 2.0;

    if post_residual > 0 && post_residual < 10 {
        score += 55.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 22.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit the resulting gap?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Same size-class lookahead: chain-friendly placement.
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Open-bin pressure: compact when many bins are open, stronger late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.7 * progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean-residual alignment, softened.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.08;

    // New-bin candidate: open only when no existing bin gives a good fit.
    if is_new_bin {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual)
            || (post_residual >= next_item_size && post_residual - next_item_size < 10);
        if !good_fit_exists && fitting_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let is_new_bin = bin_residual == bin_capacity ;
    let band = post_residual / 20 ;
    score += band as f64 * 2.0 ;
    if post_residual == 0 { score -= 60.0 ; }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 ;
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0 ; }
            // exact lookahead fit: strongly reward leaving exactly next item's room
            if post_residual == next_item_size { score -= 10.0 ; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6 ;
        }
    }
    if fitting_bins_count == 1 && ! is_new_bin { score -= 30.0 ; }
    // new-bin gating: prefer opening a fresh bin when the chosen fit leaves a large,
    // awkward residual relative to mean residual (dead-space avoidance)
    if is_new_bin {
        let tight = fitting_bins_count > 0
            && post_residual > 0
            && (post_residual as f64) < mean_residual * 0.45
            && next_item_size > post_residual ;
        if tight { score -= 22.0 ; }
        else { score += 4.0 ; }
    } else if post_residual > 0 {
        // penalize residuals that are too small to be useful later
        let waste = mean_residual - post_residual as f64 ;
        if waste > 0.0 { score += waste * 0.15 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let prog = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 12.0 * prog * norm_post * norm_post * cap * 0.1;

    // Reward tight fits, more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 20.0 * prog * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 8.0 + 0.3 * (nx - post);
        } else {
            score -= 2.0 * (1.0 - (nx / post).min(1.0));
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins; mean-residual coupling.
    score += 0.5 * open_bins_count as f64 * norm_post;
    score += 1.5 * (mean_residual - post).abs() / cap;

    // New-bin candidate: keep it neutral-ish, slightly favored only when stream is young.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - prog);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let is_new_bin = bin_residual == bin_capacity ;
    let band = post_residual / 20 ;
    score += band as f64 * 2.0 ;
    if post_residual == 0 { score -= 60.0 ; }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 ;
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0 ; }
            // exact lookahead fit: strongly reward leaving exactly next item's room
            if post_residual == next_item_size { score -= 10.0 ; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6 ;
        }
    }
    if fitting_bins_count == 1 && ! is_new_bin { score -= 30.0 ; }
    // new-bin gating: prefer opening a fresh bin when the chosen fit leaves a large,
    // awkward residual relative to mean residual (dead-space avoidance)
    if is_new_bin {
        let tight = fitting_bins_count > 0
            && post_residual > 0
            && (post_residual as f64) < mean_residual * 0.45
            && next_item_size > post_residual ;
        if tight { score -= 22.0 ; }
        else { score += 4.0 ; }
    } else if post_residual > 0 {
        // penalize residuals that are too small to be useful later
        let waste = mean_residual - post_residual as f64 ;
        if waste > 0.0 { score += waste * 0.15 ; }
    }
    // extra: reward near-perfect fills (small post_residual) to compact bins
    if post_residual > 0 && post_residual <= 5 { score -= 8.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual: leftover in (0..=10]
    // is essentially dead space; (10..=30] is reusable for small items.
    if post_residual <= 10 {
        score -= 40.0; // perfect-ish fit: strongly reward
    } else if post_residual <= 30 {
        score -= 12.0; // still attractive
    } else if post_residual <= 60 {
        score += 6.0; // mediocre
    } else {
        score += 14.0; // large leftover = wasteful placement
    }

    // Modulo arithmetic on post_residual: capacity fractions.
    // Leftovers near multiples of 25 align with common item sizes (10..80).
    let q = post_residual / 25;
    let r = post_residual % 25;
    if r <= 5 {
        score -= (5 - r) as f64; // near a harmonic quarter of capacity
    } else if r >= 20 {
        score -= (r - 20) as f64;
    } else {
        score += 3.0 + q as f64;
    }

    // Coupling with lookahead item: does the post residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Favor exact harmonic match: post_residual divisible by next_item_size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            score -= 5.0;
        } else {
            score += 8.0; // this bin can't host the next item
        }
    } else {
        // Last item: close bins tightly.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should win only when no open
    // bin gives a tight fit; make empty-bin score track mean residual pressure.
    if bin_residual == bin_capacity {
        score = cap - pr + 0.0; // equals 0 baseline for empty bin
        score += mean_residual * 0.3; // more accumulated slack -> prefer new bin less
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if post_residual > 0 {
            score += 1.0; // guard tie-break: slight penalty vs tight fits
        }
    }

    // Stream progression: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).abs() * 0.2;
    score -= progress * 4.0;

    // Crowding: many open bins -> prefer reusing (tighter post residual).
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item (1..=10) are pure waste.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0; // unusable sliver
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0; // risky narrow gap
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill, strongly favored
    }

    // Tight fit reward: item consumes a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spawning more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.6 * (1.0 + progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item can use the post_residual exactly-ish,
    // reward leaving that gap; otherwise penalize leaving a gap sized
    // just below next_item_size (near-miss dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // gap remains usable for the next item
        } else if post_residual > 0 && next_item_size - post_residual <= 5 {
            score += 10.0; // agonizing near-miss gap
        }
    }

    // New-bin candidate handling: an empty bin should only win when all
    // existing fits are poor. Give it a moderate default so tight fits
    // in open bins still beat it.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper.
        score -= 18.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let is_new_bin = bin_residual == bin_capacity ;
    // finer residual banding to discourage leaving medium dead space
    let band = post_residual / 12 ;
    score += band as f64 * 1.5 ;
    if post_residual == 0 { score -= 60.0 ; }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 ;
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0 ; }
            // reward near-perfect chains: residual barely above next item
            if post_residual < next_item_size + 8 { score -= 5.0 ; }
        } else if post_residual > 0 {
            // penalize dead space proportional to how much of it is unusable for the next item
            score += (next_item_size - post_residual) as f64 * 0.6 ;
        }
    }
    // lookahead trade-off: opening a new bin is only attractive when the current
    // best fits are poor and many items remain
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        let poor_fits = fitting_bins_count <= 2 ;
        if poor_fits && progress < 0.85 {
            score -= 25.0 ;
        } else {
            score += 15.0 ;
        }
    }
    if fitting_bins_count == 1 && ! is_new_bin { score -= 30.0 ; }
    // mild pressure toward consolidating into bins already below mean residual
    if ! is_new_bin && (bin_residual as f64) < mean_residual { score -= 4.0 ; }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // coarse residual banding: prefer bins that will end up in a "tight" band
    let band = post_residual / 20;
    score += band as f64 * 2.0;

    // perfect closure is highly rewarding
    if post_residual == 0 { score -= 60.0; }

    // lookahead: reward bins that leave space usable by the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0; }
            // extra reward when leftover after next item is small (near-exact fit)
            let after = post_residual - next_item_size;
            if after <= 8 { score -= (8 - after) as f64 * 1.2; }
        } else if post_residual > 0 {
            // penalize dead space proportional to unusable gap
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // scarcity: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin { score -= 30.0; }

    // prefer opening a new bin only when the best open-bin fit is sloppy:
    // penalize new bins mildly unless open bins are congested
    if is_new_bin {
        let congested = mean_residual < (item_size as f64) * 1.5;
        if congested { score -= 10.0; } else { score += 15.0; }
    }

    // late in the stream, consolidate harder: avoid fragmenting residuals
    if total_items > 0 && step_index * 4 > total_items * 3 {
        if post_residual > 0 && post_residual < 10 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // Reward leaving exactly enough room for the next item (perfect pairing).
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would be post_residual - next_item_size;
            // penalize the resulting dead space nonlinearly.
            let dead = (post_residual - next_item_size) as f64;
            score += 0.15 * dead * dead / bin_capacity as f64;
        } else {
            // Next item won't fit here; small penalty proportional to shortfall.
            let short = (next_item_size - post_residual) as f64;
            score += 0.10 * short;
        }
    } else {
        // Last item: simply minimize post residual.
        score += 20.0;
    }

    // Compare against mean residual: bins below mean residual are "tighter";
    // favor placing into tighter bins to consolidate space.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin for the current item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when the current item fits badly
    // everywhere (large post_residual elsewhere / many fitting bins already tight).
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 30.0
            - 0.5 * mean_residual
            - 10.0 * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild stream-progression bias: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let is_new_bin = bin_residual == bin_capacity ;
    let band = post_residual / 20 ;
    score += band as f64 * 2.0 ;
    if post_residual == 0 { score -= 60.0 ; }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 ;
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0 ; }
            // tighter lookahead: exact fit for the next item is very valuable
            if post_residual == next_item_size { score -= 9.0 ; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6 ;
        }
    }
    // penalize new bins more when many bins are still open with slack
    if is_new_bin {
        let slack = mean_residual.max(0.0) ;
        score += 18.0 + slack * 0.35 + (open_bins_count as f64).sqrt() * 3.0 ;
        // but allow new bin when the item is large relative to mean residual
        if (item_size as f64) > slack * 1.6 { score -= 14.0 ; }
    }
    if fitting_bins_count == 1 && ! is_new_bin { score -= 30.0 ; }
    // reward near-perfect fills: small post residual relative to capacity
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
    if fill_ratio > 0.92 { score -= 8.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near 0 is best, super-linear penalty for waste.
    let tight = 1.0 - (post / cap);
    score -= 40.0 * tight * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt * 0.5 {
            score += 25.0 * (1.0 - post / nxt.max(1.0));
        }
        // Reward leaving room exactly for the next item (perfect chaining).
        if (post - nxt).abs() < 3.0 {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should win only when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global fragmentation.
        score += 15.0;
        // If open bins are fragmented (high mean residual spread), new bin less bad.
        score -= (mean_residual / cap) * 10.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for bins with residual near the item (best-fit bias).
        score += 0.15 * (bin_residual as f64 - item_size as f64).abs();
        // Many open bins: encourage consolidation into existing bins.
        score -= (open_bins_count.min(50) as f64) * 0.4;
        // Bin whose residual is close to mean residual keeps balance.
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Absolute avoidance of overflow-risky tiny leftovers mid-stream.
    if post > 0.0 && post < 5.0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over time
    let mut score = pr * (1.0 + 1.5 * progress * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize large residual waste more strongly late in the stream (cubic coupling)
    score += 30.0 * norm_pr.powi(3) * progress;

    // Lookahead coupling: reward residual that fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = if pr >= nxt { (pr - nxt) / cap } else { 1.0 + (nxt - pr) / cap };
        score += 25.0 * fit * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space banding: penalize residuals too small to be useful later.
    let band = post_residual / 20;
    score += band as f64 * 2.0;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    } else if fitting_bins_count == 2 && !is_new_bin {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual hosts the next item,
    // with extra reward when the next item lands in the same residual band.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
        } else if post_residual > 0 {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
        if next_item_size > 60 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer filling "rich" bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: open a new bin only when it's genuinely better.
    if is_new_bin {
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) < 0.25 * item_size as f64
            || (mean_residual < item_size as f64 * 0.5 && open_bins_count < 8);
        if desperate {
            score -= 45.0;
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10 (dead-space granularity)
    let pr = post_residual as i64;
    let class = pr % 10;
    // Residuals in {0} are perfect; small residues (1..=5) are dead space; mid classes (6..9) reusable
    score += match class {
        0 => -25.0,
        1..=5 => 8.0 + (5 - class) as f64 * 3.0,
        _ => -2.0 + (9 - class) as f64 * 1.5,
    };

    // Integer-division thresholds: post_residual buckets via pr / 10
    let bucket = pr / 10;
    score -= bucket as f64 * 4.0; // prefer leaving larger reusable chunks

    // Fraction of capacity consumed by this item
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 30.0;

    // Perfect-fit detection via modulo arithmetic on bin_residual
    if bin_residual % item_size.max(1) == 0 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
        } else {
            // wasted residual relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let newbin_bonus = 60.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0 - progress * 10.0;
        score += newbin_bonus;
        // discourage new bin if item is small relative to capacity
        score += (cap - item_size as f64) * 0.4;
    }

    // Mild penalty for tight fits that leave near-mean residual (fragmentation spread)
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect closure dominates: a bin with zero leftover is ideal.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 30 {
        score -= 12.0;
    } else if post_residual <= 60 {
        score += 6.0;
    } else {
        score += 14.0;
    }

    // Harmonic quarter alignment of leftover.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if r <= 5 {
        score -= (5 - r) as f64;
    } else if r >= 20 {
        score -= (r - 20) as f64;
    } else {
        score += 3.0 + q as f64;
    }

    // Lookahead coupling: prefer bins whose post residual still hosts the next item,
    // with extra reward when leftover and next item share a coarse size band.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if post_residual % next_item_size == 0 && next_item_size > 0 {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score += 8.0;
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: must lose to any reasonably tight open bin.
    if is_new_bin {
        score = cap - pr; // baseline 0 for empty bin
        score += mean_residual * 0.3;
        score += post_residual as f64 * 0.05 + 1.0; // tie-break penalty
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is large, opening fresh capacity may be wise.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Stream progression: consolidate harder later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).abs() * 0.2;
    score -= progress * 4.0;

    // Crowding: many open bins -> prefer reuse.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps (1..=9) are nearly unusable
    // for future items (sizes >= 1 but typically larger), so punish hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap=1 -> +56, gap=9 -> +24
    } else if post_residual > 9 && post_residual <= 20 {
        score += 12.0; // mildly awkward zone
    }

    // Reward tight fits: post_residual near 0 (but not in dead zone) is great.
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual was already small (compact bins first).
    let residual_frac = bin_residual as f64 / cap;
    score += residual_frac * 15.0;

    // Open-bins pressure: many open bins -> favor filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate (residual == capacity): apply a fixed opening cost
    // so it only wins when existing bins score badly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the last chance and the fit would leave dead space,
        // new bin should win: handled implicitly by dead-space penalty above.
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space would result).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 25.0; // next item fills this bin almost perfectly
        } else {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if open bins are on average quite full,
    // keep compacting into them.
    score -= (mean_residual / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item nearly fits the leftover space (tight but not exact)
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Next item does NOT fit leftover: penalize proportionally to wasted potential
    else if next_item_size > post_residual {
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.25 * overflow;
        // Extra penalty if post_residual is a small dead zone (< next item, hard to reuse)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Prefer bins whose residual is already below the stream mean (consolidating waste)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item leaves a large usable residual
    // and existing bins are poorly matched; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // planned pair fits nicely in a fresh bin
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 20.0; // discourage abandoning usable open bins
        }
    }

    // Early in the stream: be slightly greedy toward tight fits to build structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
