        }
        // Early in stream, new bins are cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // But if current item is huge and no bin likely fits well, opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward when its residual is below mean (using tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.0;
        }
    }

    // Global pressure: many open bins -> encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (minimize wasted space)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // Smooth interaction: dead space penalized more as stream progresses
    score += 6.0 * prn * prn * (0.5 + t) * cap * 0.1;

    // Reward tight fits with smooth cubic term
    let tightness = 1.0 - prn;
    score -= 4.0 * tightness * tightness * tightness * cap * 0.1;

    // Lookahead coupling: smooth polynomial matching of post residual to next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        // penalize mismatch quadratically
        score += 3.0 * diff * diff * cap;
        // reward exact-ish match with smooth gaussian-like polynomial
        let match_p = (diff * diff).min(1.0);
        score -= 5.0 * (1.0 - match_p) * (1.0 - match_p);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins far from mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * (0.3 + 0.7 * t);

    // Congestion pressure: many open bins -> prefer filling existing bins
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 3.0 * congestion * tightness;

    // New-bin candidate: penalize opening new bins except when residuals are large
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        // smooth sigmoid-like polynomial gate
        let gate = (avg_waste - 0.35) * 4.0;
        let gate = gate.clamp(-1.0, 1.0);
        score = pr + 10.0 * (0.5 - 0.5 * gate * (2.0 - gate * gate)) - 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
