    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= 4.0; // perfect fit is always good even if next item won't land here
        }
    } else {
        score -= 20.0; // last item: close tightly
    }

