    // Classes: 0 (0..cap/8), 1 (cap/8..cap/4), 2 (cap/4..cap/2), 3 (cap/2..cap)
    let q = cap / 8.0;
    let post = post_residual as f64;
    let class: u32 = if post < q { 0 } else if post < 2.0 * q { 1 } else if post < cap / 2.0 { 2 } else { 3 };

    // Penalize dead space in the smallest band (unusable for most items)
    match class {
        0 => score += 0.5 * (q - post),          // tiny sliver: heavy penalty
        1 => score += 0.2 * (2.0 * q - post),    // quarter-band: mild penalty
        2 => score -= 0.3 * (cap / 2.0 - post),  // half-band: good, reward
        _ => score -= 0.1 * (cap - post),        // large residual: slight reward
    }

    // ---- Modulo arithmetic on post_residual: exact-harmonic residuals are valuable ----
    let pr = post_residual;
    if pr == 0 {
        score -= 12.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 4.0;  // aligns with common item sizes (multiples of 10)
    } else if pr < 10 {
        score += 6.0;  // sub-10 dead space is truly useless
    }

    // ---- Lookahead (k=2): does the next item fit into this post-residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportional to how snugly it fits
            let slack = (pr - next_item_size) as f64;
            score -= 5.0 + 0.4 * next_item_size as f64 - 0.1 * slack;
        } else {
            // Next item won't fit: penalize more if post-residual is small (wasted)
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // ---- Last-chance logic: if this is the only fitting bin, prefer using it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin early in the stream or when open bins are tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / cap;
        // New bin is attractive when existing residuals are small and many bins open
        score += 10.0 + 8.0 * (1.0 - progress) - 6.0 * tightness
