        // But avoid new bins for tiny items that clearly fit somewhere
        if item_size <= 20 && fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Slight preference for tighter existing bins (best-fit bias)
        score += 0.05 * (bin_residual as f64 - post);
        // Reward packing into bins below mean residual (balancing)
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

