    let dead_ratio = if bin_residual > 0 {
        (bin_residual - post_residual) as f64 / bin_residual as f64
    } else { 0.0 };
    score -= 3.0 * dead_ratio * dead_ratio;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

