            || (next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size) < 14);
        let awkward = post_residual > 0
            && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;

        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;

        if awkward || tight {
            score -= 10.0 + 0.05 * post_residual as f64;
        } else if good_fit_exists {
            score += 45.0;
        } else {
            score += 14.0;
        }

        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 && fitting_bins_count > 0 {
            score -= 10.0;
        }
        if progress > 0.5 && next_item_size > bin_capacity / 2 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // overflow guard, should not happen
    } else if post_residual > 0 && post_residual < 10 {
        // small unusable gap: strong penalty scaled by gap tininess
        score += (10.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the gap: penalize proportionally to gap size
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: penalize placements that keep many bins open
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: prefer bins with residual below mean (consolidating space)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: only prefer a new empty bin when open bins
    // would create large dead space or none fit well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = bin_capacity as f64;
        new_bin_score += (open_bins_count as f64) * 2.0;
        // if many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            new_bin_score += 20.0 + (fitting_bins_count as f64) * 5.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 15.0;
        score = score.max(new_bin_score);
        return new_bin_score.max(1.0) + score * 0.0; // fall through to new-bin score
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: dead space that can't host next item is costly;
    // residual that exactly hosts it (or multiples) is rewarded.
    if next_item_size > 0 {
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 {
                score -= 10.0; // exact refill
            } else if slack_after < next_item_size {
                score -= 4.0; // still likely reusable
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 3.0; // small slack is fine (near-full bin)
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0; // room for another copy
            }
        }
    }

    // Open-bin pressure: compact into existing bins, stronger early.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean-residual alignment with progress-scaled weight.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15 * (1.0 + progress);

    // Fullness reward: prefer bins that will be most filled by this item.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // New-bin candidate logic.
    if is_new_bin {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual);
        if !good_fit_exists && fitting_bins_count > 0 {
            // Open a new bin only on genuinely poor fits; scale with item size
            // so large items prefer fresh bins, small items prefer compacting.
            let poor = if post_residual > 0 {
                (next_item_size.saturating_sub(post_residual)) as f64
            } else {
                0.0
            };
            score -= 8.0 + poor * 0.3;
            if item_size > 60 {
                score -= 10.0; // big items: fresh bin is often better
            }
        } else {
            score += 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late stream: discourage bin proliferation.
        if progress > 0.7 {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but normalized against mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match -> huge reward (item 2 fills bin completely).
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits into this residual: reward closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize wasted space.
            score += 10.0 + diff * 0.15;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is
    // the only fitting bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        // Extra reward if post residual is small (tight fit).
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins fit badly.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            // Fresh bin can host current + next item nearly perfectly.
            score -= 15.0;
        } else {
            // Prefer reusing existing bins by default.
            score += 12.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Penalize leaving dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Slight preference for filling bins tighter as the stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
