    let harmonic_hits = [
        (0u32, 3.0), (25, 2.0), (33, 1.5), (34, 1.5), (50, 2.5),
        (66, 1.5), (67, 1.5), (75, 2.0), (100, 0.5),
    ];
    for &(h, r) in &harmonic_hits {
        if post_residual == h {
            score -= r;
        }
    }

    // Modulo coupling: residual congruent to small-item sizes (10..20) is likely reusable.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 1.2;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 0.8; // round residuals tile well
    }

    // --- Lookahead coupling with next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward, scaled by tightness.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 1.5 + tight;
        } else if post_residual > 0 && post_residual < 10 {
            // Next item can never use this sliver -> penalize.
            score += 2.0;
        }
        // Harmonic pair: post_residual + next_item_size exactly fills a class boundary.
        if post_residual + next_item_size == bin_capacity {
            score -= 2.5;
        }
        if post_residual + next_item_size <= bin_capacity
            && (post_residual + next_item_size) % 25 == 0 {
            score -= 1.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score = post_residual as f64;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this open bin fits; avoid opening a new bin.
        score -= 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; attractive only if open bins are fragmented
        // or this is a poor fit everywhere.
        score = cap * 0.55; // baseline: worse than a good fit (small post_residual)
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 0.5; // fresh bin trivially fits lookahead
        }
        if fitting_bins_count == 1 {
            score += 6.0; // keep the last-chance open bin in play
        }
        if open_bins_count == 0 {
            score -= 10.0; // must open
        }
        // If mean residual of open bins is large (fragmented), a new bin is fine.
        if mean_residual > cap * 0.6 {
            score -= 2.0;
        }
    }

    // Mild progression term: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 0.3 * (1.0 - frac);

    score
}

