pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1) are impossible,
    // but gaps too small for the next item are practically dead weight.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap is unusable for the lookahead item -> heavy penalty, scaled by how
            // much potential was wasted.
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else {
            // Gap remains usable -> reward keeping future options open.
            score -= next_item_size as f64 * 0.3;
        }
    }

    // Reward tight fits: exact or near-exact fills are ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 15.0;
    }

    // Penalize "awkward" mid-range gaps that few item sizes can use
    // (gaps in (0,10) or (10,20) ranges are hard to fill for typical distributions).
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate more when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= 2.0;
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it's a good consolidation; if it stays far above, mildly penalize.
    let mean_post = mean_residual - item_size as f64;
    score += (post_residual as f64 - mean_post) * 0.1;

    // Late-stream tightening: as the stream progresses, avoid leaving many small
    // open bins; favor fuller placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
