pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance with graded penalties on small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 22.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward perfect fills and near-modular residuals.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let r = post_residual % 25;
        if r <= 4 {
            score -= (4 - r) as f64 * 1.6;
        } else if r >= 21 {
            score -= (r - 21) as f64 * 1.6;
        }
    }

    // Lookahead: does the next item fit after placement?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after = post_residual - next_item_size;
            score -= 12.0;
            if slack_after == 0 {
                score -= 9.0;
            } else if slack_after < 14 {
                score += slack_after as f64 * 1.1;
            } else {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
            }
            if slack_after % next_item_size.max(1) == 0 && slack_after > 0 {
                score -= 4.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        score -= 18.0;
    }

    // Open-bin pressure: compact into existing bins, stronger late in stream.
    score += open_bins_count as f64 * (0.6 + 0.9 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 32.0;
    }

    // Mean-residual alignment.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.12;

    // Tightness reward: prefer bins nearly filled by this placement.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 9.0 * tightness;

    // New-bin candidate logic.
    if is_new_bin {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual);
        let awkward = fitting_bins_count > 0
            && post_residual > 0
            && post_residual < next_item_size
