            if slack_after >= next_item_size {
                score -= 3.0; // room for another copy
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0; // nearly perfect
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
