    }

    // Open-bin pressure: compact into existing bins.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual alignment, softened.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.08;

    // Tightness reward: prefer bins that become nearly full.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Progress-based fill bonus.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity.max(1) as f64);

    // Large next item lookahead: keep room for it.
    if next_item_size > 60 && post_residual >= next_item_size {
        score -= 5.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > bin_capacity / 2 {
        score += 4.0; // stranded large residual can't host next item
    }

