pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if is_new_bin {
        // New-bin candidate: attractive only when open bins fit poorly.
        let awkward = fitting_bins_count > 0
            && post_residual > 0
            && (post_residual < next_item_size.max(1) || post_residual < 8);
        let base = (bin_capacity - post_residual) as f64;
        score = base + mean_residual * 0.25 + 2.0 + progress * 5.0;
        if awkward { score -= 12.0 + 0.05 * post_residual as f64; }
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score += 6.0; // open bin would leave a nice gap for next item
        }
        if open_bins_count > 6 { score += 4.0; }
        if item_size > 70 { score -= 6.0; }
        return score;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 45.0;
    } else {
        // Penalize small unusable gaps, graded by residual band.
        if post_residual < 10 {
            score += 55.0 - post_residual as f64 * 1.5;
        } else if post_residual < 20 {
            score += 20.0 * (1.0 - post_residual as f64 / 20.0);
        }
        // Tightness: reward filling most of the residual.
        let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * tightness;
    }

    // Lookahead: does the leftover fit the next item well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 { score -= 10.0; }
            if slack_after >= next_item_size { score -= 6.0; }
            if slack_after > 0 && slack_after < 6 { score += 5.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
    } else {
        score -= 15.0;
    }

    // Open-bin pressure: compact into existing bins, stronger early.
    score += open_bins_count as f64 * (0.6 + 0.7 * progress);

    // Last-chance bin: strongly favor it.
    if fitting_bins_count == 1 {
        score -= 32.0;
    }

    // Mean-residual alignment.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.12;

    // Dead-space pressure.
    let dead_space = (bin_residual - post_residual) as f64;
    if bin_residual > 0 {
        let dead_ratio = dead_space / bin_residual as f64;
        score -= 3.0 * dead_ratio * dead_ratio;
    }

    // Many open bins: prefer bins that can still host the next item.
    if open_bins_count > 8 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
