    // near-perfect multiples/complements of the current item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 { score -= 4.0 * (fill_ratio - 0.85) * 6.6; }
    if bin_residual == item_size { score -= 6.0; }
    if post_residual > 0 && item_size >= bin_residual {
