pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness: reward filling a large fraction of the bin's current residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Graded dead-space penalty (quadratic).
    let dead_space = (bin_residual - post_residual) as f64;
    let dead_ratio = if bin_residual > 0 { dead_space / bin_residual as f64 } else { 0.0 };
    score -= 4.0 * dead_ratio * dead_ratio;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 { score += (usable_dead - 0.5) as f64 * 8.0; }

    // Small unusable gaps penalized sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 2.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 28.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fills rewarded strongly.
    if post_residual == 0 {
        score -= 50.0;
        if progress > 0.5 { score -= 8.0; }
    }

    // Next-item lookahead with slack analysis.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 { score -= 10.0; }
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 { score -= 8.0; }
            else if slack_after > 0 && slack_after < 12 {
                score += slack_after as f64 * 0.8;
            } else {
                if slack_after >= 2 * next_item_size { score -= 3.0; }
                if slack_after % next_item_size == 0 { score -= 4.0; }
            }
            if next_item_size > 60 { score -= 5.0; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

