        let awkward = next_item_size > 0 && post_residual > 0
            && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        if awkward { score -= 12.0; }
        if item_size > 70 { score -= 10.0; }
        if next_item_size > 0 && bin_capacity >= next_item_size
