            score -= 7.0;
        } else if post_residual < 9 {
            score -= 2.0 + (9 - post_residual) as f64 * 0.3;
        } else if post_residual < 20 {
            score += (post_residual - 4) as f64 * 0.35;
        }
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with slack analysis.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 9.0;
            }
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.0;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.0;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if slack_after - next_item_size < 14 {
                    score -= 3.0;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Time horizon: consolidate into nearly-full bins late in stream.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;
    score -= (mean_residual - post_residual as f64).abs() * 0.06;

    // Dead-space pressure (graded, quadratic).
    let dead_space = (bin_residual - post_residual) as f64;
    let dead_ratio = if bin_residual > 0 { dead_space / bin_residual as f64 } else { 0.0 };
    score -= 3.0 * dead_ratio * dead_ratio;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 8.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) < 0.25 * item_size as f64
            || mean_residual < item_size as f64 * 0.5;
        if desperate {
            score -= 60.0;
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64 + progress * 6.0;
            if awkward {
                score -= 10.0 + 0.05 * (post_residual as f64);
            }
            if mean_residual > 30.0 {
                score += 8.0;
            }
            if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size
                && post_residual < 2 * next_item_size {
                score -= 7.0;
            }
            if item_size > 70 {
                score -= 10.0;
            }
        }
        if tight && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
    } else {
        // Fragmentation guard on open bins.
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
    }

    // Mild late-stream alignment with mean residual.
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;

    // Many open bins: prefer bins whose leftover is just under next item (dead space).
    if open_bins_count > 8 && post_residual > 0 && post_residual <= next_item_size.max(1) {
        score -= 1.5;
    }
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= ((post_residual - next_item_size) as f64).min(30.0) * 0.10;
    }

    score
}

