pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if is_new_bin {
        // New-bin candidate: only attractive when no reasonable fit exists.
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual)
            || (fitting_bins_count > 0 && fitting_bins_count <= 2);
        if good_fit_exists {
            score += 55.0 + 10.0 * (1.0 - progress);
        } else {
            // poor fit everywhere: opening a fresh bin is fine
            score -= 12.0 + progress * 8.0;
            if open_bins_count > 6 { score += 6.0; } // too many open bins: don't fragment more
        }
        if fitting_bins_count == 0 { score -= 100.0; }
        if item_size > 70 && open_bins_count > 3 { score += 8.0; } // big items: keep them on fresh space
        return score;
    }

    // Dead-space avoidance: penalize small unusable gaps, scaled by progress.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 55.0 * (1.0 + progress * 0.5);
        } else if post_residual < 20 {
            score += 22.0 * (1.0 - (post_residual as f64) / 20.0);
        }
    } else {
        score -= 45.0; // perfect fill
    }

    // Lookahead: dead space is worse if it cannot host the next item.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.55;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 { score -= 8.0; }
            else if slack_after > 0 && slack_after < 6 { score += 3.5; } // tiny new gap: bad
            if slack_after >= next_item_size { score -= 4.0; } // room for another same item
            if post_residual % next_item_size == 0 { score -= 6.0; }
            if next_item_size > 60 { score -= 4.0; }
        }
    } else {
        score -= 15.0;
    }

    // Tightness: reward filling a large fraction of the bin's current residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 9.0 * tightness;

    // Open-bin pressure: compact when many bins are open, stronger early.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 32.0;
    } else if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // Mean-residual alignment: prefer bins tracking the average, gently.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.12;

    // Fullness bonus: bins that are nearly full should be closed out.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_frac * progress;

    // Graded dead-space pressure relative to bin residual.
    let dead_space = (bin_residual - post_residual) as f64;
    if bin_residual > 0 {
        let dead_ratio = dead_space / bin_residual as f64;
        score -= 3.0 * dead_ratio * dead_ratio;
    }

    score
}

