}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Modulo-banded dead-space shaping (borrowed idea): reward residuals near multiples of 25.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 40.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.6;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.6;
    } else {
        score += 2.0 + q as f64;
    }

    // Harsh penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Next-item lookahead: reward exact/near-exact future fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 9.0;
            }
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 {
                score -= 8.0;
            } else if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.1;
            }
            if slack_after >= next_item_size {
                score -= 4.5;
                if slack_after % next_item_size == 0 {
                    score -= 4.0;
                }
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.9;
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: compact more aggressively as stream progresses.
    score += open_bins_count as f64 * (0.6 + 0.9 * progress);

    // Last-chance bin: strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean-residual alignment with progress-scaled weight.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15 * (1.0 + 0.5 * progress);

    // Tightness reward: filling a bin deeply is good.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if is_new_bin {
        // New-bin candidate: only attractive when existing fits are poor.
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size) < 22);
        let awkward = post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        if good_fit_exists {
            score += 45.0;
        } else if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            let base = 8.0 + 6.0 * progress;
            if awkward {
                score -= base + 10.0;
            } else {
                score += 20.0;
            }
        }
        if open_bins_count > 6 {
            score += 4.0;
        }
        if item_size > 70 && fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
