    }

    // --- Existing bin scoring with lookahead on post-fit slack ---
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small dead space: strongly penalize, it is likely wasted.
        score += 60.0 - (post_residual as f64) * 1.2;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward, especially with clean slack.
            let slack_after = post_residual - next_item_size;
            score -= 12.0;
            if slack_after == 0 {
                score -= 8.0; // perfect chain
            } else if slack_after < 6 {
                score -= 4.0;
            } else if slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after % next_item_size.max(1) == 0 {
                score -= 4.5; // divisible slack packs perfectly later
