            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
        } else if post_residual > 0 {
            // Next item cannot fit: penalize proportionally, worse early.
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.3 * (1.0 - progress));
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

