        score -= 7.0;
    } else if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Lookahead: how well the next item fits into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
