        let awkward = fitting_bins_count > 0
            && next_item_size > 0
            && post_residual > 0
            && post_residual < next_item_size
            && post_residual <= (bin_capacity / 4).max(10);
        if awkward || fitting_bins_count == 0 {
            score -= 12.0 + 0.05 * post_residual as f64;
        } else if good_fit_exists {
            score += 45.0;
        } else {
            score += 8.0 + progress * 6.0;
        }
        if item_size > 70 {
            score -= 6.0;
        }
        if open_bins_count > 6 {
            score += 4.0;
        }
    } else {
        // Fragility bonus: tiny residuals are near-wasted space.
        if post_residual > 0 && post_residual < 6 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) >= next_item_size {
            score -= 2.0;
        }
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
