pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // If post_residual can still fit the next item, mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Penalize dead space: post_residual too small to ever fit next item (min size 1).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else is good.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins tighter than average (below mean residual) to consolidate waste.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer bins with small residual overall (best-fit flavor).
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
