            } else if slack_after < 14 {
                score += slack_after as f64 * 1.1; // avoid creating new slivers
            } else {
                score -= 2.5;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
