    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity.max(1) as f64);

    // Mean-residual drift penalty (softened with progress).
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;

    // Open-bin pressure: early on, discourage spreading; later, compact harder.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
