        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
