    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that cannot fit even a minimal item.
    if post_residual < 1 {
        score += 50.0;
    } else if post_residual < 10 {
        score += 8.0;
