    // Lookahead: if the next item fits into the post-residual, reward;
    // if not, penalize leaving a moderately large unusable gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when
    // existing fits are poor (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if poor_fit && open_bins_count > 0 {
