pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by integer division thresholds
    let pr = post_residual;
    let class = pr / 10; // 0..10 classes on capacity 100

    // Dead-space penalty: residuals that are "odd" harmonic classes (poorly reusable)
    // Classes 1,3 (11-39) are awkward: too big to waste, too small for typical items
    match class {
        0 => score -= 30.0,                       // perfect fit
        1 => score += 12.0,                       // 10-19: bad dead zone
        2 => score -= 5.0,                        // 20-29: decent for small items
        3 => score += 10.0,                       // 30-39: awkward
        4 => score -= 8.0,                        // 40-49: good
        5 => score -= 3.0,                        // 50-59
        6 => score += 2.0,                        // 60-69: only useful early
        7 => score -= 6.0,                        // 70-79: large item fits
        _ => {}                                   // 80-100: nearly empty bin
    }

    // Modulo coupling: residuals divisible by common item sizes are more reusable
    if pr > 0 {
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                score -= 6.0;
                break;
            }
        }
        // Odd residuals are harder to fill exactly
        if pr % 2 == 1 {
            score += 3.0;
        }
    }

    // Lookahead: does next item fit in post residual? Strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        // exact or near-exact lookahead fit
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit: this placement creates a bin that must be closed
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // cheaper to open new bin when few bins fit the item or open bins are full-ish
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        let pressure = mean_residual / bin_capacity as f64;
        score -= pressure * 15.0;
        // late in stream, prefer reusing existing bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 10.0;
    }

    // Prefer tight fits generally: reward small post residual relative to capacity
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Fragmentation guard: penalize when post residual is below smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Open bins count pressure: many open bins -> favor consolidating into fuller bins
    if open_bins_count > 4 {
        score += post_residual as f64 * 0.15;
    }

    score
}

