            // practically dead space
            score += (10.0 - gap) * 12.0;
        } else if gap < 25.0 {
            // risky small gap: only fits very small future items
            score += (25.0 - gap) * 4.0;
        } else if gap < 45.0 {
            score += (45.0 - gap) * 1.2;
        }
