    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few bins, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmenting).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here
    // is bad. Penalize the empty-bin candidate mildly so existing bins are preferred
    // unless they leave terrible gaps.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.0;
        // if next item is large, having a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if post_residual can still fit the next item, reward;
    // if post_residual is smaller than next item but nonzero, it's trapped space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
