            score += 6.0;
        }
        // If the next item fits exactly into post_residual, big bonus (chained fit)
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Slight preference early in the stream to keep bins tight (build good structure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Prefer bins with below-mean residual to balance bin loads
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

