        }
    } else {
        score -= 20.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    score -= (mean_residual - post_residual as f64).abs() * 0.06;

    // dead-space pressure (graded)
    let dead_space = (bin_residual - post_residual) as f64;
    let dead_ratio = if bin_residual > 0 { dead_space / bin_residual as f64 } else { 0.0 };
    score -= 3.0 * dead_ratio * dead_ratio;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.50 { score += (usable_dead - 0.50) as f64 * 9.5; }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
    }
    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight { score -= 10.0 + 0.05 * (post_residual as f64); }
        else { score += 14.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 { score -= 6.0; }
        if progress > 0.7 && awkward { score -= 2.5; }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 { score += 3.0; }
        if item_size > 70 { score -= 10.0; }
        if fitting_bins_count > 0 && mean_residual > 30.0 { score += 8.0; }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 { score += 5.0; }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size { score -= 7.0; }
        if open_bins_count > 4 && post_residual >= next_item_size { score += 2.0; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 { score -= 4.0; }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 { score -= 6.0; }
        if avg_res > 45.0 && item_size < 30 { score += 5.0; }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 { score += 6.0; }
        if progress > 0.75 && fitting_bins_count > 0 { score += 4.0; }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit { score -= 2.0; }
        }
        if progress > 0.6 && post_residual < 10 { score -= (10 - post_residual) as f64 * 0.35; }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 { score -= 1.0 * (1.0 - progress); }
    }

    if open_bins_count > 8 && post_residual > 0 && post_residual <= next_item_size.max(1) {
        score -= 1.5;
    }
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= ((post_residual - next_item_size) as f64).min(30.0) * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        if diff == 0.0 {
            score -= 60.0; // ideal: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // Next item still fits here; reward tighter couplings.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize dead space unless residual is near zero.
            let dead = post / bin_capacity as f64;
            score += 20.0 * dead * dead;
            // Small leftovers (<=10) are nearly perfect closures; soften penalty.
            if post_residual <= 10 {
                score -= 15.0;
            }
        }
    }

    // Relative-to-mean adjustment: prefer bins tighter than the average residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in the stream, mildly discourage hoarding many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early when open bins are slack.
        let slack = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = bin_capacity as f64 - 10.0 * (1.0 - progress) - 30.0 * slack;
        // Never open a new bin if a perfect lookahead match exists elsewhere;
        // make new bin expensive when it would leave a large unusable gap.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 10 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space shaping: reward residuals near multiples of 25, punish tiny gaps.
    if post_residual == 0 {
        score -= 18.0;
    } else {
        let r = post_residual % 25;
        if r <= 5 {
            score -= (5 - r) as f64 * 1.55;
        } else if r >= 20 {
            score -= (r - 20) as f64 * 1.55;
        } else {
            score += 3.0 + (post_residual / 25) as f64;
        }
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Tightness reward: filling a bin well is good.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Next-item lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 { score -= 10.0; }
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 { score -= 8.0; }
            if slack_after >= next_item_size { score -= 5.0; }
            if slack_after >= 2 * next_item_size { score -= 3.0; }
            if slack_after > 0 && slack_after < 6 { score -= 4.0; }
            if slack_after > 0 && slack_after < 14 { score += slack_after as f64 * 1.15; }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 { score -= (k_fits.min(3) as f64) * 1.8; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Open-bin pressure: compact into existing bins.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean-residual alignment.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15 * (1.0 - progress);

    if is_new_bin {
        // New bin: only attractive when no good fit exists.
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual);
        if !good_fit_exists && fitting_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 45.0 + 10.0 * progress;
        }
        // Large items prefer a fresh bin.
        if item_size > 70 { score -= 10.0; }
        // Avoid wasting a fresh bin on items that would leave awkward gaps.
        if next_item_size > 0 && (bin_capacity - post_residual) < next_item_size
            && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
    } else {
        // Fragmentation penalty softened early.
        if post_residual > 0 && post_residual < 6 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
