pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) proportionally to how well the item fills the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 0.9 * fill * (bin_residual as f64);

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post residual too small for typical future items is wasted,
    // but a residual too large means poor packing now.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // tiny unusable sliver
        }
        // Coupling with lookahead: bonus if next item fits the residual exactly-ish.
        if next_item_size > 0 {
            let ns = next_item_size as f64;
            if ns <= pr {
                let waste = pr - ns;
                score -= 0.6 * (pr - waste); // next item fits: reward
                if (waste as u32) == 0 {
                    score -= 300.0; // perfect chain
                }
            } else {
                score += 0.35 * (ns - pr).min(60.0); // next item won't fit here
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded or the fit elsewhere is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.15;
        // Penalize new bins generally; relax penalty late in stream or when crowded.
        let mut nb = 150.0;
        if crowded { nb -= 60.0; }
        if progress > 0.8 { nb -= 25.0; }
        if open_bins_count == 0 { nb = -500.0; }
        score += nb;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // modulated by global mean residual.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.2 * gap;
        score -= 0.1 * (mean_residual - bin_residual as f64).abs().min(50.0);
    }

    // Slight preference for keeping fewer open bins (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 2.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Dead space is worse if it cannot host the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Modular fit bonus: residual divisible by next item is ideal.
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
        let slack_after = post_residual - next_item_size;
        // Penalize small awkward slacks left after placing next item.
        if slack_after > 0 && slack_after < 14 {
            score += slack_after as f64 * 1.15;
        }
        if slack_after >= next_item_size {
            score -= 5.0;
        }
        if slack_after == 0 {
            score -= 8.0;
        }
        let k_fits = slack_after / next_item_size.max(1);
        if k_fits >= 1 {
            score -= (k_fits.min(3) as f64) * 1.8;
        }
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean-residual alignment: prefer bins whose residual tracks the average.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15 * (1.0 - progress);

    // Tightness: favor bins that become nearly full after placement.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // New-bin candidate: only attractive when no good fit exists.
    if is_new_bin {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual);
        if !good_fit_exists && fitting_bins_count > 0 {
            score -= 8.0; // allow opening new bin on poor fits
            // Extra pull toward a fresh bin when the current stream is large
            if item_size > 60 && progress > 0.4 {
                score -= 6.0;
            }
        } else {
            score += 45.0; // discourage opening bins when fits are fine
        }
        // Late-stream: discourage fresh bins slightly less to keep options open.
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    } else {
        // Existing-bin bonus when it can host the next item exactly.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer filling bins tightly (weight post_residual more);
    // late in the stream, small residuals matter even more (dead space).
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * (20.0 + 60.0 * p2 + 40.0 * p3);

    // Smooth penalty for creating residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        // smooth ramp: reward residuals that can accommodate next item
        let margin = (pr - next_item_size as f64) / cap;
        score -= fits_next * (8.0 + 10.0 * margin.max(0.0)) * (0.5 + 0.5 * progress);
        // smooth penalty proportional to wasted capacity relative to next item
        let waste = ((next_item_size as f64 - pr).max(0.0)) / cap;
        score += waste * 30.0 * (1.0 - progress);
    }

    // Last-chance bin: smooth reward when few fitting bins exist
    let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
    score -= 12.0 * scarcity * (1.0 - p2);

    // Penalize bins far below mean residual (poor consolidation) smoothly
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev * 10.0;

    // Mild preference to use existing bins over opening new ones
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 3.0 + 6.0 * (1.0 - progress) - 4.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes
    // into typical small-item sizes (mod 10 classes).
    let post_class = post_residual % 10;
    // Reward post-residuals that are "harmonic": near multiples of 10,
    // i.e., likely to be exactly filled by future items.
    let harmonic_bonus = match post_class {
        0 => 12.0,
        5 => 6.0,
        2 | 8 => 2.0,
        1 | 9 => 1.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: tiny post_residual (< 10) is dead space.
    if post_residual < 10 {
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chainability, scaled by how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize if the next item cannot follow into this bin.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize spreading across too many open bins: prefer filling fewer bins.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: an empty bin is neutral-ish; discourage
    // it unless the fit into this bin would be very poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - harmonic_bonus + 5.0;
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            // Large item into fresh bin is fine.
            score -= 3.0;
        }
    }

    // Tight fit reward: small post_residual relative to item size is good.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 2.0;
    }

    // Late in the stream: push toward closing bins (minimizing residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below the minimum plausible item size) are heavily penalized.
    let min_useful = 10.0f64;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 40.0 + (min_useful - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (almost zero waste).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with open bins pressure: more open bins -> prefer filling
    // existing bins (penalize the new-bin candidate especially).
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 3.5;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item can use the post_residual, reward leaving that
    // much space; otherwise penalize leaving space that matches nothing.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below the mean
    // (pack tightly into already-fragmented bins).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Mild stream progression: later in stream, be more conservative with
    // new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-chain fit gets a strong bonus.
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here after placement: mild reward scaled by closeness.
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize dead space that is too small to be useful.
            score += 8.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
        }
    }

    // Penalize creating small unusable gaps (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Compare against mean residual: prefer filling below-average-residual bins.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, favor consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    // New empty bin candidate: only attractive when nothing else fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 { score -= 18.0; }
    else if r <= 5 { score -= (5 - r) as f64 * 1.55; }
    else if r >= 20 { score -= (r - 20) as f64 * 1.55; }
    else { score += 3.0 + q as f64; }

    if post_residual > 0 && post_residual <= 4 { score -= 7.0; }
    if post_residual >= 5 && post_residual <= 12 { score += (post_residual - 4) as f64 * 0.45; }
    if post_residual > 0 && post_residual < 9 { score -= 2.0 + (9 - post_residual) as f64 * 0.3; }

    // tightness: reward filling a large fraction of the bin's current residual
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 { score -= 10.0; }
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0; }
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 { score += slack_after as f64 * 1.15; }
            if slack_after >= 1 && slack_after <= 22 { score -= 2.5; }
            if slack_after >= next_item_size { score -= 5.0; }
            if slack_after >= next_item_size && (slack_after - next_item_size) < 14 { score -= 3.5; }
            if slack_after >= next_item_size && slack_after % next_item_size == 0 { score -= 4.5; }
            if slack_after > 0 && slack_after < 6 { score -= 4.0; }
            if slack_after >= 2 * next_item_size { score -= 3.0; }
            if slack_after >= 6 && slack_after < next_item_size { score += 2.0; }
            if slack_after == 0 { score -= 8.0; }
            if next_item_size > 60 { score -= 5.0; }
            // lookahead: how many more copies of next item still fit (k-fitting)
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 { score -= (k_fits.min(3) as f64) * 1.8; }
            if k_fits >= 2 && slack_after % next_item_size == 0 { score -= 1.5; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    score -= (mean_residual - post_residual as f64).abs() * 0.06;

    // dead-space pressure (graded)
    let dead_space = (bin_residual - post_residual) as f64;
    let dead_ratio = if bin_residual > 0 { dead_space / bin_residual as f64 } else { 0.0 };
    score -= 3.0 * dead_ratio * dead_ratio;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 { score += (usable_dead - 0.5) as f64 * 9.5; }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
    }
    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight { score -= 10.0 + 0.05 * (post_residual as f64); }
        else { score += 14.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 { score -= 6.0; }
        if progress > 0.7 && awkward { score -= 2.5; }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 { score += 3.0; }
        if item_size > 70 { score -= 10.0; }
        if fitting_bins_count > 0 && mean_residual > 30.0 { score += 8.0; }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 { score += 5.0; }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size { score -= 7.0; }
        if open_bins_count > 4 && post_residual >= next_item_size { score += 2.0; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 { score -= 4.0; }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 { score -= 6.0; }
        if avg_res > 45.0 && item_size < 30 { score += 5.0; }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 { score += 6.0; }
        if progress > 0.75 && fitting_bins_count > 0 { score += 4.0; }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit { score -= 2.0; }
        }
        if progress > 0.6 && post_residual < 10 { score -= (10 - post_residual) as f64 * 0.35; }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 { score -= 1.5 * (1.0 - progress); }
        if dead_space > 0.0 && dead_space < 12.0 { score -= 1.0 * (1.0 - progress); }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 { score -= 1.2 * progress; }
    }

    if open_bins_count > 8 && post_residual > 0 && post_residual <= next_item_size.max(1) {
        score -= 1.5;
    }
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= ((post_residual - next_item_size) as f64).min(30.0) * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 gets a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting space it could have used
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64).min(1.0);

    // Many open bins: discourage opening new ones; encourage using existing capacity.
    let open_f = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when mean residual across bins is large (wasted capacity exists).
        score += 4.0 + 0.6 * open_f + 10.0 * (mean_residual / bin_capacity as f64);
        // But late in the stream with fragmented bins, opening fresh may be fine.
        score -= 4.0 * progress;
    } else {
        // Using an open bin is rewarded proportionally to how full it already is.
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor) with coupling.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
