    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-ish coupling)
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead coupling: penalize if post_residual can't fit next item (quadratic in gap)
    if next_item_size > 0 {
        let gap = norm_next - norm_pr;
        if gap > 0.0 {
            score += 25.0 * gap * gap * (1.0 + progress);
        } else {
            // next item fits: reward, scaled by how well it fills
            score -= 15.0 * (-gap) * (1.0 - progress);
        }
    }

