    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln() * (1.0 - norm_pr);
    }

    // Penalize bins far below mean residual (creates fragmentation asymmetry)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin early, more later
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
        // allow new bin if current item is huge relative to mean residual
        score -= 25.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 { score -= 18.0; }
    else if r <= 5 { score -= (5 - r) as f64 * 1.55; }
    else if r >= 20 { score -= (r - 20) as f64 * 1.55; }
    else { score += 3.0 + q as f64; }

    if post_residual > 0 && post_residual <= 4 { score -= 7.0; }
    if post_residual > 0 && post_residual < 9 { score -= 2.0 + (9 - post_residual) as f64 * 0.3; }

    // tightness: reward filling a large fraction of the bin's current residual
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 { score -= 10.0; }
            if (post_residual / 20) == (next_item_size / 20) { score -= 6.0; }
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 { score += slack_after as f64 * 1.15; }
            if slack_after >= 1 && slack_after <= 22 { score -= 2.5; }
            if slack_after >= next_item_size { score -= 5.0; }
            if slack_after >= next_item_size && (slack_after - next_item_size) < 14 { score -= 3.5; }
            if slack_after >= next_item_size && slack_after % next_item_size == 0 { score -= 4.5; }
            if slack_after > 0 && slack_after < 6 { score -= 4.0; }
            if slack_after >= 2 * next_item_size { score -= 3.0; }
            if slack_after >= 6 && slack_after < next_item_size { score += 2.0; }
            if slack_after == 0 { score -= 8.0; }
            if next_item_size > 60 { score -= 5.0; }
            // lookahead: how many copies of next item still fit after placement
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 { score -= (k_fits.min(3) as f64) * 1.8; }
            if k_fits >= 2 && slack_after % next_item_size == 0 { score -= 1.5; }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // dead-space pressure (graded)
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 { score += (usable_dead - 0.5) as f64 * 9.5; }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
    }
    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size
            && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight { score -= 10.0 + 0.05 * (post_residual as f64); }
        else { score += 14.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 { score -= 6.0; }
        if progress > 0.7 && awkward { score -= 2.5; }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 { score += 3.0; }
        if item_size > 70 { score -= 10.0; }
        if fitting_bins_count > 0 && mean_residual > 30.0 { score += 8.0; }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 { score += 5.0; }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size { score -= 7.0; }
        if open_bins_count > 4 && post_residual >= next_item_size { score += 2.0; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 { score -= 4.0; }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 { score -= 6.0; }
        if avg_res > 45.0 && item_size < 30 { score += 5.0; }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 { score += 6.0; }
        if progress > 0.75 && fitting_bins_count > 0 { score += 4.0; }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit { score -= 2.0; }
        }
        if progress > 0.6 && post_residual < 10 { score -= (10 - post_residual) as f64 * 0.35; }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 { score -= 1.5 * (1.0 - progress); }
        if dead_space > 0.0 && dead_space < 12.0 { score -= 1.0 * (1.0 - progress); }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 { score -= 1.2 * progress; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity fraction.
    score = post_residual as f64 * (0.5 + 0.5 * (post_residual as f64 / cap));

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    // Small residuals (<10) are near-perfect fills -> big reward.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    } else {
        // Dead space in awkward mid-range is penalized; modulo-10 class gives
        // finer granularity: residuals near multiples of 10 are "cleaner".
        let r = post_residual % 10;
        let class_bonus = if r == 0 { 12.0 } else if r <= 2 { 8.0 } else if r >= 8 { 5.0 } else { 0.0 };
        score -= class_bonus;
        // Penalize unusable dead space more strongly as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64 - 20.0) * 0.15 * progress;
    }

    // Lookahead coupling: does the leftover post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how snugly the next item fits the leftover.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 * snug;
            // Harmonic pairing: post_residual % next_item_size == 0 is ideal tiling.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Leftover can't host the next item -> dead space penalty, worse when tight.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: any placement is fine; just prefer tightest.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin is costly;
    // strongly reward using it unless the fit is terrible.
    if fitting_bins_count == 1 {
        let fit_quality = post_residual as f64 / cap;
        score -= 35.0 * (1.0 - fit_quality);
        if post_residual < 30 {
            score -= 20.0;
        }
    }

    // New-bin candidate: only attractive when the item is large and no open bin
    // offers a decent fit; make empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        // New bins are good for big items (leave useful large residual structure)
        // and when open bins are few/fragmented (high mean residual spread).
        let fragmentation = (mean_residual - post_residual as f64).abs() / cap;
        score -= 30.0 * large_item;
        score += 18.0 * (1.0 - large_item);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fragmentation > 0.5 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to items seen.
    let density = open_bins_count as f64 / (step_index as f64 + 1.0);
    score += density * 4.0;

    // Mean-residual coupling: placing into a bin far below mean residual
    // (i.e., consuming a very full bin) is efficient.
    let fullness = 1.0 - bin_residual as f64 / cap;
    score -= 10.0 * fullness * fullness;

    // Integer-division threshold on post_residual: quantized tiers.
    let tier = post_residual / 25; // 0..=4
    score += tier as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving gaps that can fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (good packing).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in stream, prefer tighter fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1e-9 {
            score -= 60.0; // perfect 2-chain: item + next item fill bin exactly
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - nr;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // next item still fits
        } else {
            // next item won't fit here; penalize leaving a gap smaller than next item (dead space)
            let gap = post_residual as f64;
            if gap > 0.0 {
                score += 10.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    } else {
        // last item: just minimize post residual
        score -= 5.0 * fit_ratio;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving below-average residual wastes capacity elsewhere
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit and stream is early/mid
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: neutral post_residual but discourage unless current bins are fragmented
        score += 20.0 * (1.0 - progress);
        if mean_residual >= item_size as f64 {
            score += 15.0; // an open bin could have handled it decently
        }
    }

    // Mild preference for filling nearly-full bins as stream progresses
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Tie-break: fewer open bins is better (compaction)
    score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: small post_residual is good, but avoid tiny slivers
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Perfect-fit bonus: item exactly fills the bin
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space: residuals too small for any plausible future item
    // (items are >= 1, but small residuals below typical item size are wasteful)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item fills the leftover almost exactly
            let gap = post_residual - next_item_size;
            score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // post_residual can't host next item: penalize proportionally
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits even more
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: opening a fresh bin is justified when the item
    // fits poorly everywhere or open bins are crowded with large residuals
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_cost = 18.0;
        // Cheaper to open a bin early in the stream (amortize over many items)
        new_bin_cost *= 0.5 + 1.5 * progress;
        // More expensive when few bins are open (want to consolidate)
        new_bin_cost += 4.0 * (1.0 / (1.0 + open_bins_count as f64));
        // If no open bin fits, opening is attractive; if many fit, discourage
        if fitting_bins_count == 0 {
            new_bin_cost -= 25.0;
        } else {
            new_bin_cost += 10.0 * fitting_bins_count as f64;
        }
        // If mean residual is high, open bins have plenty of room: discourage new bin
        new_bin_cost += 0.15 * mean_residual;
        // Large items prefer fresh bins when they'd leave awkward slivers elsewhere
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 6.0;
        }
        score = new_bin_cost;
    }

    // Mild preference for filling bins that are already well-used (keep few bins active)
    let used_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * used_fraction;

    // Global pressure: when many bins are open, favor consolidation into existing bins
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post residual, with a non-linear polynomial shaping.
    let mut score = norm_post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly (explore); later, penalize
    // them quadratically (tight packing matters more as stream ends).
    let coupling = 1.0 - 0.9 * progress + 1.6 * progress * progress;
    score *= coupling;

    // Cubic interaction: dead space becomes increasingly costly as stream advances.
    score += 0.35 * norm_post * norm_post * norm_post * (0.5 + progress);

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_fit = (pr - nxt) / cap;
            score -= 0.6 * (1.0 - slack_fit) * (1.0 - progress);
        } else {
            // next item won't fit: penalize residual that is "almost" useful
            let gap = (nxt - pr) / cap;
            score += 0.4 * gap * (1.0 - gap);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.2;
    }

    // Compare against mean residual: bins with much larger residual than average
    // are better targets; bins below average waste scarce space.
    let mean_norm = mean_residual / cap;
    score += 0.5 * (mean_norm - norm_post) * (mean_norm - norm_post).max(-2.0).min(2.0) * 0.5;

    // Mild preference for filling bins tighter than the mean, smoothly scaled.
    score -= 0.25 * (norm_post - mean_norm).abs() * (1.0 - norm_post);

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        score = 0.9 + 0.8 * pressure * (1.0 - progress) - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if is_new_bin {
        // New-bin candidate: only attractive when fits are poor or absent.
        if fitting_bins_count == 0 {
            return -1000.0; // must open a bin
        }
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual);
        // For a new bin, post_residual == capacity - item_size; measure leftover quality.
        let leftover = post_residual;
        let awkward = next_item_size > 0 && leftover > 0 && leftover < next_item_size;
        let mut nb = leftover as f64;
        nb += mean_residual * 0.25;
        nb += 2.0 + progress * 8.0;
        if awkward || fitting_bins_count <= 1 {
            nb -= 12.0 + 0.05 * leftover as f64;
        } else if good_fit_exists {
            nb += 40.0; // keep using existing bins when they fit well
        } else {
            nb += 6.0;
        }
        if open_bins_count > 5 && leftover >= next_item_size {
            nb += 5.0; // too many bins open: discourage another
        }
        return nb;
    }

    // Dead-space shaping: reward residuals that tile with next item.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let q = post_residual / 25;
        let r = post_residual % 25;
        if r <= 5 {
            score -= (5 - r) as f64 * 1.5;
        } else if r >= 20 {
            score -= (r - 20) as f64 * 1.5;
        } else {
            score += 3.0 + q as f64;
        }
        if post_residual < 9 {
            score += (9 - post_residual) as f64 * 0.6;
        }
    }

    // Lookahead: next item fits?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after = post_residual - next_item_size;
            score -= 12.0;
            if slack_after == 0 {
                score -= 8.0;
            } else if slack_after < 14 {
                score += slack_after as f64 * 1.1;
            }
            if slack_after >= next_item_size {
                score -= 4.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Open-bin pressure grows over the stream.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly compact into it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual drift penalty, softened late.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15 * (1.0 - 0.5 * progress);

    // Prefer fuller bins as stream progresses.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

