pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction class does the leftover fall into?
    // Classes (of 100): 0 (perfect), 1..=10 (tiny), 11..=30 (small), 31..=50 (medium), >50 (large)
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -40.0 // perfect fit: strong reward
    } else if pr <= 10 {
        -10.0 // near-perfect, still very usable
    } else if pr <= 30 {
        5.0
    } else if pr <= 50 {
        15.0
    } else {
        30.0
    };
    score += class_penalty;

    // Dead-space coupling with lookahead: leftover smaller than next item is wasted
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 12.0 + (next_item_size - pr) as f64 * 0.3;
    }
    // Reward leftovers that exactly accommodate the next item (harmonic chaining)
    if next_item_size > 0 && pr == next_item_size {
        score -= 15.0;
    }

    // Integer-division threshold: residual divisible by common item classes (10s) is reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor filling the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, penalize when many bins are open with space
        score += 20.0 + (open_bins_count as f64) * 2.0;
        // If mean residual across open bins is large, prefer reusing
        if mean_residual > item_size as f64 {
            score += mean_residual * 0.2;
        }
        // If no open bin can fit at all, opening is mandatory
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reusing an existing bin: reward proportional to how full it becomes
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // can never be reused by any item -> hard penalty scaled by gap smallness.
    if post_residual < 10 && post_residual > 0 {
        score += 1000.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 500.0;
    }

    // Penalize leaving gaps that are too small for the lookahead item
    // if the lookahead could otherwise fit here (wasted opportunity).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 50.0;
        }
        // Reward a residual that exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize opening new ones).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        score += 200.0 + 25.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 400.0; // forced new bin
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 150.0;
    }

    // Mild tie-breaking toward fuller bins and tighter residual spread.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 10.0;
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space banding: reward residuals near multiples of 25 (common item sizes).
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 22.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.6;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.6;
    } else {
        score += 2.5 + q as f64;
    }

    // Small unusable fragments are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0 + (10 - post_residual) as f64 * 0.5;
    }

    // Tightness: prefer filling most of the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Lookahead: next-item fit quality.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 9.0;
            }
            let slack_after = post_residual - next_item_size;
            if slack_after == 0 {
                score -= 8.0;
            } else if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.1;
            } else if slack_after >= next_item_size {
                score -= 5.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.9 * (1.0 - 0.5 * progress);
        }
    }

    // Open-bin pressure: compact more as stream progresses.
    score += open_bins_count as f64 * (0.6 + 0.8 * progress) * (1.0 - 0.5 * progress);

    // Mean-residual drift penalty, softened by progress.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.12 * (1.0 - 0.4 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    if is_new_bin {
        // New-bin candidate: base score on how much it would hold.
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        let awkward = post_residual > 0 && next_item_size > 0 && post_residual < next_item_size;
        if awkward || fitting_bins_count <= 1 {
            score -= 10.0 + 0.05 * post_residual as f64;
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size
            && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
    } else {
        // Existing-bin fine tuning.
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        let dead_space = (bin_residual - post_residual) as f64;
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) >= next_item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Exact match is a jackpot; decay quadratically with the gap.
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).powi(3);
        } else {
            // Next item cannot follow here: penalize proportionally to the overshoot.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.8 * miss;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; bonus if stream is early or many bins open.
        score = bin_capacity as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 10.0; // pairing next item with this one in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled.
    score += (post_residual as f64 / cap).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < 20 {
            // small leftover that next item cannot use
            score += 8.0;
        }
        // If next item is huge, prefer leaving a big residual (i.e. a fresh bin).
        if next_item_size >= 70 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: attractive when current residuals are fragmented
    // or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more attractive early (more future to amortize) and when
        // mean residual across open bins is small (fragmented state).
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 18.0 * (1.0 - progress) * (1.0 - fragmentation);
        // But penalize new bin if a decent fit exists elsewhere.
        if post_residual >= 0 && bin_residual == bin_capacity && item_size <= 50 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (fills emptier bins first, keeping large residuals available).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for fewer open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap);
    // Base: prefer low post residual, with non-linear (quadratic) penalty on wasted space.
    let mut score = pr + 12.0 * pr * pr / cap;
    // Smooth coupling of tightness with stream progress: tight fits matter more later.
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);
    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 20.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        // Penalize leaving residual that neither fits next item nor is small.
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }
    // Crowding: with many open bins, favor filling existing ones (penalize new-bin tendency).
    score += 3.0 * (open_bins_count as f64).sqrt() * (pr / cap);
    // Mean-residual coupling: prefer bins below mean residual (denser bins first).
    score += 2.0 * (mean_residual - pr) / cap;
    // New-bin candidate: penalize mildly so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
