pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 60.0 * (10 - post_residual as f64);
    }

    // Reward very tight fits (small post_residual that is still usable).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit here anyway; prefer tight packing now.
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But allow a fresh bin if the item would leave a bad gap in existing bins.
        if post_residual < 10 && post_residual > 0 {
            score -= 35.0;
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fullness;

    // Mean residual coupling: when mean residual is high, prefer tight fits.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Bin can still hold the next item: reward tightness of the gap
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to overshoot
        let over = (next_item_size - post_residual) as f64;
        score += 8.0 * (over / 20.0).min(3.0);
    }

    // Penalize leaving small unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 45.0 - 45.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Slight preference for bins tighter than the mean residual
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream: consolidate, avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
