pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else {
            score += gap * 0.1;
        }
    }
    // If next item cannot fit here, mild penalty when post_residual is small (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: only one fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only prefer a fresh bin when existing fits are terrible.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // Empty bin starts with base score; penalize unless existing bins are wasteful.
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        } else if waste_ratio < 0.15 {
            score += 25.0; // existing bins fit well, avoid opening new bins
        }
        // Early in stream, be more willing to open bins for flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer filling bins that are already relatively full (larger residual usage).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 6.0;

    // Global state coupling: when mean residual is high, prefer consolidating into emptier bins.
    if mean_residual > (item_size as f64) * 1.5 {
        score += 2.0;
    }

    // Many open bins: encourage closing them out (tight fits favored more).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    // Late in stream: prioritize minimizing waste aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, scaled by a smooth progress-dependent weight.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear penalty for awkward residuals (quadratic + cubic coupling).
    score += 18.0 * pr_norm * pr_norm * (1.0 - progress);
    score += 25.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: subtract for small post residual, smoothly.
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: reward if next item fits into post residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (pr as u32) >= next_item_size {
            let fit_quality = 1.0 - ((pr - next_item_size as u32) as f64) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            // Penalize leaving residual just below next item size.
            let gap = (ns - pr) / cap;
            score += 8.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * pr_norm);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * pr_norm * pr_norm;

    // Deviation from mean residual: penalize outliers smoothly.
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // Slight nudge to prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 6.0 * pr_norm * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity-fraction bucket does it land in?
    // Residuals near 0 are good; residuals in "dead zones" (just above small-item
    // sizes) are wasteful. Use integer division thresholds on post_residual.
    let pr = post_residual;
    let dead_zone = if pr == 0 { 0.0 }
        else if pr <= 5 { -6.0 }              // near-perfect fill: strong reward
        else if pr < 10 { 14.0 }              // dead space too small for min item
        else if pr < 20 { 6.0 }               // only fits tiny items
        else if pr < 30 { 0.0 }
        else if pr < 50 { -4.0 }              // fits half-capacity classes
        else if pr < 70 { 3.0 }
        else { -2.0 };                        // roomy bin, still flexible
    score += dead_zone;

    // Modulo-arithmetic coupling: does next_item_size divide into post_residual
    // nicely? Exact fit for the lookahead is a strong signal.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;                    // lookahead exact fit
        } else if pr >= next_item_size {
            let q = pr / next_item_size;      // integer division class
            let r = pr % next_item_size;
            if r == 0 && q >= 1 {
                score -= 12.0;                // lookahead tiles residual exactly
            } else if r <= 5 {
                score -= 7.0;                 // near-tile, small remainder
            } else if r < 10 {
                score += 8.0;                 // creates sub-minimum dead space
            }
        } else {
            score += 10.0;                    // lookahead cannot use this bin anyway
        }
    } else {
        // Last item: only exactness matters.
        if pr > 0 { score += 5.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but relax late in the stream or when
    // many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0
            - 12.0 * progress
            - 0.4 * (open_bins_count.min(50) as f64)
            - (mean_residual - cap * 0.5).clamp(-20.0, 20.0);
        // Exact-fit classes for a fresh bin: item sizes that are divisors of 100.
        if item_size > 0 && bin_capacity % item_size == 0 {
            score -= 10.0;
        }
