    // Prefer tighter fits generally: reward small post_residual relative to item.
    score -= 8.0 * (item_size as f64 / cap);

    // Slight preference for bins below mean residual (fill the emptier-ish ones
    // less; keep large residuals for big future items).
    score += 0.05 * ((bin_residual as f64) - mean_residual).clamp(-30.0, 30.0);

    score
}

