        if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
            score += 1.2 + 2.0 * progress;
        }
        // combined: penalize residual dead-space ratio in open bins
        if post_residual > 0 && (post_residual as f64) < 0.25 * (bin_residual as f64) {
            score += 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (2-step lookahead match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward if next item fits into the leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Penalize leftovers that nearly-but-not-quite fit the next item (wasted tightness).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize creating dead space in the mid-range (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless no open bin truly fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count <= 1
            || (next_item_size > 0 && post_residual == 0);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins with more open bins available (spread load when many bins open).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward (best-fit core)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 6.0;

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score -= item_size as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when existing fits are bad
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
        let early = step_index as f64 / (total_items.max(1) as f64);
        // early phase: opening bins is cheap; late phase: prefer packing into existing
        let new_bin_bonus = 8.0 * (1.0 - early) + 3.0 * pressure.min(3.0);
        // if mean residual of open bins is large, opening a new bin wastes consolidation potential
        score += new_bin_bonus - mean_residual * 0.25;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 4.0; // fresh bin is flexible for the next medium item
        }
    }

    // Crowded state: encourage consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;

    // Slight preference for bins whose residual deviates favorably from the mean
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Time-horizon modulation: as stream progresses, tighten fit emphasis
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: post residual, smoothed with a non-linear penalty on mid-range waste
    let mut score = pr;

    // Non-linear polynomial coupling: penalize post_residual more as stream progresses
    let p = 1.0 + progress;
    score += 30.0 * pr_norm.powf(2.0 * p) * (1.0 + fit_ratio);

    // Tight fit reward: cubic smooth term favoring small post_residual
    score -= 40.0 * (1.0 - pr_norm).powi(3) * fit_ratio;

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 25.0 * last_chance * (1.0 - pr_norm);

    // Lookahead: reward if next item fits in post_residual (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = ((pr - nxt).max(0.0) / cap).powi(2);
        score -= 20.0 * (1.0 - fits) * (nxt / cap);
        // penalize if next item just barely doesn't fit
        let miss = ((nxt - pr).max(0.0) / cap).powi(2);
        score += 15.0 * miss * (1.0 + progress);
    }

    // New-bin candidate: mild penalty, growing with number of open bins and progress
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * progress;
    }

    // Deviation from mean residual: smooth quadratic coupling
    score += 5.0 * ((pr - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if open_bins_count > 8 {
            score += 4.0 * (1.0 - progress);
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
        }
        if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
            score += 1.2 + 2.0 * progress;
        }
        // dead-space ratio penalty: discourage bins whose remaining space is badly fragmented
        let dead_ratio = dead_space / bin_capacity.max(1) as f64;
        if dead_ratio > 0.3 && post_residual > 0 && post_residual < next_item_size.max(1) {
            score += 2.0 * (dead_ratio - 0.3) * 10.0;
        }
        // reward near-perfect fills strongly late in the stream
        if post_residual > 0 && post_residual <= 3 {
            score -= 5.0 * (1.0 - progress);
        }
        // lookahead: prefer bins that can still host the next item exactly
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" multiples
    // of common item sizes are more likely to be filled later.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit, best possible outcome
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        -2.0
    } else {
        8.0 // tiny dead space (< 10) is nearly unusable
    };
    score += harmonic_bonus;

    // Dead-space penalty: quadratic in waste, harsher for small residuals.
    let waste = pr as f64;
    score += 0.02 * waste * waste / (1.0 + waste / 20.0);

    // Lookahead coupling: reward if next item exactly fills the post-residual,
    // penalize if next item cannot fit (forcing another bin anyway).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // harmonic class of the leftover after the next item
            let pr2 = pr - next_item_size;
            score -= match pr2 % 10 {
                0 => 10.0,
                5 => 5.0,
                _ => 0.0,
            };
            score -= (pr2 as f64) * 0.1;
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the
    // item is huge relative to capacity (better alone in a fresh bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 18.0 - 20.0 * fill_ratio; // big items favor fresh bins
        } else {
            score -= 10.0; // no alternative, new bin is fine
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer packing
    // into existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - pr as f64).max(0.0) * 0.5;

    // Mild preference for bins with low residual (tight packing) scaled
    // by how many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are wasted. Penalize unusable gaps super-linearly.
    let min_useful = 10u32; // smallest plausible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0;
    }
    // Penalize the "awkward zone" (residual too small for mid-size items
    // but too large to ignore) with a rising quadratic.
    if post_residual > 0 && post_residual <= 30 {
        let r = post_residual as f64;
        score += (30.0 - r) * (30.0 - r) / 12.0;
    }

    // Reward tight fits (small post_residual) with a bonus.
    let tight_bonus = if post_residual == 0 {
        60.0 // perfect fill
    } else if post_residual <= 5 {
        35.0
    } else if post_residual <= 10 {
        20.0
    } else {
        0.0
    };
    score -= tight_bonus;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (8.0 + 6.0 * progress);
    if bin_residual != bin_capacity {
        score -= bin_pressure;
    } else {
        score += 15.0; // base cost of opening a fresh bin
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 18.0;
    }
    // If next item would NOT fit the post-residual but would fit a fresh bin,
    // slightly discourage hogging a bin with a bad chain.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mean-residual coupling: bins far below mean residual are "emptier"
    // and better targets for filling; bins far above mean are nearly full.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    score
}

