    let mut score = post_residual as f64;

    // Progress through the stream: later steps favor tighter packing
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits (post_residual small relative to capacity)
    let perfect_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
