    // Harmonic class of the leftover space: capacity divided into 8ths.
    let post_class = (post_residual * 8 / bin_capacity.max(1)) as i64; // 0..8
    let next_class = (next_item_size * 8 / bin_capacity.max(1)) as i64; // 0..8

    // Reward if the next item fits exactly into the post-residual class.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 12.0 * (1.0 - slack as f64 / cap);
