        // Next item won't fit here: dead space penalty scaled by class depth
        score += 3.0 + 2.0 * post_class as f64;
    }

    // Integer-division thresholds on post_residual: tiny leftovers are dead space
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 4 {
        score += 15.0; // nearly unusable sliver
    } else if post_residual < quarter / 2 {
        score += 7.0;
    } else if post_residual < quarter {
        score += 2.0;
    } else if post_residual >= bin_capacity / 2 {
        // Keeping a large half-capacity residual is valuable
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but allow it early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 4.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
