pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Relative to mean residual: bins tighter than average are valuable
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * tightness;

    score
}

