pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) — classic best-fit core.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    // (assume min item size ~10; residuals below 10 are pure waste).
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual <= 20 {
        score -= 3.0; // small but reusable slots are valuable
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64) / 100.0;
    }
    // If next item would need almost exactly the post residual, extra reward (perfect chain).
    if next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalty for spreading across too many open bins when residuals are high:
    // prefer consolidating into bins with below-average residual (fuller bins).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 3.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 4.0 + 14.0 * progress;
        // Opening a new bin is attractive if existing residuals are all poor fits
        // (large leftover after placement in any open bin).
        if post_residual == 0 {
            score -= 20.0; // perfect fill from empty bin never hurts
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 6.0 * progress;
    }

    // Mild penalty for using many bins when a tighter option likely exists.
    score += 0.05 * open_bins_count as f64;

    score
}

