    let fill = 1.0 - pr / cap;
    score -= fill * fill * 25.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly by default; relax when it gives a perfect fit
    // or when open bins are fragmented (high mean residual spread).
    if is_new_bin {
        score += 15.0 + 0.1 * open_bins_count as f64;
        if item_size >= bin_residual {
            // unreachable, kept for symmetry
        }
        if pr == 0 {
            score -= 20.0; // perfect fit into a fresh bin
        }
        // If existing bins are fragmented (high mean residual), new bin is more attractive.
        score -= (mean_residual / cap).max(0.0) * 10.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, reward heavily.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.5 * tightness;

    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
