            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 bands capture "usable" chunk sizes.
    let post_mod = post_residual % 10;
    let post_class = post_residual / 10; // 0..=10 harmonic band

    // Penalize residuals that fall into awkward dead-space bands (1..9 mod 10
    // with small absolute value are hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 - (post_residual as f64) * 1.5; // worst: tiny slivers
    } else if post_mod != 0 && post_residual < 30 {
        score += 6.0 - post_mod as f64 * 0.4;
    }

    // Reward residual classes that pair well with common item sizes (multiples of 5/10).
    if post_mod == 0 {
        score -= 8.0;
    } else if post_mod == 5 {
        score -= 4.0;
    }

    // Big empty band (post_residual >= 50) is valuable: keep it if next item can use it.
    if post_class >= 5 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > 0 {
            score += 4.0; // next item won't fit here anyway; preserve bigger bins
        }
    }

    // Lookahead: exact harmonic match between next item and post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fill
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 12.0; // leaves a harmonic residual again
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // item closes bin with awkward leftover
        }
        // Penalize wasting a large-residual bin when next item is large and won't fit.
        if post_residual < next_item_size && post_class >= 4 && next_item_size > 50 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // would leave bad dead space, otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = (open_bins_count as f64) * 0.8;
        score = 45.0 + open_penalty + (1.0 - progress) * 10.0;
