pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Perfect fit for the lookahead item: strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: penalize adding more bins when many are open,
    // but exempt the brand-new empty bin candidate (residual == capacity).
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    } else {
        // New bin: penalize more when few bins are open relative to stream length.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
