    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 25.0; // perfect 2-step match
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Relative to mean residual: prefer bins that tighten residual distribution
    let resid = post_residual as f64;
    let dev = resid - mean_residual;
    score += 0.35 * dev;

    // Penalize unusable slivers (dead space below min item size)
    if resid > 0 && resid < 10.0 {
