    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin wastes much space
    if bin_residual == bin_capacity {
        let waste = mean_residual;
        score += 15.0 + 0.2 * waste;
        if fitting_bins_count <= 2 {
            score -= 10.0;
