    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Global residual pressure: if mean residual is high, prefer bins below mean
    // (consolidate big holes), otherwise prefer near-mean bins.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.5 * diff;

    // Time horizon: early in the stream, be more willing to open new bins for
    // good structure; late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or late-stream pressure is low.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let base = 60.0 + 40.0 * large_item;
        // If item is small and open bins exist, opening a new bin is wasteful.
        score = base - 200.0 * large_item * (1.0 - progress);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 50.0; // room for the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 80.0; // poor alternatives elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.6 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Tightness reward (slightly strengthened vs parent).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if slack_after - next_item_size < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
