    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * progress) - 12.0 * fill * fill * (0.5 + progress);

    // Reward tight fits more aggressively as the stream progresses (quartic term).
    score -= 20.0 * fill.powi(4) * (1.0 + progress);

    // Lookahead: bonus if the residual left can accommodate the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let ratio = if post > 0.0 { (nxt / post).min(2.0) } else { 2.0 };
        // Ideal: next item exactly fills remaining space -> ratio ~ 1.
        score -= 8.0 * (-(ratio - 1.0).powi(2)).exp() * (0.5 + progress);
        // Penalize residual that is too small to ever fit anything useful.
        if post < nxt && post > 0.0 {
            score += 6.0 * (1.0 - post / nxt) * (1.0 + progress);
        }
    }

    // Dead-space penalty: small residuals are wasted capacity (smooth quadratic).
    let dead = (1.0 - post / cap).max(0.0);
    score += 15.0 * dead * (1.0 - dead) * post / cap;

    // Scarcity pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New empty bin candidate: high baseline cost, decreasing with progress,
    // but cheaper when mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        let mut base = 45.0 * (1.0 - 0.6 * progress);
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        base -= 30.0 * (1.0 - mean_fill).powi(2);
        score = base + 5.0;
    }

    score
}

