pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes of 10 units.
    let class = post_residual / 10; // 0..10
    // Dead space penalty grows super-linearly for small residual classes.
    score += match class {
        0 => 0.0,
        1 => 12.0,
        2 => 7.0,
        3 => 4.0,
        4 => 2.0,
        5 => 1.0,
        _ => 0.5,
    };

    // Perfect-fit harmonic reward: post_residual is a divisor of capacity (100).
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 10.0;
    }

    // Exact fill reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item exactly fills the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a residual; penalize bad harmonic class of the
            // chained residual (post_residual - next_item_size).
            let chained = post_residual - next_item_size;
            let chained_class = chained / 10;
            score += chained_class as f64 * 1.5;
            if chained == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (next_item_size as f64).min(post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is huge
    // or the residual class here is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin for very large items that would strand tiny residuals elsewhere.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual is far below the mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold: reward when item size divides capacity harmonically
    // (aligns with standard bin sizes).
    if bin_capacity % item_size == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

