pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to be useful for future items (unusable gap zone).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap is nearly worthless
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0; // marginal gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Exact-fit lookahead: if the next item exactly fills post_residual,
    // heavily reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If next item fits into post_residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; prefer filling existing ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and
        // to how well the item would fit elsewhere.
        score += 30.0 + open_pressure;
        if fitting_bins_count >= 1 {
            score += 40.0;
        }
        // Large items (>= 60) justify a fresh bin more readily.
        if item_size >= 60 {
            score -= 45.0;
        }
    } else {
        // Reward placing into bins with residuals close to mean (balance),
        // but tight fit is already rewarded via post_residual.
        score += open_pressure * 0.1;
    }

    // Early in the stream, be slightly more willing to open bins
    // (more future flexibility); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (already tight), reward using it further.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.5;
    }

    score
}

