        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // New: fine-grained residual fitting — reward near-exact matches to next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // New: dead-space ratio shaping with lookahead — prefer bins whose leftover
        // after placement remains large enough to absorb the following item class.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
        }
        // New: penalize mid-range dead space that is too big for tiny items but
        // too small for the next item (awkward leftover band).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 12 {
            score += 3.0;
        }
        // New: reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero gets a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space too small for anything useful; penalize mildly.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins
    // have plenty of room or we're early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let room_pressure = mean_residual / bin_capacity as f64;
        score += 18.0 + 10.0 * (1.0 - progress) + 15.0 * room_pressure;
    } else {
        // Favor bins whose residual deviates below the mean (consolidate emptier bins? no:
        // prefer filling bins that are already relatively full).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Late in the stream, prioritize closing bins out (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: tight fits rewarded more strongly as stream progresses.
    let norm_pr = pr / cap; // 0..1
    let coupling = 1.0 + progress * (1.0 - norm_pr);
    score -= (cap - pr) * 0.15 * coupling;

    // Penalize large wasted residual quadratically (dead space), scaled by progress.
    score += norm_pr * norm_pr * cap * (0.2 + 0.5 * progress);

    // Lookahead: reward residual that can host next item, smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs();
        score -= (cap - fit_gap.min(cap)) * 0.1;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.3 + 0.4 * progress);
    }

    // New empty bin candidate: penalize mildly unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        score += cap * 0.25 + mean_residual * 0.2 - progress * cap * 0.1;
    }

    // Congestion pressure: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 segments
    let seg = post_residual * 10 / bin_capacity; // 0..=9
    let class_penalty: f64 = match seg {
        0 => -60.0, // perfect fill
        1 => -35.0, // tiny residue, excellent
        2 => -15.0,
        3 => 5.0,
        4 => 10.0,
        5 => 0.0,   // half-empty: flexible
        6 => 8.0,
        7 => 14.0,
        8 => 20.0,
        _ => 28.0,  // nearly full bin but wasted >20: bad dead space
    };
    score += class_penalty;

    // Modulo-4 harmonic coupling: residues divisible by 4 pair well with
    // common small item classes
    if post_residual % 4 == 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain fill
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.7 {
                score -= 20.0;
            } else if frac > 0.4 {
                score -= 8.0;
            }
        } else {
            // next item won't fit: penalize large leftover
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // last item: minimize leftover as hard as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when open bins
    // are very fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + frag * 40.0 - progress * 10.0
            - if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 };
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        }
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Slight preference for bins below mean residual (use the fullest bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.5 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    // Very small leftovers are cheap to tile with tiny items.
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained residual fitting: near-exact match to next item.
            let gap = slack_after;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
            // Awkward leftover band: too big for tiny items, too small for next.
            if post_residual >= 12 {
                score += 3.0;
            }
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        // Fresh-bin base score anchored on usable capacity of the new bin.
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: strongly penalize small unusable gaps.
    let dead_zone = 12.0; // gaps <= 12 are nearly unusable for items (min size 1..100 but typical small)
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit: best possible outcome
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Open-bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (use larger residuals first, keep small-residual bins for small items).
    let res_diff = bin_residual as f64 - mean_residual;
    score += res_diff * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit the post-residual, reward leaving
    // that usable space; otherwise penalize residual sized just below next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // residual blocks next item
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + (open_bins_count as f64) * 0.3;
        // If this item is a last chance or fits poorly elsewhere, new bin is ok.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score += 15.0; // keep the last fitting bin for itself
        }
        // Late in stream, avoid opening bins for small items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover residual exactly
    // accommodates the next item (chained packing), scaled by item size.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 300.0 + item_size as f64;
        } else {
            // Penalize residuals that are close-but-unusable for the next item.
            let near_miss = (diff as f64).min(20.0);
            score += near_miss * 2.0;
        }
    }

    // Dead-space penalty: small nonzero residual that likely can never be used
    // (items are >= 1, but small slivers relative to mean residual are waste).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is already tight relative to the fleet mean.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless no open bin fits,
    // or the current residual is a hopeless sliver.
    if bin_residual == bin_capacity {
        let hopeless = fitting_bins_count == 0
            || (bin_residual - item_size) < next_item_size && (bin_residual - item_size) < 10;
        if hopeless {
            score -= 500.0;
        } else {
            score += 400.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Late in the stream, consolidate: mildly prefer reusing existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * frac * frac; // superlinear penalty on wasted space

    // Lookahead: reward bins whose leftover can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover is usable by next item: reward proportionally to snugness
            let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 * (1.0 - snug);
        } else {
            // leftover too small for next item: penalize dead space, worse if very small
            let dead = post_residual as f64;
            score += 2.0 + 4.0 * (1.0 - dead / bin_capacity as f64);
        }
        // perfect chain: item + next item fills bin exactly
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // but if leftover would be tiny dead space and next item is large, soften
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 6.0;
        }
    }

    // Many open bins with slack: discourage spreading into loose bins,
    // encourage consolidating into bins near mean residual.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // crowding pressure: with many bins open, favor filling existing ones
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 3.0 * t * (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // New-bin candidate: neutral-to-slightly-high baseline so it's only chosen
    // when every open bin would create bad dead space.
    if bin_residual == bin_capacity {
        score = 55.0
            + 3.0 * frac
            - if next_item_size > 0 { 0.0 } else { 20.0 };
        // early in stream, opening bins is cheap and useful
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - t);
        // if the only fitting bin would leave a near-perfect fit, don't open new
        if fitting_bins_count == 1 && post_residual <= 5 {
            score += 15.0;
        }
    }

    // Small global nudge toward bins that become exactly half or fully packed
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual == bin_capacity / 2 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
