pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize leftover space, with a non-linear (quartic-ish) aversion
    // to small dead gaps that can never host typical future items.
    let mut score = post + 6.0 * (post / cap).powi(4) * cap;

    // Smooth coupling of post_residual with stream progress: early on,
    // waste is cheaper (many items remain to fill gaps); late, waste is costly.
    score += 14.0 * (post / cap) * (0.5 + progress) * (1.0 - (post / cap));

    // Reward tight fits: when item nearly fills the bin, subtract a smooth bonus.
    let fill = item / cap;
    score -= 10.0 * fill * fill * (1.0 - (post / cap));

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward strongly (smooth gaussian-like match term).
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        score -= 18.0 * (-0.5 * (diff / 8.0).powi(2));
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // More alternatives -> mild penalty for consuming a scarce resource.
        score += 2.0 * ((fitting_bins_count as f64 - 1.0).ln().max(0.0));
    }

    // New-bin candidate (empty bin): penalize opening bins, more so when
    // other bins fit, and smoothly more as the stream progresses.
    if bin_residual == bin_capacity {
        let penalty = 30.0 + 20.0 * progress
            + if fitting_bins_count > 0 { 15.0 } else { 0.0 };
        score += penalty;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 12.0 * fill * fill;
    }

    // Mild preference for bins whose residual deviates from the mean in a
    // useful way: placing into a bin with residual near item size is ideal.
    let resid_gap = (bin_residual as f64 - item).abs();
    score += 4.0 * (resid_gap / cap);

    // Slight bonus for keeping the number of open bins down.
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

