    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // New mutation: discourage opening a new bin when several open bins can still
        // absorb the item with reasonable slack (wasted-capacity guard).
        if fitting_bins_count >= 2 && post_residual > 0 {
            score += 6.0 + 2.0 * (fitting_bins_count.min(5) as f64);
        }
        // Late-stream: strongly prefer existing bins over new ones.
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 10.0 * progress;
        }
        // Avoid opening a bin whose leftover would strand a big next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < bin_capacity / 10 {
            score += 12.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        // Dead-space ratio shaping: strongly penalize bins that waste capacity on this placement.
        if dead_space > 0.0 && next_item_size > 0 && (dead_space as u32) < next_item_size && post_residual > 0 {
            score += 2.5 * progress;
        }
        // New mutation: reward near-perfect fills more aggressively when many bins open.
        if post_residual == 0 && open_bins_count > 3 {
            score -= 6.0;
        }
        // New mutation: when few fitting bins remain and post residual still fits the
        // next item, tilt harder toward this bin (avoid premature new-bin opening).
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        // New mutation: penalize creating residual just below next_item_size (stranded space).
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && (next_item_size - post_residual) <= 8 {
            score += 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space classes modulo 10 ---
    let pr = post_residual;
    let pr_mod10 = (pr % 10) as f64;
    // Residuals that are multiples of 10 are "harmonic" with common item sizes
    // (items drawn 1..=100 often cluster on multiples of 5/10); reward them.
    if pr == 0 {
        score -= 60.0; // perfect closure: ideal
    } else if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 5 == 0 {
        score -= 12.0;
    } else {
        // Non-harmonic residue: penalize proportionally to distance from
        // nearest multiple of 5 (dead space unlikely to be reused).
        let dist = pr_mod10.min(10.0 - pr_mod10);
        score += dist * 2.0;
    }

    // Integer-division thresholds: how many "typical" small items (<=10) fit.
    let small_fit = pr / 10;
    score -= (small_fit as f64) * 4.0;

    // Lookahead coupling: can next_item_size land exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Exact-fit lookahead is gold.
            if next_item_size == pr {
                score -= 45.0;
            } else {
                let post2 = pr - next_item_size;
                // Reward if the second leftover is again harmonic.
                if post2 % 5 == 0 {
                    score -= 18.0;
                } else {
                    score += (post2 % 5) as f64 * 3.0;
                }
            }
        } else {
            // Next item cannot use this bin's leftover at all: dead space.
            score += 15.0;
        }
    }

    // Fraction of capacity used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the leftover
    // we would leave behind is large and non-harmonic, or few bins fit.
    if bin_residual == bin_capacity {
        // Opening a new bin leaves residual = capacity - item_size.
        let new_pr = bin_capacity - item_size;
        if new_pr % 5 != 0 && new_pr < 30 {
            score += 10.0; // poor future reuse -> discourage new bin
        }
        // Prefer new bin when current open bins are mostly full (low mean residual).
        score += mean_residual * 0.4;
        // Early in the stream, opening fresh bins is cheap and flexible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
        // If many bins already fit the item, discourage proliferation.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    }

    // Slight preference for consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.15;

    // Tiny tie-break toward tighter fits via bin_residual class.
    score += (bin_residual % 10) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are total waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Near-perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize moderately small residuals that few items can use, scaled by stream position.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * (2.0 + 3.0 * progress);
    }

    // Reward bins whose residual is far above mean (absorb slack into roomy bins).
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Lookahead: favor bins where the next item also fits afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open,
    // encourage consolidation when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 60.0 + 15.0 * open_bins_count as f64;
        // But if current item leaves a large residual and no fitting bins exist, opening is fine.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 500.0;
        } else if post_residual as u32 >= next_item_size {
            // next item could also fit here: mild reward proportional to closeness
            let gap = post_residual as f64 - next;
            score -= 100.0 / (1.0 + gap);
        } else {
            // dead space relative to next item: penalize
            let dead = next - post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below mean wastes bin space.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.8 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if item is large relative to capacity and mean residual is small,
        // opening fresh may be justified: reduce penalty.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 && mean_residual < item_size as f64 {
            score -= 200.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 80.0;
        }
    }

    // Late in the stream, prefer consolidating (avoid leaving many near-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that no future item could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small slivers are fine (min item 1)
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 12.0;
            } else {
                score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score -= 0.4 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global residual balance: prefer bins whose residual is below mean (fuller bins).
    score += 0.15 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits poorly everywhere
        // (large post_residual relative to capacity) or few bins fit the item.
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 12.0 - 8.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        // Late in the stream, avoid spreading out.
        score += 6.0 * progress;
    }

    // Time horizon: early on, be more exploratory (slightly favor new bins for diversity).
    score -= 3.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

