pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress) + norm_post.powi(3) * 2.0;

    let mut score = post + poly * cap * 0.5;

    // Penalize creating residuals that neither fit the lookahead item nor stay useful
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        let gap_norm = gap / cap;
        score += gap_norm * cap * (0.3 + 0.7 * progress);
        // Reward when post_residual exactly accommodates the lookahead item
        score -= (1.0 - gap_norm).max(0.0) * cap * 0.4 * (1.0 - progress);
    }

    // Reward tight fits (small post residual relative to what was consumed)
    let tightness = item_size as f64 / res.max(1.0);
    score -= tightness * cap * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Penalize spreading across many open bins when mean residual is already low
    let mean_gap = (post - mean_residual) / cap;
    score += mean_gap * cap * 0.2 * (open_bins_count as f64).sqrt() / 10.0;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit the item
    if bin_residual == bin_capacity {
        let open_penalty = if open_bins_count > 0 { 1.0 } else { 0.0 };
        score += cap * (0.8 + 0.6 * (1.0 - progress)) * open_penalty
            + if fitting_bins_count > 0 { cap * 0.9 } else { 0.0 };
        // A fresh bin is attractive only if it promises low dead space for large items
        score -= (item_size as f64 / cap) * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
