pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals divisible by common item sizes (or small) are more valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Class residual by divisibility with likely item sizes (1..100 range)
    let mut harmonic_bonus = 0.0;
    for m in [5u32, 10, 20, 25, 50].iter() {
        if pr % m == 0 && pr > 0 {
            harmonic_bonus += 15.0 * (m / 5) as f64;
        }
    }
    score -= harmonic_bonus;

    // Dead-space penalty: residual too small to ever fit again (min item 1, but
    // realistically small slivers are useless). Penalize very tiny residuals mildly,
    // and mid-range awkward residuals more.
    if pr > 0 && pr < 10 {
        score += 8.0; // small but nearly useless sliver
    }

    // Fraction-of-capacity class of post residual
    let frac = pr as f64 / cap;
    if frac > 0.0 && frac < 0.1 {
        score += 12.0; // awkward class
    } else if frac >= 0.3 && frac <= 0.7 {
        score -= 10.0; // highly reusable middle class
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it uses the leftover
            let fill = next_item_size as f64 / pr as f64;
            score -= 30.0 * fill;
            // harmonic match: next item leaves another clean residual
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize if we'd be left with a sliver anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless their fit is terrible
        score += 40.0;
        // If many open bins with high mean residual, opening a new bin wastes capacity
        score += (open_bins_count as f64) * 2.0;
        // If mean residual is large, prefer filling existing bins
        score += mean_residual * 0.5;
        // Large items (>= 50) pair well in fresh bins early in the stream
        if item_size >= 50 && step_index < total_items / 2 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Slight preference for fewer open bins overall
    score += open_bins_count as f64 * 0.5;

    // Progress-based tie-breaking: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items as f64;
    score -= tightness * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
