            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // NEW: penalize opening a fresh bin when many open bins still have
        // generous mean residual (dead-space avoidance).
        if open_bins_count > 2 && avg_res > next_item_size as f64 * 1.5 && next_item_size > 0 {
            score += 6.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            // Anticipation: wasted gap between residual and next item class.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // NEW: favor bins whose post-fit residual stays reusable for the
        // following item at least twice (chained lookahead).
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 2.5 * (1.0 - progress);
        }
        // NEW: discourage leaving mid-band waste that fits neither current
        // chain nor next item (dead-space variance reduction).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < (bin_capacity / 4) {
            score += 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * chain;
        } else {
            // Next item cannot use the leftover: penalize large dead space.
            score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);
        }
    } else {
        // Last item: any residual is pure waste; prefer the emptiest bin usage.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes existing residual mass.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual * open_bins_count as f64;
        score = bin_capacity as f64 + waste * 0.05 - 5.0 * progress;
        // If nothing fits well anywhere, allow a new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in the stream, fresh bins are cheap; late, avoid proliferation.
        if open_bins_count as f64 > 8.0 + 10.0 * progress {
            score += 20.0;
        }
    }

    // Prefer bins that are already fairly full (low residual relative to mean).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Mild global pressure: with many open bins, consolidate.
    score += 0.02 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits, stronger as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize mid-range dead space (quartic valley around small residuals)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 18.0 * dead * dead;

    // Lookahead: reward leaving room for the next item, penalize near-miss waste
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            score += 6.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer bins with residuals close to the mean (balance), smooth coupling
    score += 0.15 * (pr - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful" classes
    // (small leftovers that many future items can still fill) are rewarded.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual by integer division into harmonic bands of capacity/10.
    let band = post_residual / (bin_capacity / 10).max(1); // 0..=10
    match band {
        0 => score -= 40.0,                 // tiny leftover: nearly perfect fit
        1 => score -= 15.0,                 // small leftover, still fillable by mid items
        2 => score -= 5.0,
        3 => score += 10.0,                 // awkward mid leftover: dead-space risk
        4 => score += 20.0,
        5 => score += 25.0,                 // half-full leftover: worst harmonic class
        6 => score += 15.0,
        7 => score += 5.0,
        8 => score -= 10.0,                 // large leftover: bin still very usable
        _ => score -= 20.0,
    }

    // Coupling: does next_item_size fit into the post_residual? Reward harmony.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // how harmonically does it pair? leftover after the lookahead item
            let post2 = post_residual - next_item_size;
            let band2 = post2 / (bin_capacity / 10).max(1);
            score -= 30.0 - (band2 as f64) * 2.0;
            if post2 == 0 {
                score -= 60.0; // perfect 2-item chain
            }
        } else {
            // lookahead cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Modulo arithmetic on residual: multiples of common item sizes (10, 20, 25)
    // are "harmonic" leftovers that typical streams fill exactly.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large dead space (big fraction leftover) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // default: fresh bin is mediocre; make it attractive only for bad fits
        score = 0.55 * cap + 20.0 - 30.0 * (1.0 - progress);
        if frac > 0.5 && fitting_bins_count > 0 {
            // existing bins are all bad fits (post_residual > half capacity),
            // opening fresh is competitive
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 25.0; // lookahead won't fit typical open bin -> new bin helps
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Slight tie-break toward bins whose residual is close to item need.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Mean-residual coupling: avoid dumping into bins far from the fleet mean
    // (keeps residual distribution harmonized for future items).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
    }
    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        // New: penalize leaving residuals that cannot host next item but are too large to tile cheaply.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > 12 {
            score += 0.8 + 1.5 * progress;
        }
        // New: reward near-exact fills scaled by item size.
        if post_residual > 0 && post_residual <= 2 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min item size is 1, but tiny gaps rarely usable)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; otherwise mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only allow opening a new bin when all
    // open bins would leave poor dead space, and there are many open bins.
    if bin_residual == bin_capacity {
        let best_alternative_gap = mean_residual;
        let poor_fits = if post_residual < 10 { 1.0 } else { 0.0 };
        // Make new bin unattractive by default, but slightly cheaper when
        // mean residual across open bins is small (nothing useful to fill).
        score += 55.0 - 0.3 * best_alternative_gap - 10.0 * poor_fits;
    }

    // Mild stream-progression term: later in the stream, be slightly more
    // conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
