    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size < post_residual {
            let slack_after_chain = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack_after_chain / bin_capacity as f64);
