    // leaving a residual near the mean keeps future options balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize creating large unusable gaps relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny residual = near-perfect fill
    }
    if post_residual > 60 {
        score += 10.0; // large leftover gap is wasteful
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
