pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Fractional fill of the bin by this item.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly (subtract for high fill).
    score -= 60.0 * fill * fill;

    // Penalize small post-residuals that are likely dead space:
    // residuals too small for typical future items (1..100 unknown).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 15.0; // tiny leftover is fine, nearly perfect fit
    } else {
        // dead space grows quadratically as residual shrinks below ~half capacity
        let r = post_residual as f64;
        if r < 0.5 * bin_capacity as f64 {
            score += 0.35 * (0.5 * bin_capacity as f64 - r);
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
