        score += 30.0;
        // If the item fits poorly everywhere (large item), opening new bin is fine.
        score -= 20.0 * fill;
        // More open bins with large mean residual => reuse them instead.
        score += 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        // Late in the stream, slightly discourage leaving many open bins.
        score += 10.0 * progress;
