            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin lookahead: opening a bin whose leftover can hold the next item too.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // NEW: discourage opening a new bin late when open bins are still roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if post_residual >= next_item_size && post_residual - next_item_size == 0 {
                score -= 1.2 * progress;
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead: penalize bins whose leftover cannot absorb
        // the next item yet wastes a mid-band amount.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // NEW: strong preference for bins that fit both current and next items
        // with near-zero combined slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = pr / cap; // normalized post residual in [0,1]
    let g = progress * progress; // smooth progress term
    score += 12.0 * g * (1.0 - t) * t * 4.0; // interior-weighted smooth bump
    score -= 8.0 * (1.0 - progress) * (t * t * (3.0 - 2.0 * t)); // smoothstep reward early on large leftover

    // Dead-space penalty: quadratic in small post residual relative to capacity
    if t < 0.2 {
        score += 15.0 * (0.2 - t) * (0.2 - t) / 0.04;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * ((nx - pr) / cap);
        }
    }

    // Mean residual deviation: penalize bins far from mean residual
    let dev = (pr - mean_residual).abs();
    score += 3.0 * (dev / cap) * (dev / cap) * 10.0;

    // New-bin candidate: prefer opening a new bin when fit is poor and stream is early
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.5 * cap;
        score -= if poor_fit { 4.0 * (1.0 - progress) } else { -2.0 * progress };
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by
    // integer division into capacity fractions (dead-space classes).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class

    // Penalize leftovers that are too small for typical items (dead space),
    // but reward near-perfect fits (class 0 or 1).
    match class {
        0 => score -= 40.0,                    // perfect / near-perfect fit
        1 => score -= 25.0,                    // small but plausibly usable gap
        2 => score -= 5.0,                     // quarter-ish residual
        3 => score += 8.0,                     // awkward mid gap
        4 => score -= 10.0,                    // half bin: very reusable
        5 => score += 6.0,
        6 => score += 3.0,
        _ => {}                                // large residual: neutral
    }

    // Modulo-arithmetic coupling: does the leftover pair well with the
    // lookahead item? Reward when next_item_size divides into post_residual
    // with a small remainder (harmonic compatibility).
    if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 18.0;                     // exact harmonic pairing
        } else if rem <= eighth {
            score -= 10.0;                     // near-exact pairing
        } else if rem > post_residual / 2 {
            score += 4.0;                      // next item barely fits: bad chain
        }
    } else if next_item_size > post_residual {
        // Leftover can't host the lookahead item; mild penalty scaled by
        // how far off it is, softened when many bins remain open.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.15 / (1.0 + open_bins_count as f64 * 0.1);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // placement would create severe dead space late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (post_residual as f64) < 10.0; // unusable sliver
        if dead && progress > 0.25 && fitting_bins_count > 1 {
            score -= 12.0;                     // fresh bin better than sliver
        } else {
            score += 35.0;                     // prefer reusing open bins
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — completing it is good (reduce fragmentation).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.02;
    }

    // Small tie-break on item size: pack larger items into tighter bins first.
    score += item_size as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded.
        score += 40.0 * (open_bins_count as f64).sqrt() + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        score -= 35.0;
    } else {
        // Mild pressure to fill existing bins rather than spreading out.
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Slight stream-progression adaptation: tighten standards as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
