pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits via non-linear coupling on fill ratio.
    let fill = (item_size as f64) / (bin_capacity as f64);
    let waste = post_residual as f64;
    let waste_ratio = waste / (bin_capacity as f64);
    score += 18.0 * waste_ratio * waste_ratio;          // quadratic dead-space penalty
    score -= 14.0 * fill * fill;                        // reward high fill quadratically

    // Lookahead: penalize residuals that cannot host the next item (blocked bin),
    // reward residuals that can still host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.10 * (next_item_size as f64);
        } else {
            // dead space relative to the next item's demand
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
            // extra penalty if gap is small-but-fatal (just barely unusable)
            if gap < 12.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when the item is large or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let big_item = fill > 0.55;
        let poor_fits = fitting_bins_count == 0
            || (mean_residual - item_size as f64).abs() < 4.0;
        if big_item || poor_fits || crowded > 2.5 {
            score -= 12.0 + 6.0 * fill + 2.0 * crowded + 4.0 * progress;
        } else {
            // discourage scattering small items into fresh bins
            score += 15.0 + 10.0 * (1.0 - fill);
        }
    }

    // Global state coupling: if mean residual is high, prefer bins above the mean
    // (drain the fullest bins first to consolidate empties).
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.12 * dev;

    // Time horizon: late in the stream, tighten packing (reduce tolerance for waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * waste_ratio;

    // Tie-breaker: prefer bins with slightly larger residual when fits are equal
    // (keeps tiny residuals from lingering), unless it's the new-bin candidate.
    if bin_residual < bin_capacity {
        score -= 0.02 * (bin_residual as f64);
    }

    // Mild exploration term: deterministic pseudo-noise from state hash for diversity.
    let h = (item_size as f64 * 13.37 + bin_residual as f64 * 7.77 + step_index as f64 * 3.31) % 1.0;
    score += 0.5 * h - 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (favor tight fits, penalize mid-range waste)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on tolerate waste,
    // later tighten packing by penalizing residual more strongly.
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Interaction: post_residual vs next item size (smooth quadratic gap measure)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let gnorm = gap / cap;
        score += 12.0 * gnorm.abs() * gnorm.abs() * cap - 6.0 * gnorm * cap;
        // exact-fit reward for the lookahead item, smoothly scaled by progress
        let fit_bonus = (-4.0 * gnorm * gnorm / 0.002_f64.max(1e-9)).exp();
        score -= 8.0 * fit_bonus * (0.5 + progress);
    }

    // Last-chance bin: smooth reward decaying with number of fitting bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: penalize bins far from the mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // Crowd control: many open bins -> prefer filling existing ones (smooth in count)
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 20.0 * crowd * norm_pr * cap;

    // Slight preference for larger fills (smaller post residual) via cubic term
    score += 0.01 * (item_size as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
