    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Fine-grained dead-space band shaping (kept from parent, tuned).
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size && dead_space < 2 * next_item_size {
            score -= (2 * next_item_size - dead_space) as f64 * 0.12;
        } else if dead_space < next_item_size && dead_space > 12 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are still roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // NEW: discourage new bins when any open bin can hold both this and next item.
        if next_item_size > 0 && fitting_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 5.0 + 4.0 * progress;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Strong preference for bins that fit both current and next items with near-zero slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // NEW: dead-space ratio diagnostic — penalize bins whose leftover-to-item ratio
        // yields a fragment that will never be reused (mid-band waste).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio > 0.35 && ratio < 0.85 {
                score += (0.85 - ratio) * 6.0 * (0.4 + progress);
            }
        }
        // NEW: reward bins whose post-fit residual keeps a reusable band (>= next item
        // or <= tiny fragment), penalize the un-reusable middle band.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= next_item_size {
                // still reusable, mild extra reward with consolidation pressure.
                score -= 1.5 * progress;
            } else if slack > 8 && slack < next_item_size {
                score += (slack - 8) as f64 * 0.4 * (0.3 + progress);
            }
        }
        // NEW: when many bins are open, extra consolidation pressure on roomy bins.
        if open_bins_count > 5 && post_residual >= (item_size + next_item_size) as u32 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is
    // for common future item sizes. Residuals in [1,100] partitioned by
    // integer-division classes of width 10 (matching the coarse size scale).
    let post_class = (post_residual / 10) as f64;
    // Reward keeping the residual inside a "harmonic" class boundary:
    // exact class edges (post_residual % 10 == 0) are highly reusable.
    let edge_bonus = if post_residual % 10 == 0 && post_residual > 0 {
        12.0
    } else if post_residual % 5 == 0 && post_residual > 0 {
        6.0
    } else {
        0.0
    };
    score -= edge_bonus;

    // Penalize large post_residual lightly (wasted space), but reward tight fits.
    score += 0.05 * post_class * post_class;

    // Modulo coupling with next item: if the next item fits exactly into the
    // post residual, strongly favor this bin (perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item leaves another clean class edge.
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            } else if nxt_post % 5 == 0 {
                score -= 5.0;
            } else {
                score += 2.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    if bin_residual == bin_capacity {
        // Prefer new bin only when no open bin offers a tight fit
        // (i.e. post_residual would be very large) or late in the stream
        // with few open bins. Otherwise penalize so existing bins win.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste > 0.5 {
            score -= 5.0 + 5.0 * (1.0 - progress);
        } else {
            score += 10.0;
        }
    }

    // Mild reward for bins tighter than the current mean residual
    // (keeps residual distribution balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Small penalty on bin sprawl: fewer open bins is generally better.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are dead space; penalize them heavily.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 4.0;
    } else {
        // Reward tight fits (small post_residual) super-linearly.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * tightness * 6.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post_residual accommodates next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is relatively cheap.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * 5.0;

    // New-bin candidate: neutral-ish residual, but penalize slightly more
    // as the stream progresses (fewer chances to consolidate later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 2.0 + progress * 4.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual
    // (fill the emptiest usable bins first to consolidate).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
