pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual), with non-linear sharpening.
    let fit_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fit_frac * fit_frac;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot chain here; penalize wasted residual that likely becomes dead space.
            score += 0.25 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer maximal fill.
        score -= 40.0 * fit_frac;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let waste_frac = waste / (bin_capacity as f64);
        if waste_frac < 0.25 {
            score -= 25.0 * (1.0 - waste_frac * 4.0);
        } else {
            // Poor fit in the only bin: bias toward opening a fresh bin.
            score += 8.0 * waste_frac;
        }
    }

    // New-bin candidate: only attractive when open bins are congested or fits are poor.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).ln1p();
        let mean_tight = 1.0 - (mean_residual / (bin_capacity as f64));
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 6.0 * mean_tight + 4.0 * congestion * (1.0 - progress);
        // Early in the stream, fresh bins are cheap; later, discourage proliferation.
        score += 18.0 * progress * (open_bins_count as f64).sqrt() / 4.0;
    }

    // Prefer bins with residual close to the item size (minimize leftover gap relative to mean state).
    let gap = (bin_residual - item_size) as f64;
    score += 0.10 * (gap - mean_residual).abs();

    // Mild preference for bins with smaller residuals (best-fit flavor) modulated by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * bin_residual as f64;

    score
}

