pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction bands. Residuals in the lowest bands (tiny leftovers)
    // are the most "harmonically resolved" and get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Integer-division threshold classes on post_residual (harmonic bands at
    // 1/8, 1/4, 1/2 of capacity).
    let band = post_residual / (bin_capacity / 8); // 0..=8 class
    match band {
        0 => score -= 12.0,          // near-perfect fit, dead space < 12.5%
        1 => score -= 7.0,           // good band
        2 => score -= 4.0,
        3 => score -= 2.0,
        4 => score += 1.0,           // half-empty: mediocre
        5 => score += 3.0,
        6 => score += 5.0,
        7 => score += 8.0,           // barely used bin
        _ => {}
    }

    // Modulo arithmetic: residuals that are multiples of small harmonics
    // (5, 10) remain divisible by common item sizes, keeping future fits easy.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let npr = post_residual - next_item_size;
            // second-level harmonic band on the two-step residual
            let nband = npr / (bin_capacity / 8);
            score -= 4.0 - (nband as f64);
            if npr % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; slight penalty unless this bin is
            // otherwise attractive
            score += 1.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.25 * (item_size as f64);
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty late in the stream when many bins are open and mean residual
    // is large (fragmentation is high; consolidation beats spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // If mean residual across open bins is small, open bins are nearly
        // full anyway -> a new bin is less bad.
        if mean_residual < 0.15 * cap {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream with fragmented bins, prefer new bin less.
        new_bin_penalty += 0.05 * (open_bins_count as f64) * (1.0 - progress);
        score += new_bin_penalty;
    } else {
        // Mild preference for reusing bins over opening new ones.
        score -= 2.0;
    }

    // Small global pressure: prefer using bins with less residual when many
    // bins are open (best-fit pressure scales with congestion).
    score += 0.02 * (open_bins_count as f64) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small to fit even the smallest plausible
    // item (assume min size ~1, but practically gaps < ~15 are near-dead)
    // is heavily penalized unless it is exactly 0.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 4.0; // strong penalty for tiny gaps
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with open_bins_count: discourage opening new bins when many
    // bins are already open (pressure to consolidate).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bin count.
        score += 25.0 + (open_bins_count as f64) * 6.0;
        // But if no other bin fits, opening is inevitable: soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: reward using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // The remaining gap blocks the next item: mild penalty scaled by gap size.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the "good" direction (placing into larger-than-average residuals keeps
    // small residuals for small items).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Slight late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 11.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained residual fitting: reward near-exact matches to next item.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            // Mid-band slack that can't hold the next item again: mild penalty.
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // NEW: suppress new-bin opening when an existing bin can take the next
        // item exactly after this placement (anticipatory lookahead).
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score += 12.0;
            } else if slack <= 4 {
                score += 6.0;
            }
        }
        // NEW: discourage new bins when open-bin mean residual already fits item.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 7.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            // Anticipation: wasted gap between residual and next item class.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead: penalize bins whose leftover cannot absorb
        // the next item yet wastes a mid-band amount.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // NEW: strong pull toward bins whose dead space is nearly zero (perfect
        // compaction target) — reduces residual variance across bins.
        if dead_space <= 3.0 && post_residual > 0 {
            score -= 4.0 * (1.0 - progress) + 2.0 * progress;
        }
        // NEW: penalize creating dead space in a mid-band that neither fits the
        // next item nor leaves a clean small residual.
        if next_item_size > 0 && dead_space > 8.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
            score += 2.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post-residual can still hold the next item: mild reward scaled by leftover slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.5;
    }
    // Next item cannot use the leftover: penalize dead space relative to mean residual.
    else if next_item_size > 0 {
        score += 20.0 + (post_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Tight fits are good: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 5.0;

    // New-bin candidate: keep it unattractive unless existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        score = 150.0 - mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when plenty of fitting bins exist
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus penalty scaled by open bins and stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 + 2.5 * (open_bins_count as f64) + 10.0 * progress;
        // But if the mean residual across open bins is too small to fit the item,
        // opening a new bin is more attractive: discount the penalty
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // If the next item is large and this bin would remain nearly full, new bin is fine
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 6.0;
        }
    }

    // Mild preference for filling bins with larger residuals when mean residual is high
    score += 0.05 * ((mean_residual - bin_residual as f64).abs());

    // Time horizon coupling: later in the stream, be greedier (minimize post residual harder)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
