pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling: quadratic in normalized post-residual,
    // modulated by stream progress (later => prefer tighter fits more strongly).
    let base = pr as f64;
    let poly = fit_norm * fit_norm * (1.0 - fit_norm) * (2.0 + fit_norm);
    let mut score = base - 12.0 * poly * (0.5 + progress);

    // Reward near-perfect fits more aggressively as stream progresses.
    let tightness = 1.0 - fit_norm;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space below smallest plausible item threshold smoothly.
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += 20.0 * dead * dead * (1.0 + 2.0 * progress);

    // Last-chance bin bonus (only fitting bin) — smooth exponential urgency.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead coupling: favor bins whose post-residual can host next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let usable = if pr >= nx { 1.0 } else { 0.35 };
        score += 0.3 * gap * usable - 4.0 * usable * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    let mr = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (mr - fit_norm).abs() * (1.0 - progress);

    // New-bin candidate: smooth sigmoid gate — open new bin only when
    // item fits poorly in existing bins (high relative post-residual waste).
    if bin_residual == bin_capacity {
        let waste = (pr - item_size as f64) / cap; // = 1 - item/cap
        let gate = 1.0 / (1.0 + (-8.0 * (waste - 0.55)).exp());
        score += 30.0 * gate * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse integer-division classes.
    // Residuals in [0,10) are dead space -> heavily penalized; large residuals fine.
    let post_class = post_residual / 10;
    match post_class {
        0 => score += 40.0,                    // unusable sliver
        1 => score += 12.0,                    // awkward
        2 => score += 4.0,
        3 => score += 0.0,
        _ => score -= 2.0,                     // roomy leftover
    }

    // Perfect fit reward (harmonic residue 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: does the leftover match the next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could fit here: reward tight coupling.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap);
            if post_residual == next_item_size {
                score -= 25.0; // chain perfect fit
            }
        } else {
            // Leftover too small for next item: penalize proportional to waste.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
            // Class mismatch penalty: leftover mod 10 far from next item mod 10
            let lr = (post_residual % 10) as f64;
            let nr = (next_item_size % 10) as f64;
            let d = (lr - nr).abs().min((lr + nr - 10.0).abs());
            score += 1.5 * d;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: prefer bins in well-populated regimes.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates from mean in the "tighter" direction.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let desperation = if fitting_bins_count == 0 { 80.0 } else { 25.0 - 15.0 * progress };
        score += desperation + 0.1 * mean_residual;
    }

    // Mild tie-break: tighter post residual preferred.
    score += 0.05 * post_residual as f64;

    score
}

