        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Combined: prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin lookahead: reject opening a bin whose dead space cannot host the next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 8.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            // Anticipation: wasted gap between residual and next item class.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead: penalize bins whose leftover cannot absorb
        // the next item yet wastes a mid-band amount.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Combined anticipation: mid-band dead space that still fits next item exactly.
        if next_item_size > 0 && post_residual > 0 && dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= 1.8 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post_residual) more strongly over time.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins that are much emptier than average (fragmentation risk),
    // but only mildly early in the stream.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * (0.4 + 0.6 * progress);

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement heavily (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the known next item.
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let best_possible_waste = if fitting_bins_count > 0 {
            // how much waste the best existing fit roughly leaves
            (bin_residual - item_size).abs_diff(item_size) as f64
        } else {
            100.0
        };
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is penalized; penalty shrinks if existing fits are terrible
        // or many bins are already open and mean residual is low.
        let mut penalty = 20.0 + 3.0 * open_pressure.sqrt();
        penalty -= 0.25 * best_possible_waste;
        penalty -= 0.05 * mean_residual;
        score += penalty.max(2.0);
    }

    // Slight preference for filling already-started bins as stream matures.
    if !is_new_bin {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let prn = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - progress) * 8.0;
    score -= poly * 4.0;
    // penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    }
    // reward exact-ish fits
    score -= (1.0 - prn).powi(3) * 2.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }
    // new-bin candidate: prefer only when residuals are large and stream is late
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 5.0 - mean_gap * 10.0 * (1.0 - progress) - progress * 3.0;
    }
    // tightness coupling with item size
    score -= (item_size as f64 / cap) * (1.0 - prn) * 3.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
