pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powf(6.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: reward post_residual in "usable" residue classes
    // (small residues 1..=10 are near-perfect; residues that combine with
    // common item sizes are also good). Penalize dead-space classes.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // classes 0..=5 leave modular-friendly leftovers, 7..9 are awkward
        match class {
            0 => score -= 6.0,
            1 => score -= 8.0,
            2 => score -= 7.0,
            3 => score -= 6.0,
            4 => score -= 5.0,
            5 => score -= 4.0,
            7 => score += 3.0,
            8 => score += 4.0,
            9 => score += 5.0,
            _ => {}
        }
        // Integer-division threshold: residual that can't host the smallest
        // plausible future item is dead space
        if pr < 10 {
            score += 12.0; // tiny unusable sliver
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // open bins exist and fit is decent. Make the empty-bin score
    // unattractive unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: residual left = capacity - item
        score += 30.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is correct
        }
    } else {
        // penalize bins that are already much emptier than average
        // (prefer filling fuller bins first, preserving flexibility)
        if (bin_residual as f64) > mean_residual * 1.25 {
            score += 10.0;
        }
    }

    // Mild late-stream bias: consolidate more aggressively toward the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

