    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_use = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * gap_use;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't use the gap -> dead space likely.
        score += 12.0;
