pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large residuals that waste space
            score += 0.15 * post_residual as f64 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last chance: this is the only bin that can fit the item — strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Penalize the empty-bin call proportionally to how much capacity is
    // already idle across open bins.
    if bin_residual == bin_capacity {
        let idle = mean_residual * open_bins_count as f64;
        score += 30.0 + 0.5 * idle;
        if item_size <= 40 {
            score += 10.0; // small items should go into existing slack
        }
        // Early in the stream, allow new bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins whose residual is already small relative to fleet mean
    // (consolidate leftovers into few bins).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild pressure to keep open-bin count low as the stream progresses.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_term = progress * progress * (1.0 - progress);
    let coupling = norm_pr * (1.0 + 2.0 * progress_term);

    let mut score = coupling * cap;

    // Penalize dead space quadratically, modulated by progress
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * cap * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= cap * 0.4;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.25 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.5;
        }
    }

    // Mild penalty for spreading across many bins late in stream
    score += open_bins_count as f64 * 0.05 * progress;

    // Distance from mean residual
    score += (pr - mean_residual).abs() * 0.1;

    score
}

