        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead: penalize bins whose leftover cannot absorb the next item.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Strong preference for bins that fit both current and next items with near-zero combined slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // NEW: triple-fit lookahead — reward bins whose residual can hold the next item
        // at least twice with exact division, i.e. clean multiplicative reuse.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
            score -= 3.5 * (1.0 - progress);
        }
        // NEW: dead-space ratio refinement — penalize mid-band waste scaled by how much
        // the bin residual exceeds the mean (bins drifting from the pack norm).
        if post_residual > 0 && dead_space > next_item_size as f64 && dead_space < 0.35 * bin_capacity as f64 {
            score += 0.08 * (dead_space - next_item_size as f64) * (0.5 + progress);
        }
        // NEW: reward bins whose post-fit residual sits in the "small but reusable" band
