pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual that is too small to hold
    // anything useful (items are >= 1, but a tiny gap is effectively dead space).
    // A gap below ~15 units is likely dead unless the next item is tiny.
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Extra penalty if the dead space cannot even hold the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Reward when this bin's post_residual exactly accommodates the next item
    // (a perfect two-item chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
