    // Open-bins pressure: penalize adding to a bin when many bins are already open
    // (prefer consolidating into fewer bins), but only mildly so it doesn't
    // override fit quality.
    score += (open_bins_count as f64) * 0.05;

    // Slight penalty when this bin's residual is far below the mean residual
    // (it's already nearly full; better to fill bins with more room when fits are equal).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // (bin_capacity - item_size). Make new bins attractive only when the item
    // is large relative to capacity, or when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Waste if the item goes into a fresh bin.
        let waste = (bin_capacity - item_size) as f64;
        // Base cost of opening a new bin, reduced for large items.
        score = 60.0 + waste * 0.5;
        // If many bins fit the item, opening a new bin is rarely justified.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If this is the last chance (only fitting bin is... none other), opening
        // a new bin is fine, so no extra penalty. But if other bins fit, discourage.
        if fitting_bins_count >= 1 {
            score += (fitting_bins_count as f64) * 2.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: this item's leftover exactly fits the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize very small unusable leftovers (dead space), but not exact next-item fits.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Mild penalty for opening a new bin when open bins exist that fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        let waste = post_residual as f64 - next_item_size as f64;
        if waste > 0.0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += crowd * 3.0;

    // Deviation from mean residual: prefer bins whose residual is below mean (more filled)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // New-bin candidate logic: opening a new bin is only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so new bins are chosen only on merit
        score += 20.0;
        // late in stream or when the item is large relative to capacity, allow new bins
        if item_size > 60 || progress > 0.7 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 12.0;
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild reward for filling large items into emptier bins early on
    if progress < 0.3 {
        score -= (item_size as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual via non-linear coupling
    let pr = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - pr).powi(3);

    // Penalize post_residual close to unusable dead space relative to smallest items
    score += 0.35 * pr * pr * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 12.0 * snug;
    } else if next_item_size > post_residual {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly encourage using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins early, less so late;
    // also penalize proportionally to how many bins are already open
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * (1.0 - progress) + open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (consolidate fuller bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Smooth stream-progress coupling: earlier, prefer filling; later, prefer flexibility
    score += 8.0 * progress * pr * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and mod 25.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;

    // Penalize residues that are hard to fill later (small nonzero leftovers).
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space: nothing in [1,100] range reliably fills
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    } else if pr >= 20 && pr < 30 {
        score += 3.0;
    }

    // Reward perfect / near-perfect fits.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 10.0;
    }

    // Modulo-coupling: if next item can exactly fill post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if pr < next_item_size {
            score += 5.0; // next item won't fit here; residual becomes dead
        }
        // Harmonic class of next item size mod 10
        let nclass = (next_item_size % 10) as f64;
        score -= (10.0 - nclass) * 0.4;
    } else {
        // Last item: prefer tightest fit regardless.
        score = pr as f64;
        return score;
    }

    // Integer-division thresholds on post_residual (quarters of capacity).
    let quarter = bin_capacity / 4;
    if pr <= quarter {
        score += 6.0;
    } else if pr <= 2 * quarter {
        score += 1.0;
    } else if pr >= 3 * quarter {
        score -= 6.0;
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless
    // current residuals are all poor (high mean residual spread).
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= (mean_residual - 25.0).max(0.0) * 0.5;
    }

    // Fractional residual alignment: penalize class10 vs class25 mismatch.
    score += (class10 - class25 / 2.5).abs() * 0.3;

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (1..=8) are "dead" — penalize harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space coupling with lookahead: if the next item can't use the
    // post-residual gap, that gap is likely wasted forever.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins early;
    // encourage packing into existing bins when bin count is high.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it less attractive than decent fits, but
    // preferable when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight stream-progression bias: pack tighter as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained residual fitting (combined feature).
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained gap fitting after placing next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Anticipation: prefer bins whose post-residual exactly matches next item's
        // size class, reducing fragmentation across the horizon.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) % next_item_size == 0 {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mildly good
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot use leftover: penalize dead space proportionally
            score += 80.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean residual coupling
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual > item_size as f64;
        if decent_fit_exists && waste > 20.0 {
            score += 150.0 + waste;
        }
        // slight bias against new bins late in the stream
        score += 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling tighter (smaller residual) bins slightly more
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64);

    score
}

