        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize wasted residual, with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.35 * progress) - 0.15 * (post * post) / cap;

    // Reward tight fits: small post_residual strongly favored via quadratic bonus.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize residuals too small for the smallest plausible item (dead space).
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post);
    }

    // Lookahead coupling: if next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 15.0;
        } else {
            score += 0.05 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Mean-residual coupling: bins deviating far below mean residual are worse choices.
    score += 0.1 * (post - mean_residual).abs();

    // New-bin candidate: mild penalty so it only wins when fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress - 0.02 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod 10) ---
    // Residuals divisible by 10 are "harmonic": easy to fill with items >=10.
    let harmonic = (post_residual % 10) == 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Penalize awkward remainders: dead space not reachable by small items.
        let awkward = post_residual % 10;
        score += (10 - awkward) as f64 * 0.4;
    }

    // Fractional capacity coupling: post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Prefer bins that become "nearly full" (small frac), but avoid leaving
    // slivers below the minimum item size (assume items >= 1, but typical >= 10).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // unusable sliver penalty
    }

    // Integer division thresholds on post_residual (harmonic bands).
    let band = post_residual / 25; // 0,1,2,3,4
    score += band as f64 * 2.0;    // deeper emptiness -> slightly worse fit

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.15;
        }
        // Harmonic pair: item + next == capacity (perfect closure).
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, tighten competition on residual quality.
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // No open bin really fits: opening a new bin is reasonable.
            score -= 5.0;
        } else {
            // Open bins can absorb the item: discourage new bin.
            score += 25.0 + mean_gap * 0.3;
        }
        // Late in the stream, consolidating matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins: prefer filling them rather than spawning more.
        score += open_bins_count as f64 * 0.8;
    }

    // Reward near-perfect fills (post_residual in harmonic low band).
    if post_residual <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bins pressure: many open bins -> favor consolidating into existing bins,
    // penalize spreading out (higher post_residual already does part of this).
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible, handled by dead-space penalty).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover: mild penalty proportional to gap.
        score += 5.0;
    }

    // New-bin candidate: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "small" bin best consumed now.
    score += ((mean_residual - bin_residual as f64) * 0.15).max(-15.0).min(15.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but weight it more heavily.
    score = 1.5 * post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead = next_item_size as f64;
        if (post_residual as f64 - lookahead).abs() < 1e-9 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tightly it packs
            let tight = 1.0 - (post_residual as f64 - lookahead) / bin_capacity as f64;
            score -= 40.0 * tight * tight;
        } else {
            // next item cannot fit here: penalize leaving a gap it almost fits into
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * gap * (1.0 - gap);
        }
    }

    // Penalize post residuals that are too small to ever be useful (dead space).
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 0.0; // unreachable, kept for clarity
    }
    if post_residual == 0 {
        score -= 30.0; // perfectly closed bin is excellent
    } else if (post_residual as f64) < 10.0 {
        score += 15.0; // tiny unusable sliver is dead space
    }

    // Relative to mean residual: prefer bins with residual above mean (keep big holes for big items),
    // but when this bin's residual is close to item_size, it's a great fit.
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * fit_tightness;

    let mean_dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 5.0 * mean_dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented
    // or the item fits nothing well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual);
        score = 0.5 * bin_capacity as f64 // baseline mid score for empty bin
            + 30.0 * (1.0 - poor_fit)     // large item in fresh bin is fine
            - 10.0 * open_pressure.min(3.0); // many open bins with small residuals => avoid new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open
        }
    }

    // Slight time adaptation: early in stream, be more willing to open bins (score new bins lower).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving a dead zone: residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste of space if next item cannot use the remainder.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let penalty = 20.0 + 30.0 * (1.0 - fragmentation) * (1.0 - progress);
        score += penalty;
        // Large items are fine in fresh bins.
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual (balancing open bins).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure to consolidate as bins accumulate.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: early on, be conservative about tight fits; later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // COMBINED: fine-grained residual gap fitting with lookahead anticipation.
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if gap == 0 {
                score -= 5.0 * progress;
            } else if gap < 5 {
                score -= 3.0 * progress;
            }
            let two_fit = gap >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
            // anticipate: unusable leftover for next item penalized more late
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

