        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // MUTATION: discourage new bins when any open bin can still fit next item too.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        // MUTATION: harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Preference for bins fitting both current and next items with near-zero slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // MUTATION: triple-fit lookahead — reward bins that could hold the next
        // item multiple times, tightening residual reuse.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let rem = post_residual % next_item_size;
            if rem <= 3 {
                score -= 2.5 + (3 - rem) as f64 * 0.8;
            }
        }
        // MUTATION: penalize leaving residuals in the awkward 25..35 band that
        // rarely match future items exactly.
        if post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
            score += 1.5 + 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals in "useful" bands
    // that are likely to be filled by common item sizes (harmonics of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill level of the bin after placement (harmonic fraction).
    let fill = 1.0 - (pr / cap);

    // Reward near-full bins strongly (tight packing priority).
    if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 12.0;
    } else if pr <= 50 {
        score -= 4.0;
    }

    // Modulo-10 harmonic class of post_residual: certain residues pair well
    // with typical item sizes (multiples of 5/10). Penalize odd residues.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0;
    } else if residue_class == 5 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // Partial fit: reward proportional to how much of the gap it fills.
            let gap_fill = next_item_size as f64 / pr;
            score -= 20.0 * gap_fill;
        } else {
            // Next item cannot use this residual at all: penalize large dead space.
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize scattering across many open bins when mean residual is already low.
    if open_bins_count > 4 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (open_bins_count as f64 - mean_residual / 10.0) * (0.3 + 0.7 * progress);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 30.0;
        // But if current bin would leave huge unusable residual, opening is fine.
        if post_residual > 40 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Mild early-stream exploration: prefer filling existing bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress) * (fill - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" is heavily penalized.
    // Dead zone: residual too small to hold any plausible future item (assume min item 1,
    // but practically small gaps below ~10 are hard to reuse).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Lookahead won't fit: penalize proportionally to wasted potential.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 2.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when open bins are underutilized,
    // favored when existing residuals are small (fragmented) and item is large.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0
            + fragmentation * 30.0
            + progress * 10.0
            - (item_size as f64 - 50.0).abs() * 0.1
            + open_bins_count as f64 * 2.0;
        // If the only fitting bin is a last chance, make new bin less attractive.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits (tuned from best heuristic).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting (combined with best's structure).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if slack_after - next_item_size < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;

    // Usable dead-space ratio.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
    }
    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_leftover = post_residual - next_item_size;
        score -= 150.0 - (pair_leftover as f64) * 3.0;
        if pair_leftover == 0 {
            score -= 300.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Penalize if the leftover is so small it becomes dead space for the next item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 80.0;
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are "tight" -> good targets.
    let tightness = mean_residual - bin_residual as f64;
    score -= tightness * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (large post residual).
    if fitting_bins_count == 1 {
        score -= 250.0 + (post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large post_residual here) or many bins are open.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Base cost of opening a new bin.
        score += 400.0;
        // Attractive when the current item is large (little waste risk) or
        // when we have few open bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= item_size as f64 * 3.0;
        score -= (1.0 - progress) * 100.0;
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Penalize spreading across too many open bins when residual is average.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * frac * frac;

    // Lookahead: if the next item can pair into the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space.
            score += 4.0 * frac;
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, unless many bins are open
    // (fragmentation) or residuals are large (room to consolidate elsewhere).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0 + open_bins_count as f64 * 1.5;
        // Early in the stream, opening bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        // If mean residual across open bins is high, opening a new bin is fine.
        new_bin_score -= 0.3 * mean_residual;
        // Perfect-fit bonus: if item exactly fills a fresh bin.
        if item_size == bin_capacity {
            new_bin_score -= 50.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual is closest to item size (best fit flavor).
        let slack = (bin_residual - item_size) as f64;
        score += 0.1 * slack;
        // Slight preference for bins below mean residual (balance load).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, penalized more heavily as the stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth decay term
    score -= 25.0 * (-(pr / 15.0)).exp();

    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: baseline score so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) + 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit style).
    score -= (bin_capacity as f64) * 0.6 / (1.0 + post_residual as f64);

    // Harmonic class of post_residual: residuals in small classes are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction

    // Penalize residuals that fall into awkward harmonic bands.
    // Class 0: pr == 0 -> perfect closure, big reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Modulo classes on post_residual w.r.t. common item-size bands (10..80).
        // Items come in 10..80, so residual mod 10 == 0 keeps alignment with size grid.
        if post_residual % 10 == 0 {
            score -= 4.0; // aligned residual, likely reusable exactly
        }
        // Harmonic half-class: residual exactly half capacity is highly reusable.
        if (post_residual as i32 - bin_capacity as i32 / 2).abs() <= 2 {
            score -= 6.0;
        }
        // Small unusable slivers (pr < 10 can never fit any item) -> strong penalty.
        if post_residual < 10 {
            score += 12.0;
        }
        // Integer-division threshold: dead space when pr < next_item_size but pr >= 10.
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
            score += 3.0;
        }
        // Reward when next item fits exactly into post_residual (perfect chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0;
        }
        // Fractional coupling: penalize residuals in (0.3, 0.5) band - awkward zone.
        if frac > 0.3 && frac < 0.5 {
            score += 2.5;
        }
        // Reward residuals above 0.7 (still roomy, flexible).
        if frac > 0.7 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // Penalize new bins mildly; relax as stream progresses or bins get fragmented.
        score += 8.0 - 6.0 * progress - 2.0 * crowding.min(3.0);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Lookahead harmony: if next item would fit this bin's post-residual within tolerance.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * (post_residual - next_item_size) as f64 / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
