        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Preference for bins fitting both current and next items with near-zero slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // Triple-fit lookahead — reward bins that could hold the next item
        // multiple times, tightening residual reuse.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let rem = post_residual % next_item_size;
            if rem <= 3 {
                score -= 2.5 + (3 - rem) as f64 * 0.8;
            }
        }
        // Penalize leaving residuals in the awkward 25..35 band that
        // rarely match future items exactly.
        if post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
            score += 1.5 + 2.0 * (1.0 - progress);
        }
        // MUTATION: combine dead-space ratio with lookahead — penalize bins whose
        // dead space after placement is neither zero nor reusable by next item.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += (next_item_size - post_residual) as f64 * 0.08 * progress;
        }
        // MUTATION: reward near-perfect fills more strongly as stream progresses,
        // reducing residual variance late.
        if post_residual > 0 && post_residual <= 3 {
            score -= 3.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (or the lookahead item) are "dead space".
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable gap for any item (min size 1..10 regime)
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0; // cannot host the lookahead item
        } else {
            // Tight fits are rewarded: near-exact packing.
            score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead coupling: reward bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, allow more freedom.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (consolidate emptier space usage
    // keeps larger residuals available for larger items).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 + 30.0;
        let discount = if fitting_bins_count == 0 {
            -50.0
        } else if post_residual as f64 / bin_capacity as f64 > 0.6 {
            20.0
        } else {
            0.0
        };
        score = base + discount + pressure;
    }

    score
}

