pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: penalize large post_residual non-linearly.
    if !is_new_bin {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * fit_ratio * fit_ratio;

        // Reward exact / near-exact fills.
        if post_residual == 0 { score -= 60.0; }
        else if post_residual <= 5 { score -= 30.0; }
        else if post_residual < 10 { score -= 12.0; }

        // Penalize leaving a residual that no typical item can use (dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Lookahead: reward if the next item fits into post_residual (chaining).
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 15.0;
            } else {
                // Penalize leaving residual just below next item size (frustration).
                let gap = next_item_size as f64 - post_residual as f64;
                if gap < 10.0 {
                    score += 0.8 * (10.0 - gap);
                }
            }
        }

        // Prefer bins with residuals close to the mean (keep balance), mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;

        // Late in the stream, consolidate aggressively into fewer bins.
        score += progress * 5.0 * open_bins_count as f64 * 0.1;
    } else {
        // New-bin candidate: baseline cost of opening a bin.
        score = bin_capacity as f64 * 0.9;

        // If other bins fit the item, opening a new bin is usually worse.
        if fitting_bins_count > 0 {
            let best_possible_waste = fitting_bins_count as f64;
            score += 30.0 + 10.0 * best_possible_waste;
        }

        // If only this new bin can fit (fitting_bins_count == 0 among open bins),
        // it must be chosen: make its score low.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }

        // Large items early: opening fresh bins is fine; late: discourage.
        score += 40.0 * progress;

        // If the next item is large and this item is small, a fresh bin preserves
        // flexibility for it.
        if next_item_size > 60 && item_size < 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 - p) + norm_pr * p * p;
    score += 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness * (0.5 + p);

    // Penalize leaving dead space smaller than typical item sizes (unusable gap).
    let dead = pr;
    if dead > 0.0 {
        let gap_penalty = (1.0 - dead / cap).max(0.0);
        score += 8.0 * gap_penalty * gap_penalty * (1.0 - p);
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * p);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / cap) * p;
    }

    // Mild preference for consolidating into bins below mean residual early on.
    let mean_dev = (mean_residual - pr) / cap;
    score += 5.0 * mean_dev * (1.0 - p);

    // Many open bins: prefer filling existing ones rather than spreading.
    score += 0.3 * (open_bins_count as f64) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Dead-space ratio.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Fine-grained dead-space band shaping.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        // MUTATION: scale new-bin penalty with how much roomy open bins exist.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 5.0 * (1.0 - progress) * (open_bins_count.min(10) as f64 / 10.0);
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Preference for bins fitting both current and next items with near-zero slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // Triple-fit lookahead with fine remainder shaping.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let rem = post_residual % next_item_size;
            if rem <= 3 {
                score -= 2.5 + (3 - rem) as f64 * 0.8;
            }
        }
        // Penalize leaving residuals in the awkward 25..35 band.
        if post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
            score += 1.5 + 2.0 * (1.0 - progress);
        }
        // MUTATION: combine fine-grained residual fitting with lookahead —
        // reward bins whose post-fit slack is a small multiple of next item size,
        // and penalize slack that wastes more than half the next item's size.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack_after = post_residual - next_item_size;
            let waste = slack_after % next_item_size.max(1);
            if waste > 0 && waste > next_item_size / 2 {
                score += (waste - next_item_size / 2) as f64 * 0.25;
            } else if waste > 0 && waste <= 4 {
                score -= 2.0 + (4 - waste) as f64 * 0.5;
            }
        }
        // MUTATION: dead-space ratio lookahead coupling — prefer bins where
        // remaining dead space after this item stays below mean residual.
        if post_residual > 0 && post_residual as f64 <= mean_residual + 2.0 {
            score -= 1.5 * (1.0 - progress);
        }
        // MUTATION: penalize open bins whose residual is far from any plausible
        // next fit when many bins are open (consolidation pressure).
        if open_bins_count > 4 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 0.8 * (open_bins_count.min(12) as f64 / 12.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small reusable" classes (fits common item bands) are favored.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fit: strongest reward
    } else if pr <= 10 {
        -12.0 // dead-space risk low, still reusable by tiny items
    } else if pr < 20 {
        8.0   // awkward sliver
    } else if pr < 35 {
        -6.0  // fits small items (10..35 band)
    } else if pr < 50 {
        5.0   // mid sliver
    } else if pr < 70 {
        -4.0  // fits medium items
    } else {
        2.0   // large leftover: fine but not urgent to fill
    };
    score += class;

    // Modulo coupling: post_residual divisible by common item sizes (10,20,25,50)
    // pairs well with future arrivals.
    if pr != 0 {
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus -= 3.0; }
        if pr % 20 == 0 { harmonic_bonus -= 2.0; }
        if pr % 25 == 0 { harmonic_bonus -= 2.0; }
        if pr % 50 == 0 { harmonic_bonus -= 2.0; }
        score += harmonic_bonus;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            score += 4.0; // this bin can't host the follow-up; deprioritize slightly
        }
        // Harmonic pair: next_item_size + item_size forms a nice fraction of capacity
        let s = item_size + next_item_size;
        if bin_capacity % s == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless current bins are tight
    // or this is the very start.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = if open_bins_count == 0 { 0.0 }
            else { mean_residual / bin_capacity as f64 };
        // open new bin only when mean residual is small (bins nearly full)
        score += 25.0 - 40.0 * (1.0 - tightness) * (0.5 + 0.5 * progress);
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Slight tie-break noise-free deterministic jitter by step parity on classes.
    if step_index % 2 == 0 && post_residual % 15 == 0 { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize large leftover space that likely won't be filled by typical items
    // (items are 1..100, so leftover > 50 is at risk of becoming dead space).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.5;
    }

    // Dead-space avoidance: penalize residuals that cannot fit the lookahead item
    // while a slightly larger gap could have.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 8.0;
    }
    // Reward a residual that can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residual capacity is already abundant.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 1.5;
    }

    // Mild bonus for using bins whose residual is below the mean
    // (consolidate nearly-full bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a good fit; otherwise keep them penalized so
    // existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if this is the last chance (no other fitting bin), allow opening.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Slight stream-progression pressure: as the stream advances, prefer
    // filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

