    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits perfectly in post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 / (1.0 + gap)) * 0.9;
        // Perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that can't fit next item but is small (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Prefer bins with small residual relative to mean (tight packing)
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and no bin will chain well, new bin is okay
        if next_item_size > 0 && post_residual >= next_item_size {
