    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating small, hard-to-use dead space (nonzero but tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Tightness coupling: prefer bins where the item fills a large fraction
    // of the residual (good packing density).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 6.0 * fill_ratio;
    }

    // Global state: if mean residual across open bins is high, we have slack,
    // so be pickier about poor fits; if low, accept placements more readily.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, keep options open (penalize near-full
    // bins slightly less aggressively since future is uncertain); late in the
    // stream, prioritize closing bins out (reward tight fits more).
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: a fresh empty bin is only attractive when
    // no open bin offers a decent fit (item barely fits or nothing fits well).
    if bin_residual == bin_capacity {
        let decent_fit = fitting_bins_count > 0 && post_residual >= 15;
        if decent_fit {
            // Keep existing bins attractive; discourage opening a new one.
            score += 25.0;
