            // Poor fits everywhere: opening a new bin is reasonable.
            score -= 5.0;
        }
        // Late in the stream with many open bins, avoid proliferation.
        if progress > 0.7 && open_bins_count > 3 {
            score += 5.0 * open_bins_count as f64;
