pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, waste matters more (quadratic growth in progress).
    let waste = post_residual as f64 / cap;
    score += 40.0 * waste * waste * (0.5 + progress);

    // Reward tight fits: post_residual near zero gets a smooth bonus.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tight * tight * tight;

    // Coupling with mean residual: penalize bins far from the mean residual
    // (keeps residual profile homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

