    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Fine-grained dead-space band shaping.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
    }

    // Penalize awkward 25..35 residuals that rarely match future items.
    if !is_new_bin && post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Discourage new bins when any open bin can still fit next item too.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        // Harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        // New-bin lookahead: prefer opening a new bin only when the fresh
        // residual (capacity - item) can also host the next item snugly.
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            // MUTATION: also reward fresh residuals that can host the next
            // item exactly or with multiplicity, encouraging chain fits.
            if fresh >= next_item_size && fresh % next_item_size == 0 {
                score -= 3.0;
            }
        }
        // MUTATION: resist opening new bins when mean residual suggests
        // plenty of aggregate room remains, scaled by progress.
        if mean_residual > 1.5 * item_size as f64 && open_bins_count > 3 {
            score += 5.0 * (0.5 + 0.5 * progress);
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // MUTATION: dead-space multiplicity anticipation — reward bins whose
        // dead space can host next item with minimal leftover, scaled by
        // stream progress and open-bin count.
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size {
                let rem = ds % next_item_size;
                if rem == 0 {
                    score -= 2.0 + 2.0 * progress;
                } else if rem <= 4 {
                    score -= 1.0 + 1.5 * progress;
                }
            }
        }
        // MUTATION: late-stream tightness — extra reward for bins whose
        // post residual is small relative to mean residual, consolidating
        // remaining space where it is most reusable.
        if progress > 0.55 && next_item_size > 0 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score -= 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.5 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained residual fitting: reward near-exact matches to next item.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin dead-space control.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        // Stronger bias against opening a new bin when several bins already fit.
        if fitting_bins_count >= 3 {
            score += 6.0 + 2.0 * (fitting_bins_count.min(6) as f64);
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            // Anticipation: wasted gap between residual and next item class.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Consolidation: when many bins are open, favor bins that end nearly empty.
        if open_bins_count > 5 && post_residual == 0 {
            score -= 3.0 * (1.0 - progress);
        }
        // Mid-band waste guard: penalize leftovers just below the next item size.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
            score += 2.0 + progress * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger post residuals are less harmful; slight reward for tight fits
        score -= (100.0 - post_residual as f64) * 0.05;
    }

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: prefer reusing bins when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so when many open.
        score += 25.0 + 8.0 * pressure;
        // But if no existing bin fits well (post_residual small means good fit,
        // so if this is the new bin and item leaves huge residual, discourage less)
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reusing an existing bin: reward, especially when few fitting bins remain.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        score -= 3.0 * pressure;
    }

    // Lookahead: if the next item would fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Late-stream tightness: as stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    // Mean residual coupling: penalize bins whose residual deviates badly from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect 2-step match: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= look {
            // Next item can fit after this placement: reward proportionally to tightness.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item: penalize.
            score += 1.5 * diff;
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 10.0;
    }

    // Prefer bins whose residual is small relative to the mean (compact bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        // But if no open bin fits, new bin is the only option; soften penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild coupling: discourage creating residuals that are unusably small.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Penalize very small dead space waste relative to future item needs.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Item can't be followed by the next item in this bin: penalize dead space.
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else {
            // Next item fits too: bonus for chain placement.
            score -= 6.0 + (post_residual - next_item_size as u32) as f64 * 0.15;
        }
    } else {
        // Last item: prefer maximal fill.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Global residual context: if this bin's residual is far below the mean
    // (it's the "emptiest"), slightly deprioritize dumping into it early.
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual + 1.0 {
        score += (bin_res_f - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - bin_res_f) * 0.1;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        // Base penalty keeps new bins closed unless open bins are truly bad.
        score += 18.0 + poor_fit * 10.0;
        // Late in the stream, opening a fresh bin for exact-ish future fits is fine.
        score -= progress * 8.0;
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    } else if post_residual == 0 {
        // Perfect fill: huge reward.
        score -= 30.0;
    }

    // Mild non-linear dead-space shaping: penalize residuals that are hard to fill later.
    let waste = post_residual as f64;
    if waste > 0.0 && waste < 10.0 {
        score += (10.0 - waste) * 0.5; // tiny unusable slivers are worst
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * (1.0 - norm_pr) * 2.0 + progress * progress * norm_pr * 1.5);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residual too small to matter, amplified late
    let dead = (norm_pr - (1.0 - item_size as f64 / cap)).max(0.0);
    score += 10.0 * dead * dead * (1.0 + progress);

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 15.0 * (1.0 - (pr - nx) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this fit is loose
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (norm_pr * norm_pr);

    // Mean residual divergence: prefer bins near the mean to keep balance
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 + progress) - 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    let pr = post_residual;
    // Perfect fit: huge reward
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Residual class penalty: residuals that are too small to fit any
        // plausible item are dead space. Items >= 10 in classic setting, but
        // interface allows 1..100, so use a soft dead-zone around small pr.
        let dead = if pr < 10 { (10 - pr) as f64 * 4.0 } else { 0.0 };
        score += dead;

        // Modulo-harmonic reward: residuals divisible by common item sizes
        // (10, 20, 25, 50) are more likely to be filled exactly later.
        let mut harmonic_bonus = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += d as f64 * 0.5;
            }
        }
        score -= harmonic_bonus.min(40.0);

        // Integer-division threshold: post_residual bucket by 25
        let bucket = pr / 25; // 0..4
        score -= match bucket {
            0 => 6.0,              // tiny leftover: bad
            1 => 2.0,              // 25..49: decent
            2 => 0.0,              // ~half free: good
            3 => -1.5,             // roomy
            _ => -2.5,             // nearly empty bin
        };

        // Lookahead coupling: if next item fits the post residual exactly or
        // nearly, reward strongly (chaining).
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size <= pr {
                let gap = pr - next_item_size;
                let chain = if gap < 10 { 25.0 } else if gap < 25 { 12.0 } else { 4.0 };
                score -= chain;
            } else {
                // next item won't fit here; slight penalty scaled by overshoot
                score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
            }
        }

        // Last-chance bin: if this is the only fitting bin, strongly prefer
        // using it over opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 45.0;
        }

        // New-bin candidate handling: empty bin gets a mild base cost so we
        // prefer existing bins, unless open bins are very full / fragmented.
        if bin_residual == bin_capacity {
            score += 30.0 + (open_bins_count as f64).sqrt() * 2.0;
            // If mean residual across open bins is small (bins nearly full),
            // opening fresh bin is attractive.
            score -= (cap - mean_residual).min(cap) * 0.4;
        } else {
            // Tightness reward: the fuller the bin relative to capacity, the better.
            let tightness = 1.0 - (post_residual as f64) / cap;
            score -= tightness * 15.0;
        }

        // Late in stream: consolidate, penalize spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
        if open_bins_count > 3 {
            score += (open_bins_count as f64).ln() * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained slack-gap shaping scaled by progress.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= 2 * next_item_size {
                let rem = slack_after % next_item_size;
                if rem <= 3 {
                    score -= 2.5 + (3 - rem) as f64 * 0.8;
                }
            }
            if slack_after == 0 {
                score -= 5.0 * progress;
            } else if slack_after < 5 {
                score -= 3.0 * progress;
            }
            // MUTATION: multiplicity-anticipation on dead space — reward bins whose
            // dead space hosts next item with minimal leftover, progress-scaled.
            let ds = (bin_residual - post_residual) as u32;
            if ds >= next_item_size {
                let rem = ds % next_item_size;
                if rem == 0 {
                    score -= 2.0 + 2.0 * progress;
                } else if rem <= 4 {
                    score -= 1.0 + 1.5 * progress;
                }
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

