    // Late-stream small-residual consolidation.
    let frag = (post_residual > 0 && post_residual < 6) as i32;
    score -= frag as f64 * 3.0 * (1.0 - progress);
    if !is_new_bin && progress > 0.6 && post_residual < 10 {
        score -= (10 - post_residual) as f64 * 0.35;
    }
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let two_fit = (post_residual - next_item_size) >= next_item_size;
        if two_fit {
            score -= 2.0;
        }
    }
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
        score -= 1.5 * (1.0 - progress);
