    if !is_new_bin && dead_space > 0.0 && dead_space < 12.0 {
        score -= 1.0 * (1.0 - progress);
    }
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.2 + 2.0 * progress;
