            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            // MUTATION: new-bin multiplicity lookahead — favor opening a fresh bin
            // only when its fresh residual can host the next item exactly or with
            // near-zero leftover, otherwise penalize proportionally to waste.
            if fresh >= next_item_size {
                let rem = fresh % next_item_size;
                if rem == 0 {
                    score -= 4.0 * (1.0 - progress);
                } else if rem > next_item_size / 2 {
                    score += (rem - next_item_size / 2) as f64 * 0.4;
                }
            } else {
                score += 2.0;
            }
        }
        // MUTATION: avoid opening a new bin when an open bin could host both this
        // item and the next one (lookahead consolidation).
        if open_bins_count > 0 && next_item_size > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 7.0;
        }
    }

    score
}

