    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 35.0 };
        score += pressure + open_bins_count as f64 * 0.5;
        // Late in the stream, prefer consolidating into existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Mild pull toward bins with residuals close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

