pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Items are 1..=100; small residuals below ~10 are near-waste.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward;
    // if next item is larger than post_residual, this bin's leftover is dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        } else {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, keep bins open and flexible
    // (penalize near-empty bin usage); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score += (1.0 - progress) * (1.0 - fill_ratio) * 10.0;
    score -= progress * fill_ratio * 10.0;

    // Global state: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate; new-bin candidate penalized.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let consolidation_pressure = (open_bins_count as f64) * 1.5 + mean_residual * 0.05;
        score += consolidation_pressure + 5.0;
        // But if the item is large and barely fits anywhere, allow new bin.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Mild penalty for leaving residuals in the awkward 40..60 band
    // (hard for typical small items to fill exactly).
    if post_residual >= 40 && post_residual <= 60 {
        score += 3.0;
    }

    score
}

