        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // NEW: penalize leaving a dead gap that no future item of plausible size can use.
        if next_item_size > 0 && post_residual > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > bin_capacity / 2 {
            score += 1.5 * (1.0 - progress);
        }
        // NEW: reward bins whose post-residual stays tileable by small items.
        if post_residual > 0 && post_residual <= 12 && progress > 0.4 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_norm = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };

    // Non-linear coupling: residual waste penalized more strongly as stream progresses
    score += 6.0 * pr_norm * pr_norm * (0.3 + 0.7 * progress);

    // Tight fits (small post_residual) rewarded with smooth quadratic bonus
    score -= 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * fit_norm;

    // Last-chance bin before opening a new one: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smooth term
    score += 0.5 * ((pr - mean_residual) / cap).powi(2);

    // Lookahead coupling: reward leaving space useful for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 2.0 * (1.0 - (diff / cap)) * (1.0 - (diff / cap));
        } else {
            score += 1.5 * ((-diff) / cap);
        }
    }

    // Mild preference to fill existing bins over opening new ones as stream grows
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes / small remainders) are preferred.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr < 10 {
        25.0 // dead space: too small for any item
    } else {
        // reward residuals that are multiples of 10, 20, 25, 50 (harmonic classes)
        let harmonic = (pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
        -(harmonic as f64) * 8.0
    };
    score += class_penalty;

    // Integer-division threshold coupling: how well does next_item_size nest
    // into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // nested fit quality: fraction of next item covered exactly
            let quot = post_residual / next_item_size.max(1);
            let rem = post_residual % next_item_size.max(1);
            let nest = (rem == 0) as i32 as f64 * 15.0 + (quot.min(3) as f64) * 3.0;
            score -= nest;
            // penalize leaving residual that neither fits next item nor is dead
            if post_residual - next_item_size > 0 && post_residual - next_item_size < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot go here; penalize proportionally to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when current bins are crowded and
    // this placement would create a large dead-space class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let dead = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score = 70.0 - 25.0 * progress + 5.0 * crowded - dead;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 20.0; // fresh bin guarantees next-item fit
        }
    }

    // Mild fill-rate shaping: reward tight fits relative to capacity fraction.
    score -= (item_size as f64 / cap) * 5.0;

    // Tie-break with mean residual divergence: bins far below mean residual
    // are "waste candidates" — slight penalty.
    let dev = (post - mean_residual) / cap;
    score += dev * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Non-linear penalty on mid-range wasted space (worst zone: 20..50 unused).
    let pr = post_residual as f64;
    if pr > 20.0 && pr < 50.0 {
        score += 0.6 * (pr - 20.0) * (50.0 - pr) / 225.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // leftover too small for lookahead -> dead space risk
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 35.0 + 4.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds a pool); late, expensive.
        score += 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, reusing is clearly better.
        score += 0.3 * mean_residual;
    } else {
        // Reward reusing existing bins, scaled by how many are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild preference for filling bins that are already quite full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a post_residual that exactly
    // or nearly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: exponential decay on gap.
        score -= 60.0 * (-gap / 12.0).exp();
        // Exact match jackpot.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If the next item also fits after this placement, mild reward.
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space penalty scaled by how much is wasted relative to mean residual.
            let waste = post_residual as f64;
            score += 0.5 * waste * (1.0 + (mean_residual / bin_capacity as f64));
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins whose post_residual sits near the
    // mean residual (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and load.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * (1.0 + 0.5 * progress) + 20.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 30.0;
        }
        // If only this bin can fit the item (fitting_bins_count==1 includes new bin),
        // opening is fine.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    } else {
        // Prefer fuller bins: reward small post_residual generally (tight fit).
        score -= 0.4 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;
        // Penalize leaving awkward residuals that neither fit typical items well.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny dead space is bad
        }
    }

    // Mild penalty for bin sprawl: fewer open bins preferred when residuals are healthy.
    if open_bins_count > 10 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 55.0;
        // Early in the stream, new bins are cheaper (more room to fill later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If no other bin fits well, opening is acceptable.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    } else {
        // Reward using a bin that only this item fits into (last-chance bin).
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit;
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0) * 0.5;
        }
    }

    // Global state coupling: prefer balancing residuals toward the mean.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
