        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // MUTATION: dead-space multiplicity anticipation scaled by progress.
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size {
                let rem = ds % next_item_size;
                if rem == 0 {
                    score -= 2.0 + 2.0 * progress;
                } else if rem <= 4 {
                    score -= 1.0 + 1.5 * progress;
                }
            }
        }
        // MUTATION: penalize residual that can't host next item late (dead-end avoidance).
        if progress > 0.55 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = progress.clamp(0.0, 1.0);

    // Smooth polynomial coupling of post_residual with progress:
    // residual waste becomes more costly as the stream matures.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let waste_penalty = pr_norm * pr_norm * (0.5 + p) * 30.0
        + pr_norm * pr_norm * pr_norm * (1.0 - p) * 20.0;
    score += waste_penalty;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * 25.0;

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, strongly favor this bin (smooth quadratic match term).
    if next_item_size > 0 {
        let gap = (pr as f64 - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += gap_norm * gap_norm * 40.0;
        // Bonus if next item nests perfectly
        if next_item_size == post_residual {
            score -= 60.0 * (1.0 - 0.5 * p);
        }
    }

    // Last-chance bin: penalize heavily if this is the only fitting bin and
    // the fit is loose (avoid wasting the final usable bin on a bad fit).
    if fitting_bins_count == 1 {
        score += 15.0 * pr_norm * (1.0 + p);
    } else {
        score -= 5.0;
    }

    // New-bin candidate handling: empty bin gets a baseline offset so it is
    // only chosen when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += cap * 0.6 + mean_residual * 0.3 * (1.0 + p);
    } else {
        // Favor bins whose residual is below the mean (denser bins first).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * dev * 10.0;
        score -= dev * 5.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
