        // consolidate open bins and reduce total count.
        if progress > 0.65 && bin_residual > bin_capacity / 2 {
            score -= 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable size classes
    let pr = post_residual as i64;
    let class = if pr == 0 { 0 }
        else if pr <= 5 { 1 }        // nearly dead space
        else if pr <= 20 { 2 }       // small item class
        else if pr <= 40 { 3 }
        else if pr <= 70 { 4 }
        else { 5 };
    let class_penalty: [f64; 6] = [0.0, 60.0, 18.0, 8.0, 3.0, 0.0];
    score += class_penalty[class as usize];

    // Reward tight fits (small post_residual fraction)
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight * 4.0).max(0.0) * 10.0;

