    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Modulo-based harmonic bonus on post_residual
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0; // round residual leaves clean class slots
    }
    if post_residual % 10 != 0 && post_residual < 10 {
        score += 15.0; // ragged tiny residual is dead space
    }

    // New-bin candidate handling: prefer new bin only when fits are poor
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: residual after placement = capacity - item
        score = (bin_capacity - item_size) as f64 + 25.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        // If existing fits are all bad (large post_residuals), opening is fine
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    } else {
        // Prefer filling bins with low residual relative to mean
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Mild pressure to close out bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

