            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Combined: prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
