    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that is too small to fit even the smallest plausible item
    // (or the lookahead item) is effectively wasted capacity.
    let dead_threshold = next_item_size.min(20) as f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 + (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual cannot host the next item: mild penalty
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight; favor filling it further.
    let dev = mean_residual - bin_residual as f64;
    score -= (dev / bin_capacity as f64).clamp(-1.0, 1.0) * 8.0;

    // New-bin candidate: make the empty bin moderately attractive only when
    // no open bin offers a good fit; otherwise keep it penalized.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 20.0 + mean_residual * 0.1;
        }
    }

    score
}

