        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Combined: penalize dead space that sits just below the next item size,
        // scaled by how close it is to being usable (fine-grained coupling).
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            let near = 1.0 - ((next_item_size - dead_space as u32) as f64 / next_item_size.max(1) as f64);
            score += near * 1.5 * (1.0 - progress);
        }
        // Dead-space ratio shaping: extra penalty when dead space exceeds half
        // the next item size but remains unusable — reduces residual variance.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            let half = next_item_size / 2;
            if (dead_space as u32) >= half && half > 0 {
                score += 2.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/next-item fits
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain fit
        } else if post_residual > next_item_size {
            // leftover after placing next item too
            let second = post_residual - next_item_size;
            score -= 20.0 * (1.0 - second as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize tight-but-wasteful fits
            score += 8.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    } else {
        // last item: minimize final residual aggressively
        score -= 30.0;
    }

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score -= 15.0 * (1.0 - tightness / bin_capacity as f64);

    // Penalize deviating far from mean residual (keeps pool balanced)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0
            + 0.3 * mean_residual
            - 10.0 * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());
    }

    // Mild stream-progress pressure to close bins early
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // slight penalty when many bins fit, to break ties by fit quality
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item fits perfectly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize leaving awkward gap
            score += 5.0;
        }
    }

    // Global state coupling: prefer filling bins with residual near mean residual
    let res_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * res_gap;

    // Penalize creating many nearly-empty open bins (fragmentation)
    if post_residual > bin_capacity as u32 / 2 {
        score += 0.1 * open_bins_count as f64;
    }

    // Time horizon: early in stream, be more willing to open new bins (empty-bin candidate);
    // late in stream, consolidate into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, expensive late
        score += 30.0 * t - 10.0 * (1.0 - t);
    } else {
        score -= 10.0 * t;
    }

    // Small tie-break noise-free deterministic perturbation
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, non-linearly scaled by stream progress.
    // Early on, tight fits matter less (bins are cheap); late, waste is costly.
    let mut score = pr * (1.0 + progress * progress * 1.5);

    // Smooth convex penalty on small residuals (dead space) via quadratic coupling.
    score += norm_pr * norm_pr * cap * 0.3;

    // Interaction: post_residual vs mean residual — prefer bins whose leftover
    // matches the fleet's average residual (keeps future fits viable).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.5;

    // Lookahead coupling: reward if post_residual accommodates next item,
    // penalize smoothly as next item falls short of fitting.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * cap * 0.8;
        // Smooth bonus when next item fits exactly-ish.
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= (1.0 - slack).max(0.0) * 2.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using a bin when it's the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many bins are open and tight fits exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress) + open_bins_count as f64 * 0.2;
        // But allow opening when existing bins would leave very large dead space.
        score += norm_pr * 0.0; // new bin has full residual; base term already large
    }

    // Cubic progress coupling for long-stream adaptation.
    score += (progress - 0.5) * (progress - 0.5) * (progress - 0.5) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
