        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // Combined: prefer new bin when its leftover aligns with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin dead-space control: discourage opening a bin that wastes a
        // mid-band gap the next item cannot use (reduces residual dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        // New-bin lookahead anticipation: if the new bin's leftover can absorb
        // the next item exactly, favor opening it over a poor existing fit.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            // Anticipation: wasted gap between residual and next item class.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.12 * (1.0 - progress) + wasted * 0.08 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead: penalize bins whose leftover cannot absorb
        // the next item yet wastes a mid-band amount.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Combined: penalize dead space that sits just below the next item size,
        // scaled by how close it is to being usable (fine-grained coupling).
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            let near = 1.0 - ((next_item_size - dead_space as u32) as f64 / next_item_size.max(1) as f64);
            score += near * 1.5 * (1.0 - progress);
        }
        // NEW: exact-fill chain bonus, mild and progress-scaled.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes on post_residual: penalize residuals that are
    // unusable dead space (too small for any plausible item, sizes 1..=100).
    // Class boundaries via integer division thresholds.
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 40.0,           // nearly full bin: excellent
        1 => score -= 20.0,           // 10-19 left
        2 => score -= 12.0,           // 20-29 left
        3 => score -= 6.0,            // 30-39
        4 => score -= 2.0,            // 40-49
        5 => score += 3.0,            // half-empty: mediocre
        6 => score += 6.0,
        7 => score += 9.0,
        8 => score += 12.0,
        9 => score += 15.0,
        _ => score += 18.0,           // nearly empty bin (new bin case)
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward when next item nearly fills the leftover.
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - next_tight / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how close we are
        // to fitting it (wasted opportunity).
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are poor. Empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows mildly with number open.
        score = (bin_capacity as f64) + 5.0 * (open_bins_count as f64).sqrt();
        // If next item is large, a fresh bin is more attractive.
        score -= 0.05 * (next_item_size as f64);
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    } else {
        // Favor using bins with below-mean residual (balance load).
        let dev = mean_residual - (bin_residual as f64);
        score += 0.3 * dev;
    }

    // Mild preference to keep many open bins from proliferating: reward
    // packing into already-open bins as open_bins_count grows.
    if bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count as f64);
    }

    score
}

