        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Strong preference for bins that fit both current and next items with near-zero combined slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // When many bins are open, reward filling the emptiest-but-usable bin to
        // reduce residual variance (consolidation pressure scales with open count).
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        // Penalize leaving large residuals in bins that could absorb the next item
        // twice, encouraging tight triple-fits.
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // NEW: dead-space ratio shaping — penalize bins whose dead space fraction
        // is neither tiny nor reusable by the next item (middle-band waste).
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        // NEW: lookahead anticipation — reward bins whose post-fit residual
        // matches the next item modulo a small chain of fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy penalty for small unusable gaps
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            // gap too small for any item: severe penalty
            score += 60.0 * (10.0 - dead) / 10.0;
        } else if dead < 20.0 {
            // small gap, only fitable by tiny items: moderate penalty
            score += 25.0 * (20.0 - dead) / 10.0;
