pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post_residual).
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strong reward.
            let match_q = 1.0 - diff / cap;
            score -= 10.0 * match_q * match_q;
            if diff == 0.0 {
                score -= 8.0; // perfect 2-chain bonus
            }
        } else {
            // Next item won't fit here: penalize creating a stub too small for it.
            score += 4.0 + 0.05 * (nx - post_residual as f64);
        }
    }

    // Compare residual to mean residual across open bins: prefer bins that are
    // relatively fuller (below mean residual) to keep a pool of large residuals.
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // and no good open option exists.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        if next_item_size > 0 && (bin_residual - item_size) >= next_item_size {
            score += 6.0; // fresh bin can host a chain: mild penalty, still viable
        } else {
            score += 10.0 + 0.05 * waste; // discourage needless new bins
        }
        if fitting_bins_count > 1 {
            score += 5.0; // other bins exist; avoid spreading
        }
    }

    // Slight stream-progression pressure: tighten as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * fit_ratio;

    // Mild penalty per open bin to encourage consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

