    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Wasted-gap anticipation.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = (next_item_size - post_residual) as f64;
        let near = 1.0 - (wasted / next_item_size.max(1) as f64);
        score += wasted * 0.14 * (1.0 - progress) + wasted * 0.08 * progress;
        score += near * 1.5 * (1.0 - progress);
        if post_residual >= 12 {
            score += 3.0;
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
    } else {
        // Late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // New: discourage creating residuals in the "awkward middle" band
        // that no typical next item can fill, scaled by open bin count.
        if post_residual > 16 && post_residual < 30 && open_bins_count > 2 {
            score += 1.5 + 1.5 * progress;
        }
        // New: reward residuals that are near-exact multiples of common
        // small item sizes (anticipating chains of small items).
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size.max(1);
            let rem = post_residual % next_item_size.max(1);
            if rem <= 1 && k >= 2 {
                score -= 2.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic class of post_residual: bins whose leftover is "usable" (large residual)
    // get a bonus; tiny dead-space leftovers get penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, excellent
    } else if pr <= 5 {
        score += 20.0; // dead space, hard to reuse
    } else if pr <= 15 {
        score += 8.0;
    } else if pr <= 30 {
        score -= 5.0; // mid residual is reusable
    } else {
        score -= 10.0; // large residual still useful
    }

    // Modulo arithmetic on capacity fractions: residual divisible into common item sizes
    let harmonics = [10u32, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if pr >= *h && pr % h == 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 25.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here after placement; slight penalty scaled by closeness
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (1.0 - gap / bin_capacity as f64).min(1.0);
        }
    } else {
        // last item: prefer zero waste
        score += 0.3 * pr as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // opening a new bin is fine early or when open bins are nearly full
        score += 25.0 - 15.0 * pressure.min(2.0);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // item would fit perfectly in fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Mild stream-progression tiebreak: later in stream, favor consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (mean_residual - post_residual as f64).signum();

    // Prefer bins with residual close to item size (minimize waste ratio)
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 15.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
