pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact power-of-two-friendly residuals are best
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space negligible
    } else if pr <= 25 {
        score += 8.0;
    } else if pr <= 50 {
        score += 18.0;
    }

    // Modulo-10 class: residuals divisible by 10 pair well with the 10..80 item grid
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Modulo-25 class: quarter-capacity harmonics
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd residuals are awkward for integer item sizes
    if pr % 2 == 1 && pr > 0 {
        score += 5.0;
    }

    // Harmonic coupling: next item fits exactly into post_residual -> strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size {
            let chain = pr - next_item_size;
            if chain % 10 == 0 {
                score -= 15.0;
            }
            score -= (chain.min(30)) as f64 * 0.4;
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; make it attractive only when existing
    // residuals are fragmented (high mean residual spread vs item)
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if item_size as f64 > mean_residual {
            score -= 10.0; // item doesn't fit anywhere well anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Prefer bins whose residual deviates favorably from the mean
    score -= (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
