pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Penalize if next item would leave a tiny dead gap in this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 10 {
            score += 12.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it attractive only when this would be a fresh,
    // well-shaped start; otherwise keep it costly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with number of already-open bins.
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If current bin fit is poor (large post residual in an open bin),
        // opening a new bin becomes relatively better; handled implicitly since
        // open-bin scores carry their post_residual.
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 20.0;
        }
        // Early stream: allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild alignment with mean residual: prefer bins whose residual is below mean
    // (tighter bins) when placing.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

