            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect 2-step match:
    // post_residual equals next item size (next item fills bin exactly).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 4.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward scaled by how snugly
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize small dead space more
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 0.6;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: avoid opening a new bin if this fits reasonably.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0; // many alternatives, be pickier
    }

    // Penalize very small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // Many open bins: prefer tightening existing ones over spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= (1.0 - post_residual as f64 / cap) * 10.0;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += (next_item_size - post_residual) as f64 * (0.5 + progress);
    }

    // Reward bins whose leftover can still host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (post_residual as f64 - next_item_size as f64) / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin: penalize so it is chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64 + progress * 5.0;
    }

    // Slight preference for bins whose residual deviates favorably from the mean
    // (use below-mean-residual i.e. fuller bins first).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: penalize leaving many sparse bins.
    if open_bins_count > 1 {
        score += progress * (post_residual as f64 / cap) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with non-linear shrink of large residuals over time
    let mut score = pr * (1.0 - 0.35 * progress * norm_pr);

    // Smooth polynomial coupling between item size and progress
    score -= 12.0 * norm_item * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space non-linearly: very small residuals are wasted
    score += 20.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * (1.0 - progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose residual pairs with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).abs();
        score += 0.25 * fit;
        if pr >= nxt {
            score -= 8.0 * (1.0 - fit / cap);
        }
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual deviation coupling
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: slightly penalize early, allow late when residuals are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
