            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= 2 * next_item_size {
                let rem = slack_after % next_item_size;
                if rem <= 3 {
                    score -= 2.5 + (3 - rem) as f64 * 0.8;
                }
            }
            if slack_after == 0 {
                score -= 5.0 * progress;
            } else if slack_after < 5 {
                score -= 3.0 * progress;
            }
            if slack_after == next_item_size {
                score -= 3.0 + 3.0 * progress;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.65;
            score += gap * 0.35;
            score += gap * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
    }

    if !is_new_bin && post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        // MUTATION: stronger new-bin gate — require the fresh residual to
        // accommodate the next item with tight slack, else resist opening.
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size {
                let slack = fresh - next_item_size;
                if slack > 10 {
                    score += (slack - 10) as f64 * 0.35;
                }
            } else if fitting_bins_count > 0 {
                score += 5.0 * (1.0 - progress);
            }
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size {
                let rem = ds % next_item_size;
                if rem == 0 {
                    score -= 2.0 + 2.0 * progress;
                } else if rem <= 4 {
                    score -= 1.0 + 1.5 * progress;
                }
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= 2 * next_item_size && (ds - 2 * next_item_size) <= 5 {
                score -= 2.5 + 1.5 * progress;
            }
            if ds > next_item_size && ds < 2 * next_item_size && (ds - next_item_size) > 8 {
                score += 1.5;
            }
        }
        // MUTATION: residual-conservation shaping — reward bins whose post
        // residual stays close to the stream's mean residual (keeps future
        // items packable), penalize outliers scaled by progress.
        if post_residual > 0 {
            let drift = (post_residual as f64 - mean_residual).abs();
            score += drift * 0.08 * (1.0 - progress);
            if drift < 4.0 {
                score -= 1.8;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of 10, i.e. class 0 mod 10) are rewarded,
    // awkward leftovers (small nonzero scraps) are penalized.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0.0 {
        score -= 12.0; // decimally reusable residual
    } else {
        score += class * 1.5; // penalize scrap proportional to off-class amount
    }

    // Dead-space penalty: leftover too small for any plausible item (1..100 range)
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr < 20 {
        score += 5.0;
    }

    // Harmonic coupling with next item: if next item exactly fills post_residual
    // (mod-capacity harmony), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let frac = next_item_size as f64 / pr as f64;
            if frac > 0.5 {
                score -= 8.0 * frac;
            } else {
                score += 6.0 * (1.0 - frac); // leaves another awkward scrap
            }
        } else {
            score += 10.0; // next item can't reuse this residual
        }
    }

    // Integer-division threshold on bin_residual: half/full fill classes.
    let half = bin_capacity / 2;
    if bin_residual >= half {
        score -= 4.0; // prefer filling roomier bins
    } else {
        score += 3.0; // keep tight bins for small items
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good harmony exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item followed by large item: fresh bin OK
        }
    }

    // Stream progression: late in stream, consolidate rather than open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
