pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step chain fit: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        // Heavy reward for exact match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space unusable by next item but not tiny
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just minimize waste
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it enables a much better future fit
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a new bin lets both current and next item pack cleanly
            score -= 45.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0 * (open_bins_count as f64).min(20.0) / 20.0;

    // Time horizon: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - tightness) * 20.0 * progress;

    // Global residual state: if mean residual is small, avoid wasting this bin's space
    if mean_residual < (item_size as f64) && bin_residual >= item_size {
        score += 5.0;
    }

    // New-bin candidate: mildly penalize so it only wins when fits are truly poor
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled by progress (later: prefer tight fits more strongly)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty weighted by progress
    score += 30.0 * progress * norm_pr * norm_pr;

    // Cubic interaction between residual fill ratio and item size
    score += 12.0 * norm_item * norm_pr * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * progress * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smooth
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Combined fine-grained fitting + lookahead anticipation: reward
            // slack that leaves a gap the next item can nearly or exactly fill.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= next_item_size {
                score -= 2.0;
            }
            if slack_after > 0 && slack_after % next_item_size == 0 {
                score -= 2.0 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio penalty.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Wasted-gap anticipation: penalize leftovers that sit just below the
    // next item size, scaled by closeness (fine-grained coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = (next_item_size - post_residual) as f64;
        let near = 1.0 - (wasted / next_item_size.max(1) as f64);
        score += wasted * 0.14 * (1.0 - progress) + wasted * 0.08 * progress;
        score += near * 1.5 * (1.0 - progress);
        if post_residual >= 12 {
            score += 3.0;
        }
    }

    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // New-bin leftover aligned with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin dead-space control.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        // New-bin lookahead anticipation: leftover can absorb next item nearly exactly.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits (class 0) are gold.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 40.0,                       // dead-space-free leftover
        1..=5 => 8.0 - class as f64,     // small leftovers pair well with tiny items
        _ => -(class as f64 - 5.0) as f64, // 6..9 leftovers are awkward
    };
    score -= class_bonus;

    // Integer-division threshold: leftover >= half capacity is a healthy bin.
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    } else if post_residual <= 10 {
        // Nearly-sealed bin: excellent, seal it.
        score -= 12.0;
    } else {
        // Mid-range dead space penalty grows with fill ratio squared.
        let fill = 1.0 - post_residual as f64 / cap_f;
        score += 10.0 * fill * fill;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely into this bin.
            let slack = (post_residual - next_item_size) % 10;
            score -= 10.0 - slack as f64;
        } else {
            // Next item would be stranded; penalize proportionally to overflow.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest packing overall.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 18.0;
        if post_residual > 30 {
            score -= 5.0; // decent leftover after using last chance
        }
    }

    // New-bin candidate logic: an empty bin (residual == capacity) is only
    // attractive early in the stream or when open bins are all nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap_f;
        // Penalize new bins more as the stream progresses and bins are full.
        score += 25.0 + 30.0 * progress - 20.0 * avg_fill;
        if open_bins_count == 0 {
            score -= 50.0; // nothing else exists, must open
        }
    }

    // Mild preference to balance load across many open bins.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible
    // future item (items >= 1, but small gaps < ~15 are hard to use) are
    // heavily penalized.
    if post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual < 30 {
        score += 12.0 * (1.0 - (post_residual as f64 - 15.0) / 15.0);
    }

    // Reward tight fits: the smaller the post_residual relative to the
    // item, the better the packing efficiency.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // next item can't use this tiny gap: dead space confirmed
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement: mild reward scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't follow: penalize dead space creation.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Reward placements that bring residual below the mean residual (tightening).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.4;
    } else {
        score += (res - mean_residual).min(50.0) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when post_residual is huge (item nearly fills it)
    if bin_residual == bin_capacity {
        // penalize opening new bin unless it yields an exceptionally tight fit
        score += 20.0;
        if item_size >= 70 {
            score -= 45.0; // big item in fresh bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: prefer closing bins tightly, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).max(1.0).log2() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 25 {
        score += 8.0; // risky small gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 6.0; // this placement blocks a bin that could have held next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fullest bins (best-fit style) among many open bins.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Late in stream: consolidate; early: allow opening bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: penalize opening new bins unless current fit is bad
    // or there are no open bins / very few fitting options.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 0.6 * (bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 50.0;
        } else if bad_fit && (fitting_bins_count <= 2 || progress > 0.7) {
            score -= 20.0; // worth opening a fresh bin for a poor fit
        } else {
            score += 35.0; // discourage new bin when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer small post residual (tight packing), scaled smoothly by progress
    let mut score = pr * (0.5 + 0.5 * progress);

    // Reward tight fits: quadratic bonus for small post_residual relative to capacity
    let tightness = 1.0 - pr / cap;
    score -= (tightness * tightness) * 10.0 * (0.3 + 0.7 * progress);

    // Reward exact-ish fits (post_residual very small) with smooth decay
    score -= (1.0 - (pr / cap).min(1.0)).powi(6) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.3);
    }

    // Penalize scattering across many open bins mildly
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Lookahead: reward if next item fits into post_residual exactly/well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 20.0; // perfect chain fit
        } else if nxt <= pr {
            let chain_waste = pr - nxt;
            score -= 8.0 * (1.0 - chain_waste / cap);
        } else {
            // next item won't fit: penalize leaving large unusable residue
            score += (pr / cap) * 6.0 * (1.0 - fit);
        }
    }

    // New-bin candidate: residual == capacity. Make it attractive only when
    // current fits are poor (large post_residual) and stream is early/mid.
    if bin_residual == bin_capacity {
        let poor_fit = pr / cap; // for empty bin pr == cap so use item fit instead
        let _ = poor_fit;
        let openness = 1.0 - progress;
        score = cap * (0.9 + 0.1 * progress) - 5.0 * openness * (1.0 - fit);
        // discourage opening new bin when a decent fit exists elsewhere
        if fitting_bins_count > 0 && pr > 0.0 {
            score += 4.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 3.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual diverges from mean
    // to balance residual distribution smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers that are "nice" sizes
    // (multiples of 10 / quarter-capacity) are more reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let nice = |r: u32| -> f64 {
        if r == 0 { 0.0 }
        else if r % 10 == 0 { -3.0 }
        else if r % quarter == 0 { -2.5 }
        else if r % 5 == 0 { -1.0 }
        else { 0.0 }
    };
    score += nice(post_residual);

    // Penalize awkward tiny dead space (mod-1 classes) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division thresholds: prefer post_residual in usable bands.
    let band = post_residual / 25; // 0..=4 harmonic band
    score -= (band as f64) * 2.0;

    // Coupling with lookahead item: reward if next item fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 - (slack as f64).min(6.0);
            if slack % 10 == 0 { score -= 2.0; }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current bins are crowded/tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        let penalty = 20.0 + 25.0 * (1.0 - progress) + 30.0 * (1.0 - tight);
        // If no open bin fits, opening is unavoidable-ish; soften.
        if fitting_bins_count == 0 {
            score += penalty * 0.35;
        } else {
            score += penalty;
        }
    }

