        // NEW: reward bins whose residual can absorb the next item twice exactly.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: penalize residual just barely below the next item (unusable sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 4 {
            score += 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0; // effectively impossible, kept for safety
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) if that item
    // would otherwise need a fresh bin: dead space relative to next_item_size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 8.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // over opening new ones; also penalize opening new bins when mean
    // residual is already large.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 25.0 + open_bins_count as f64 * 6.0 + mean_residual * 0.5;
    } else {
        // Existing bin: mild reward scaled by open bin pressure.
        score -= open_bins_count as f64 * 0.8;
    }

    // Slight preference to pack into emptier bins when mean residual is high
    // (consolidate large gaps, avoid fragmenting many bins).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late-stream nudge: as the stream progresses, avoid leaving awkward gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Perfect chain: this placement enables a perfect fit next step
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here; reward proportionally to closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by overshoot
            score += 8.0 * (diff / bin_capacity as f64).min(1.0);
        }
    } else {
        // Last item: purely minimize post_residual
        score -= 5.0;
    }

    // Penalize dead space: small post_residual that can never hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Penalize opening a new bin when open bins exist that fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin is acceptable if no good fit exists (large post_residual everywhere)
        if mean_residual >= item_size as f64 * 1.5 {
            score += 10.0;
        } else {
            score += 45.0 - 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
