pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual), especially exact fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64)
        } else {
            true
        };
        if dead {
            score += 8.0 * (post_residual as f64) / (bin_capacity as f64);
        } else {
            score -= 4.0; // next item can fill this gap
        }
    }

    // Last-chance bonus: only one fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let waste_here = (bin_residual - item_size) as f64;
        let spread = (mean_residual - (bin_residual as f64)).abs();
        score += 20.0 + waste_here * 0.3 + spread * 0.2;
        // Early in stream, prefer exploring new bins slightly less harshly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely needed.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64);
    score += 0.15 * gap;

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Lookahead: if next item would fit in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth interaction: residual wastefulness grows with stream progress
    score += 12.0 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0).sqrt();

    // Penalize large post residual when it can't hold the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth step via tanh-like logistic
        let s = ((pr - nxt) / 8.0).tanh();
        let smooth_fit = 0.5 * (1.0 + s);
        score -= 6.0 * fits_next * (1.0 - smooth_fit) * (nxt / cap);
        score += 4.0 * (1.0 - fits_next) * (nxt / cap);
    }

    // Reward tight fits: low post residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * tightness * tightness;

    // Last-chance bonus: only one fitting bin -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins with high mean residual
    score += 0.3 * (mean_residual / cap - norm_pr).abs() * (open_bins_count as f64).ln().max(1.0);

    // Slight preference for existing bins over new bin as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls
    // into "unusable" residue classes (small but nonzero, can't fit typical items).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Tiny unusable sliver: penalize heavily (best-case waste).
        score += 40.0 - 2.0 * pr as f64;
    } else if pr == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Classify post_residual by capacity fraction bands.
        let frac = pr as f64 / cap;
        if frac < 0.25 {
            score += 10.0;
        } else if frac < 0.5 {
            score -= 5.0;
        } else {
            score -= 15.0;
        }
        // Modulo coupling: residual divisible into chunks of common item sizes
        // (10/20/25/50) is reusable; reward divisibility.
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else { score += 6.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = 55.0 + 40.0 * (1.0 - crowded) - (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, be more conservative (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
