    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: mild penalty (dead space risk).
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    if bin_residual < bin_capacity {
        score += pressure * 2.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmented bins).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: bias depends on how bad the best fit would be.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    score
}

