    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    let dead_space = (bin_residual - post_residual) as f64;

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
