            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: borrow from best heuristic — allow new bin when it can
        // host both current and next item with room to spare.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
        // MUTATION: harder gate late — open bins only if truly needed.
        if progress > 0.8 && fitting_bins_count > 0 && post_residual > 0 {
            score += 3.0 * progress;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: reward bins in the 12–30 dead-space band that can still
        // host the next item — reduces stranded mid-range residuals.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        // MUTATION: exact post-fit zero chase with lookahead confirmation.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Fine-grained slack-gap shaping combined with multiplicity.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= 2 * next_item_size {
                let rem = slack_after % next_item_size;
                if rem <= 3 {
                    score -= 2.5 + (3 - rem) as f64 * 0.8;
                }
            }
            if slack_after == 0 {
                score -= 5.0 * progress;
            } else if slack_after < 5 {
                score -= 3.0 * progress;
            }
            // Exact two-item pairing anticipation.
            if slack_after == next_item_size {
                score -= 3.0 + 3.0 * progress;
            }
            // Triple-fit chain anticipation with snug remainder.
            let ds = slack_after;
            if ds >= 3 * next_item_size && (ds - 3 * next_item_size) <= 4 {
                score -= 3.0 + 2.0 * progress;
            }
            // MUTATION: combined fine-grain + lookahead — reward when the
            // remaining slack after placing the next item is itself a snug
            // host for a mid-size follow-up (dead-space recycling).
            if slack_after > 12 && slack_after < 40 {
                let mid = slack_after / 2;
                if mid >= 10 && mid <= 35 {
                    score -= 1.2 + 1.2 * progress;
                }
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
            // Wasted-lookahead coupling scaled by progress.
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
            // Soft penalty when stranded residual is just below the next item.
            let gap = next_item_size - post_residual;
            if gap <= 8 && post_residual % 25 >= 20 {
                score += 2.0 * (1.0 - progress);
            }
            // MUTATION: stranded residual that is exactly half the next item
            // may pair with a future small item — mild forgiveness.
            if next_item_size >= 2 * post_residual && next_item_size <= 3 * post_residual && post_residual >= 8 {
                score -= 1.0 * (1.0 - progress);
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Dead-space ratio.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Fine-grained dead-space band shaping.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
        // Reward bins whose dead space hosts next item with exact or
        // near-exact leftover, scaled by progress.
        let ds = dead_space as u32;
        if ds >= next_item_size {
            let rem = ds % next_item_size;
            if rem == 0 {
                score -= 2.0 + 2.0 * progress;
            } else if rem <= 4 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // Dual-fit chain anticipation.
        if ds >= 2 * next_item_size && (ds - 2 * next_item_size) <= 5 {
            score -= 2.5 + 1.5 * progress;
        }
        if ds > next_item_size && ds < 2 * next_item_size && (ds - next_item_size) > 8 {
            score += 1.5;
        }
        // MUTATION: dead-space ratio refinement — penalize bins whose
        // unusable dead space exceeds a quarter of capacity unless the
        // dead space still hosts the next item.
        let dead_ratio = dead_space / bin_capacity.max(1) as f64;
        if dead_ratio > 0.25 && ds < next_item_size {
            score += (dead_ratio - 0.25) * 6.0 * (0.5 + progress);
        }
    }

    // Penalize awkward 25..35 residuals that rarely match future items.
    if !is_new_bin && post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Discourage new bins when any open bin can still fit next item too.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        // Harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        // New-bin lookahead: prefer opening a new bin only when the fresh
        // residual (capacity - item) can also host the next item snugly.
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            // Extra gate — fresh residual should be reusable for at least
            // one more copy of the next item.
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
            // MUTATION: fresh residual divisibility — a fresh residual that
            // is an exact multiple of the next item promises clean packing.
            if fresh >= next_item_size && fresh % next_item_size == 0 {
                score -= 2.5 + 2.0 * progress;
            }
        }
        // Resist opening bins when some open bin has a snug fit
        // for the current item (tightness-aware new-bin gate).
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        // Strongly resist new bins mid-stream when open bins
        // still have ample room on average.
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: resist new bins whenever any open bin residual is a
        // snug fit (within 5) for the current item — prevents wasted
        // near-perfect placements.
        if fitting_bins_count > 0 && avg_res <= item_size as f64 + 5.0 && avg_res >= item_size as f64 {
            score += 6.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Late-stream exact-fill chase — reward bins that can be
        // driven to zero residual by the current item.
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: combine tightness with lookahead — if this bin becomes
        // exactly the next item's size after placement, favor it strongly
        // (perfect two-step chain).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.5 + 2.5 * progress;
        }
        // MUTATION: penalize leaving residuals in the sparse 36..44 band
        // that rarely match typical item sizes.
        if post_residual >= 36 && post_residual <= 44 && next_item_size > 0 && next_item_size != post_residual {
            score += 1.0 + 1.5 * (1.0 - progress);
        }
    }

    score
}

