    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match (gap == 0) gets the largest bonus; decays with gap.
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize dead space more strongly.
        score += 3.0 + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
