    // Compare post_residual relative to mean residual of open bins.
    // Leaving a residual well below mean means this bin becomes "dead space" relative to others.
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap < 0.0 {
        score += 0.4 * (-mean_gap);
    } else {
        score -= 0.2 * mean_gap;
    }

