    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early in the stream and when many bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
