        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Discourage new bins when any open bin can still fit next item too.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        // Harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        // New-bin lookahead: prefer opening a new bin only when the fresh
        // residual (capacity - item) can also host the next item snugly.
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            // Extra gate — fresh residual reusable for one more next item.
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
        }
        // Resist opening bins when some open bin has a snug fit for the
        // current item (tightness-aware new-bin gate).
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        // Strongly resist new bins mid-stream when open bins still have
        // ample room on average.
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: pair-fit gate — open a new bin only if fresh residual
        // can host current+next with tiny slack; otherwise resist.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            let pair_slack = fresh as i64 - (item_size as i64 + next_item_size as i64);
            if pair_slack > 12 {
                score += 3.0;
            } else if pair_slack >= 0 {
                score -= 4.0;
            }
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Late-stream exact-fill chase — reward bins that can be driven
        // to zero residual by the current item.
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: consolidation gate — prefer bins whose post-residual
        // matches the next item exactly, tightening residual variance.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 2.5 + 2.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual) with a non-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere or the item is large relative to the residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If no open bin fits (we are the only candidate), opening is fine.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // Large items are better placed in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Reward leaving usable space for the next item.
            let slack_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * slack_ratio.min(1.0);
        } else {
            // Penalize creating dead space the next item cannot use.
            score += 10.0;
        }
    }

    // Global state: penalize placements that leave residual far from the mean
    // (encourages a balanced pool of residuals that future items can match).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins with larger residual when many bins are open (keeps bins usable).
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    // Slight reward for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // Smooth polynomial coupling: reward small post_residual more strongly as stream progresses
    let norm_pr = pr / cap;
    let tightness = 1.0 - norm_pr * norm_pr;
    score -= tightness * (1.0 + 2.0 * progress) * cap * 0.25;
    // Penalize large dead space non-linearly, amplified late in stream
    score += (norm_pr * norm_pr * norm_pr) * cap * (0.5 + 0.5 * progress);
    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * 0.35;
    }
    // Prefer bins tighter than the mean residual
    score += (mean_residual - pr) * 0.15;
    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - (pr - nxt) / cap) * 8.0;
        } else {
            score += 6.0;
        }
    }
    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let usable = (pr % 10 == 0) as f64 * 6.0
        + (pr % 20 == 0) as f64 * 4.0
        + (pr % 25 == 0) as f64 * 3.0
        + (pr % 5 == 0 && pr > 0) as f64 * 1.5;
    score -= usable;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving exactly enough room for next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 22.0;
        } else if pr > next_item_size {
            score -= 6.0 * ((pr - next_item_size) as f64 / cap).min(0.5);
        } else {
            score += 8.0; // next item can't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fractional fill of the bin: prefer bins that end up well-filled.
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= 10.0 * fill * fill;

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 25.0 - 8.0 * crowding.min(3.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // big items pair well in fresh bins
        }
    }

    // Mild stream-phase bias: early on, be picky; late, consolidate aggressively.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual < 10 {
