pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already tight.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= 2 * next_item_size {
                let rem = slack_after % next_item_size;
                if rem <= 3 {
                    score -= 2.5 + (3 - rem) as f64 * 0.8;
                }
            }
            if slack_after == 0 {
                score -= 5.0 * progress;
            } else if slack_after < 5 {
                score -= 3.0 * progress;
            }
            if slack_after == next_item_size {
                score -= 3.0 + 3.0 * progress;
            }
            let ds = slack_after;
            if ds >= 3 * next_item_size && (ds - 3 * next_item_size) <= 4 {
                score -= 3.0 + 2.0 * progress;
            }
            // MUTATION: exact two-item chain anticipation strengthened.
            if ds == 2 * next_item_size {
                score -= 4.0 + 2.0 * progress;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35;
            score += (next_item_size - post_residual) as f64 * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 8 && post_residual % 25 >= 20 {
                score += 2.0 * (1.0 - progress);
            }
            // MUTATION: penalize stranded residuals in the 25..35 awkward band
            // that rarely match typical item sizes.
            if post_residual >= 25 && post_residual <= 35 && next_item_size != post_residual {
                score += 1.5 + 2.0 * (1.0 - progress);
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
        if progress > 0.4 {
            score -= 3.0 * progress;
        }
    }

    // Time horizon.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Dead-space ratio.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
        let ds = dead_space as u32;
        if ds >= next_item_size {
            let rem = ds % next_item_size;
            if rem == 0 {
                score -= 2.0 + 2.0 * progress;
            } else if rem <= 4 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        if ds >= 2 * next_item_size && (ds - 2 * next_item_size) <= 5 {
            score -= 2.5 + 1.5 * progress;
        }
        if ds > next_item_size && ds < 2 * next_item_size && (ds - next_item_size) > 8 {
            score += 1.5;
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: pair-fit gate — open a new bin only if item+next fit snugly.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // MUTATION: mid-band dead-space reuse — reward bins whose dead space
        // can host the next item with small remainder, even in 12..30 band.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual with a nonlinear penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * 100.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        }
        // Penalize leaving a gap just smaller than the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Prefer bins with residual close to item_size (best-fit flavor),
    // penalize bins whose residual is much larger than the item.
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.10 * waste;

    // Global state coupling: when many bins are open relative to progress,
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let density = open_bins_count as f64 / (total_items.max(1) as f64);
    score -= density * 20.0 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a good candidate to absorb the item.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // New-bin candidate logic: only attractive when no open bin fits well
    // or residuals are fragmented (low mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_score = 55.0 - 40.0 * fragmentation + 10.0 * progress;
        // Compare against typical existing-bin scores; opening a new bin is
        // penalized unless fragmentation is severe.
        score = new_bin_score + (pr / bin_capacity as f64) * 100.0;
        if fitting_bins_count > 0 && fragmentation > 0.35 {
            score += 30.0; // keep using existing bins when they are still roomy
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;
    let next_norm = next_item_size as f64 / cap;

    // Smooth polynomial base: prefer small post_residual, with non-linear shaping
    let mut score = pr_norm.powi(2) * (1.0 + 2.0 * progress) + 0.5 * pr_norm;

    // Non-linear coupling of post-residual with item fill fraction
    score -= 0.8 * (1.0 - pr_norm) * fit_ratio * (1.0 - fit_ratio);

    // Stream-progress polynomial interaction: tighten bins as stream advances
    let tighten = 0.4 + 1.2 * progress * progress;
    score *= tighten;

    // Dead-space penalty: post-residual too small for any plausible future item
    let dead = ((15.0 / cap) - pr_norm).max(0.0) / (15.0 / cap);
    score += 1.5 * dead * dead;

    // Lookahead smooth coupling: reward if next item fits post-residual
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        score -= 0.6 * (fits.max(0.0)) * (1.0 - pr_norm);
        score += 0.3 * (-(pr_norm - next_norm)).exp() * pr_norm;
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 1.2 * last_chance * (1.0 - pr_norm);

    // New-bin candidate: penalize opening a bin mildly, scaled by alternatives
    if bin_residual == bin_capacity {
        let alt = fitting_bins_count as f64;
        score += 0.5 + 0.3 * alt + 0.5 * progress;
    }

    // Mean-residual smooth coupling
    score += 0.2 * (pr_norm - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted
    let waste_frac = pr / cap;
    score += 60.0 * waste_frac * waste_frac;

    // Modulo-class penalty: residues in awkward bands (e.g. 1..10, 11..20) are near-useless
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0; // dead space
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 35 {
        score -= 4.0; // still usable for small items
    } else {
        score -= 8.0; // large residual is valuable
    }

    // Perfect fit reward (harmonic alignment)
    if post_residual == 0 {
        score -= 40.0;
    }
    // Exact next-item fit reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Next item fits comfortably: reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize blocking
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap).min(1.0);
        // opening a new bin is cheap when few bins or when open bins are fragmented
        score = 45.0 - 30.0 * crowded - (open_bins_count as f64).ln() * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming, fresh capacity is good
        }
    }

    // Stream progression: early on, be more willing to open bins (long horizon to fill them)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress * (1.0 - (pr / cap));
    }

    // Mean residual coupling: if mean residual is low (bins mostly full), avoid wasting
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (subtract) when post_residual == 0.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Unusable dead space: residual < minimum item size (10) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Small awkward gaps (10..=30) are semi-dead space; penalize proportionally.
    if post_residual >= 10 && post_residual <= 30 {
        score += (30.0 - post_residual as f64) * 4.0;
    }

    // Large post_residual is still usable: mild reward.
    if post_residual > 40 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // If next item would be blocked by this placement's dead space, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        score += 40.0;
    }

    // Progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

