        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain <= 2 {
                score -= 2.0 + 3.0 * progress;
            } else if chain <= 6 {
                score -= 1.0 + 1.5 * progress;
            }
            // Penalize residuals that strand 7..15 of dead space after the
