pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post-residual nonlinearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_quality * fit_quality;

    // Penalize dead space that can't fit typical items (below 50 residual is risky).
    if post_residual < 50 {
        score += (50 - post_residual) as f64 * 0.8;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Avoid consuming space the next (large) item needs.
        if next_item_size > post_residual && post_residual < item_size {
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 2.0 * item_size as f64 && open_bins_count > 2 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is young.
    if bin_residual == bin_capacity {
        let good_open_exists = fitting_bins_count > 0 && (bin_residual.min(100) as f64 - item_size as f64).abs() < f64::MAX;
        if fitting_bins_count > 1 {
            score += 25.0 + 20.0 * progress; // prefer existing bins, more so late in stream
        } else if fitting_bins_count == 1 {
            score += 40.0; // existing bin is last chance -> keep it
        } else {
            score -= 10.0 * (1.0 - progress); // nothing fits; new bin fine early
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can pair this and next item
        }
    }

    // Mild preference for fuller bins among ties.
    score += 0.05 * (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
