#[inline]
fn dead_frac_proxy(bin_capacity: u32, dead_space: f64) -> f64 {
    dead_space / bin_capacity.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * coupling;
    // penalize large post-residual late in the stream more strongly
    score += 60.0 * norm_pr * progress * progress;
    // reward tight fits (small post_residual) especially when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - progress);
    }
    // lookahead: favor bins whose post_residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - ((pr - nxt) / cap).powi(2));
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }
    // mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).sqrt() * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "large waste" classes (e.g. 1..=5) are dead space -> penalize.
    let waste_class = post_residual % 10;
    if post_residual > 0 {
        if waste_class <= 5 {
            // tiny unusable slivers: heavy penalty proportional to closeness to 0
            score += 40.0 * (6.0 - waste_class as f64);
        } else {
            // usable slivers: mild reward for being in a "harmonic" class
            score -= 5.0 * (waste_class as f64 - 5.0);
        }
    }

    // Integer-division thresholds on post_residual: residual that can host
    // common future items (>=10) is valuable; residual < 10 is dead.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward (perfect harmonic match).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score -= 15.0;
        } else {
            score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here even after placement: slight penalty
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; only attractive when open bins
    // are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_pressure = mean_residual / bin_capacity as f64;
        score = 45.0 - 30.0 * avg_pressure - 10.0 * progress;
        if post_residual >= item_size {
            score += 5.0;
        }
    }

    // Tight fits (small post_residual relative to item) rewarded.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 10.0 / (1.0 + tightness);

    // Prefer filling bins with lower residual among equals (best-fit flavor).
    score += 0.05 * open_bins_count as f64;

    score
}

