    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Fine-grained dead-space band shaping.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        if dead_space >= next_item_size as f64 && dead_space < 2.0 * next_item_size as f64 {
            score -= (2.0 * next_item_size as f64 - dead_space) * 0.12;
        } else if dead_space < next_item_size as f64 && dead_space > 12.0 {
            score += (dead_space - 12.0) * (0.05 + 0.15 * progress);
        }
        // Dead-space ratio shaping — penalize middle-band waste, reward small dead space.
        let dead_frac = dead_space / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
            score += (dead_frac - 0.25) * 8.0;
        } else if dead_frac <= 0.25 {
            score -= (0.25 - dead_frac) * 4.0;
        }
        // Mid-band dead space reusable by next item.
        if dead_space >= 12.0 && dead_space < 30.0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are still roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Only open a new bin when no open bin can host both this and the next item.
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        // Stronger new-bin penalty when an open bin can host both this and next item.
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        // Extra new-bin penalty when an open bin fits both with small combined slack.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Strong preference for bins that fit both current and next items with near-zero combined slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // When many bins are open, reward filling the emptiest-but-usable bin to
        // reduce residual variance (consolidation pressure scales with open count).
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        // Penalize leaving large residuals in bins that could absorb the next item
        // twice, encouraging tight triple-fits.
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Reward bins whose dead space fits current + next item exactly
        // (two-item lookahead compaction).
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual == next_item_size {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable residuals (< minimum item size).
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0;
        }
        // Tight fit reward: small post residual relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain placement.
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize wasted chain potential, worse when residual is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins that come closer to mean
    // (balanced packing) unless it's a tight fit.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item, few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base penalty keeps existing bins preferred; relax when few bins fit.
        score += 250.0 - 150.0 * poor_fit - 100.0 * (1.0 - progress);
        // A new bin leaves full residual; slightly reward if item is large.
        score -= 0.3 * item_size as f64;
    }

    // Mild preference for filling more crowded bins (reduce open bin count pressure).
    score += 0.5 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward;
    // if post_residual is too small for the next item, penalize dead space.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            score -= 10.0 * (1.0 - (pr - n).abs() / cap);
        } else {
            score += 6.0 * (pr / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let poor_alternatives = (fitting_bins_count == 0) as f64;
        let big_item = (item_size as f64 / cap) > 0.6;
        score += 30.0; // base cost of opening a new bin
        score -= 45.0 * poor_alternatives;
        score -= 20.0 * fragmentation * fragmentation;
        if big_item {
            score -= 15.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 {
            score -= 10.0; // big next item: keep a fresh bin around
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * t * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins below mean residual (consolidating fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

