    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Late-stream exact-fill chase.
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: combine fine-grained residual fitting with lookahead —
        // when this placement leaves a residual that exactly matches a
        // plausible small item bucket, reward it more strongly late.
        if next_item_size > 0 && post_residual > 0 && post_residual <= 25 && progress > 0.5 {
            score -= (25 - post_residual) as f64 * 0.12;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling: tight fits are increasingly rewarded as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 8.0;

    // Penalize awkward dead space: residuals too small for typical future items.
    let dead = (pr / cap).powi(3);
    score += dead * 20.0;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= (1.0 - slack) * 6.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty when many bins are open (discourage bin proliferation early).
    score += (open_bins_count as f64).ln() * 0.5;

    // Slight preference for bins below mean residual (balance load smoothly).
    score += (pr - mean_residual) * 0.05;

    // New-bin candidate: make it mildly unattractive unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
