        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 1.2 * progress;
            } else if gap <= 2 {
                score -= 4.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 1.8 * (1.0 - progress);
            }
        }
        // Late-stream consolidation into nearly-full bins.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/2, 1/3, 1/4 of capacity)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Penalize leaving dead space that falls into a "useless" harmonic band:
    // residual too small to fit typical items (below quarter) is wasted capacity.
    if post_residual < quarter {
        score += 12.0 + (quarter - post_residual) as f64 * 0.35;
    } else if post_residual < third {
        score -= 4.0; // small-but-usable residual is fine
    }

    // Reward tight fits: post_residual in a harmonic residue class of the item
    // (exact fill is best).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual % (item_size.max(1)) == 0 {
        score -= 8.0; // residual divisible by item size -> future perfect stacking
    } else if post_residual % 10 == 0 {
        score -= 3.0; // round-number residual is easy to fill later
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this bin's remainder; penalize proportional waste
            score += (next_item_size - post_residual).min(bin_capacity) as f64 * 0.10;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual would be tiny dead space).
    if fitting_bins_count == 1 && post_residual >= quarter {
        score -= 20.0;
    } else if fitting_bins_count == 1 && post_residual < quarter {
        // still better than a fresh bin if waste is modest
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good (sub-half) fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin; grows slightly with open bin count pressure
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is cheaper than fragmenting old ones
        score -= progress * 10.0;
        // If mean residual across open bins is large, prefer reusing them instead
        score += mean_residual * 0.4;
        // Large items prefer fresh bins (harmonic >1/2 class)
        if item_size > half {
            score -= 25.0;
        }
        return score;
    }

    // Prefer filling bins whose residual is closest to the item (minimize post_residual),
    // with a mild bias toward bins below half-full to consolidate space.
    if bin_residual <= half {
        score -= 5.0;
    }

    // Normalize against mean residual: bins with below-average residual get priority
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest possible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Bonus for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the dead-space penalty above dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly favor reusing existing bins as the pool grows.
    if bin_residual != bin_capacity {
        score -= 2.0 + open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize slightly so it only wins when fits are bad.
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        // post-residual likely dead for the known next item: penalize.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Late-stream tightening: as the stream progresses, be less willing to leave medium gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Prefer bins whose residual is already below average (they are "nearly full").
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0;
    }

    score
}

