            if rem == 0 {
                score -= 2.0 + 2.0 * progress;
            } else if rem <= 4 {
                score -= 1.0 + 1.5 * progress;
            }
        }
        // Dual-fit chain anticipation.
        if ds >= 2 * next_item_size && (ds - 2 * next_item_size) <= 5 {
            score -= 2.5 + 1.5 * progress;
        }
        if ds > next_item_size && ds < 2 * next_item_size && (ds - next_item_size) > 8 {
            score += 1.5;
        }
    }

    // Penalize awkward 25..35 residuals that rarely match future items.
    if !is_new_bin && post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        // Discourage opening a new bin late when open bins are roomy.
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        // Discourage new bins when any open bin can still fit next item too.
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        // Harder to open bins early unless item is large.
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        // New-bin lookahead: prefer opening a new bin only when the fresh
        // residual (capacity - item) can also host the next item snugly.
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            // Extra gate: fresh residual should be reusable for at least
            // one more copy of the next item.
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
            // MUTATION: penalize fresh residual that lands in the awkward
            // 25..35 band after hosting the current item.
            if fresh >= 25 && fresh <= 35 && fresh < next_item_size {
                score += 3.0;
            }
        }
        // Resist opening bins when some open bin has a snug fit for the
        // current item (tightness-aware new-bin gate).
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        // Strongly resist new bins mid-stream when open bins still have
        // ample room on average.
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: pair-anticipation gate — if current item plus next item
        // fits into some existing open bin (estimated via mean residual),
        // resist opening a fresh bin.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 6.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        // Reward near-full consolidation late.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Late-stream exact-fill chase — reward bins that can be driven to
        // zero residual by the current item.
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: dead-space band 12..30 hosting next item — reward
        // moderately-sized reusable dead zones early.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post / cap * (1.0 + 0.5 * progress);

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post-residual (perfect chaining), penalize near-misses.
    if next > 0.0 {
        let gap = (post - next).abs();
        if gap < 1.0 {
            score -= 2.5; // perfect match for next item
        } else if next <= post {
            // next item fits: reward proportional to how snugly it fits
            score -= 1.5 * (next / post.max(1.0));
        } else {
            // next item does NOT fit in this bin: dead-space risk
            score += 0.8 * (post / cap);
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 1.0;
    }

    // Reward bins whose residual is already below average (consolidating waste),
    // penalize dumping into unusually roomy bins.
    score += 0.4 * (post - mean_residual) / cap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // New-bin candidate handling: only open a new bin if current bins are poor fits.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; make it unattractive unless item is large
        // relative to typical residuals (large items deserve fresh space).
        let large = item / cap;
        score = 1.5 + large * 2.0 - 0.5 * progress;
        if next > 0.0 && next <= post - item as f64 {
            score -= 0.6; // fresh bin can also chain the next item
        }
    }

    // Small penalty for high fragmentation (very small post residual that
    // likely fits nothing: 1..=9 dead space).
    if post > 0.0 && post < 10.0 {
        score += 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (unusable gaps hurt later).
    score += 0.08 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits: small post residual relative to item size.
    if item_size > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap smaller than next item.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate logic: empty bin should only win when open bins are
    // congested (few fitting bins) or residuals are heavily fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (fitting_bins_count as f64).recip();
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 18.0 + 10.0 * progress - 15.0 * congestion - 12.0 * fragmentation;
    } else {
        // Mild preference for bins with below-mean residual (consolidate waste).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early on, be more willing to open bins (explore);
    // late, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);
    score += progress * 0.03 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward filling the bin deeply: normalized fill fraction with cubic coupling.
    let fill = (cap - post) / cap;
    score -= 12.0 * fill * fill * fill;

    // Smooth non-linear interaction between post_residual and stream progress:
    // late in the stream, waste is more costly (fewer chances to recover).
    let progress_coupling = (0.5 + 0.5 * progress) * (post / cap) * (post / cap);
    score += 18.0 * progress_coupling;

    // Penalize bins whose residual deviates badly from the mean residual (non-linear divergence).
    let diff = residual - mean_residual;
    score += 0.02 * diff * diff / (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward saving this bin's leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - (post - nxt) / cap;
            score -= 6.0 * tightness * tightness;
        } else {
            // Next item won't fit here; mildly penalize leaving large unusable residue.
            score += 0.05 * post * (1.0 + progress);
        }
    }

    // New-bin candidate: empty bin should only win when no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty for opening a new bin, relaxed late in the stream.
        score = 55.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If other bins fit poorly (high mean residual vs item), opening new bin is acceptable.
        let fit_quality = item_size as f64 / mean_residual.max(1.0);
        score -= 20.0 * fit_quality * fit_quality;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
