    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
