    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: classify dead space into capacity fractions ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Dead space is worst when it is small-but-nonzero (unusable for typical items).
    // Harmonic class: which "slot band" does post_residual fall into?
    // Band 0: post_residual == 0 -> perfect fit, huge reward.
    // Band 1: 0 < post_residual < 10 -> worst dead space, heavy penalty.
    // Band 2: 10 <= post_residual < 20 -> still risky.
    // Band 3+: progressively less bad.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score += 30.0; // tiny dead space, nearly unusable
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score -= 2.0;
    } else {
        score -= 8.0; // large residual can host future items
    }

    // --- Integer-division thresholds on post_residual (harmonic classes of C/2, C/4) ---
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0; // bin still half-capable
    } else if post_residual >= quarter && post_residual < half {
        score += 3.0; // quarter-band: moderate utility
    }

    // --- Modulo arithmetic on post_residual: reward residuals in friendly classes ---
    // Residuals congruent to 0 mod 10 align with common item sizes (multiples of 10).
    let m10 = (post_residual % 10) as f64;
    score += 0.6 * m10; // misaligned residue penalized proportionally
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0; // aligned residual, easy future fit
    }

    // --- Lookahead: does next item fit exactly into post_residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // partial credit scaled by how much slack remains after next item
            let after_next = post_residual - next_item_size;
            score -= 8.0 - 0.15 * (after_next as f64);
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 6.0;
            }
            // harmonic class of the gap: how badly does next item miss?
            let miss = (next_item_size - post_residual) as f64;
            score += 0.1 * (miss % 20.0);
        }
    }

    // --- Last-chance bonus: only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral baseline; make it unattractive unless current
        // placements would create bad dead space elsewhere. Penalize mildly so we
        // prefer filling existing bins with decent fits, but reward when stream
        // is early (many items left) and item is large (hard to place later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0; // default cost of a fresh bin
        score -= 10.0 * (1.0 - progress); // early stream: fresh bins are OK
        if item_size > (bin_capacity * 3 / 5) {
            score -= 12.0; // large item: keep it in a fresh bin for flexibility
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins first) ---
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 0.10 * (mean_residual - bin_res_f);
    } else {
        score += 0.05 * (bin_res_f - mean_residual);
    }

    // --- Congestion modulation: many open bins -> prefer consolidating into tight fits ---
    if open_bins_count > 4 {
        score += 0.02 * (post_residual as f64); // amplify dead-space penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
