pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold typical future items are wasted.
    if post_residual > 0 {
        // Dead-space threshold: residual below smallest plausible item is pure loss.
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // near-unusable gap
        } else if post_residual < 35 {
            score += 8.0;  // marginal gap
        } else {
            // Larger leftovers still useful: mild reward for keeping usable space.
            score -= 6.0;
        }
    } else {
        // Perfect fill: strongly rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_residual as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 18.0; // chaining to a near-perfect second fit
        } else if next_gap < 25 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item won't fit after this placement even though it fits now: penalize.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual >= 10 {
            score -= 10.0; // decent fit in the only option
        }
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: an empty bin is a blank slate.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins would leave bad gaps
        // or when no open bin fits well.
        if post_residual >= 60 {
            score -= 12.0; // fresh bin keeps lots of usable space
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is high, they can absorb the item: penalize new bin.
        if mean_residual > item_size as f64 + 15.0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: next item fits exactly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }

    // Reward if next item fits into the post residual (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for tight chain (little waste left after both).
        let chain_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 - chain_waste as f64) * 0.05;
    }

    // Penalize post residuals too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize small unusable post residuals in general.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fit relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Relative-to-mean coupling: prefer bins below mean residual (fill fuller bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer opening a new bin when item is large and open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 + item_size as f64 * 0.1 * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins late in the stream.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
