pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect-fit bonus: strongly favor bins that get filled exactly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits non-linearly
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * tightness * tightness;
    }

    // Dead-space penalty: residuals too small for any plausible item (items >= 1,
    // but small residuals < 10 are nearly useless in the classic regime)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating residual that blocks the known next item
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    score += 0.05 * open_bins_count as f64;
    score -= 0.10 * mean_residual;

    // New-bin candidate logic: empty bin gets a baseline cost that shrinks
    // when the stream is early or the fit into existing bins is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 45.0 - 30.0 * (1.0 - progress) - 60.0 * poor_fit;
        // Opening a new bin is more attractive when many bins exist but residuals are fragmented
        if mean_residual < 0.35 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 15.0;
        }
    } else {
        // Mild preference for reusing larger-residual bins when fits are comparable
        score += 0.02 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Late-stream consolidation: as we approach the end, squeeze into existing bins
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
