    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: cubic penalty on small residuals (unusable gaps).
    if pr > 0.0 {
        let dead = (1.0 - pr / cap).max(0.0);
        score += 12.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead);
    }

    // Lookahead: reward if next item fits in post_residual, penalize otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (nx / cap) * (1.0 + progress);
        } else {
            score += 10.0 * (1.0 - pr / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    score += 0.05 * (open_bins_count as f64) * (1.0 - mean_residual / cap).max(0.0);

    // New-bin candidate: keep it slightly attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (pr / cap); // equals item_size/cap for new bin
        score += 8.0 - 10.0 * fit_quality + 15.0 * (1.0 - progress);
    }

    score
}

