            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Combined fine-grained fitting + lookahead anticipation.
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= next_item_size {
                score -= 2.0;
            }
            if slack_after > 0 && slack_after % next_item_size == 0 {
                score -= 2.0 * (1.0 - progress);
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio penalty.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // Wasted-gap anticipation.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = (next_item_size - post_residual) as f64;
        let near = 1.0 - (wasted / next_item_size.max(1) as f64);
        score += wasted * 0.14 * (1.0 - progress) + wasted * 0.08 * progress;
        score += near * 1.5 * (1.0 - progress);
        if post_residual >= 12 {
            score += 3.0;
        }
    }

    if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && post_residual > 0 {
        score += 1.2 + 2.0 * progress;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // New-bin leftover aligned with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin dead-space control.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        // New-bin lookahead anticipation: leftover can absorb next item nearly exactly.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
        // Pair-fit anticipation: new bin can hold current + next item together.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
            if post_residual - next_item_size == 0 {
                score -= 1.2 * progress;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead space penalty: residuals below the minimum item size are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class logic: bucket post_residual into capacity fractions
    let frac = post_residual as f64 / cap; // 0..1
    // Class boundaries at 1/8 fractions; small classes (<1/4) are hard to fill
    if frac < 0.125 {
        score += 25.0;
    } else if frac < 0.25 {
        score += 12.0;
    } else if frac < 0.5 {
        score += 4.0;
    }

    // Integer-division thresholds on post_residual vs next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong chaining reward
            score -= 18.0;
            // Extra reward if next item would leave a "good" harmonic class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            if next_post == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize if it creates a lonely small residual
            score += 8.0;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean (best-fit style)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for consolidating when many bins are open
    score += open_bins_count as f64 * 0.3;

    // Slight stream-awareness: later in the stream, be more greedy about exact fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual == 0) as i32 as f64 * 20.0;

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score = cap * 0.55 - item_size as f64 * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize the "unusable gap" regime hard.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fills: small post_residual relative to capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits perfectly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fill = next_item_size as f64 / post_residual as f64;
        if next_fill > 0.7 {
            score -= 30.0 * next_fill;
        } else if next_item_size > post_residual {
            // next item won't fit here; slightly penalize leaving a large gap
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Penalize the fresh bin mildly; the
    // penalty grows with the number of open bins (waste of capacity).
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if current item is large and mean residual is small, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

