        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
        // New-bin dead-space control.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
