    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            if slack_after <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= next_item_size {
                score -= 2.0;
            }
            if slack_after > 0 && slack_after % next_item_size == 0 {
                score -= 2.0 * (1.0 - progress);
            }
            // Avoid leaving slack that neither fits next item nor is tiny:
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let wasted = (next_item_size - post_residual) as f64;
        let near = 1.0 - (wasted / next_item_size.max(1) as f64);
        score += wasted * 0.14 * (1.0 - progress) + wasted * 0.08 * progress;
        score += near * 1.5 * (1.0 - progress);
        if post_residual >= 12 {
            score += 3.0;
        }
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
        // New bin can host current + next item comfortably: prefer it.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1)
            && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: normalized fill ratio, quadratic coupling with progress.
    let fill = (bin_residual as f64 - pr) / cap; // fraction of bin filled by item
    let tightness = (1.0 - pr / cap).powi(2);
    score -= 18.0 * fill * tightness * (0.6 + 0.8 * progress);

    // Penalize dead space non-linearly: small residuals are hard to reuse.
    let dead = pr / cap;
    score += 25.0 * dead * dead * (1.0 + progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // existing bins fit, but relax if it would leave a large usable gap elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
        if fitting_bins_count > 1 {
            score += 12.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 5.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (consume the most crowded space first).
    score -= 4.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in low modulo classes is hard to reuse
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        score += (10 - class) as f64 * 0.7; // prefer residuals landing on multiples of 10
        if pr < 10 {
            score += 25.0; // tiny dead space is nearly unusable
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count == 0 {
        score += 15.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual > 60 || fitting_bins_count == 0 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item stream: fresh bins fine
        }
    }

    // Lookahead harmony: if next item fits the post-residual, reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic check: combined usage lands on a clean class
            if (item_size + next_item_size) % 100 == 0 {
                score -= 25.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins tighter than the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (<=10) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 7.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin's remaining space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // New empty bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this item would create large dead space elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        score = 25.0 + 8.0 * (open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0; // last chance bin exists, prefer using it
        }
        if post_residual == bin_capacity && open_bins_count == 0 {
            score -= 25.0; // nothing open yet, must open
        }
        // If the next item could combine with current item in a fresh bin, mild bonus.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 6.0;
        }
        return score;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing space
    // rather than spreading items thinly.
    score += 0.35 * (open_bins_count as f64);

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        }
    }

    // Slight preference for bins below mean residual (keeps large residuals available).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    score
}

