            score -= 0.8 * (1.0 - progress);
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large share of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 0.35 * post_residual as f64;
        }
        // Perfect chain: post residual exactly matches lookahead size.
        if post_residual == next_item_size {
            score -= 12.0;
