    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score = 55.0 + 0.25 * item_size as f64 - 20.0 * fragmentation / bin_capacity as f64 - 30.0 * pressure;
