        // COMBINED: mid-band dead space that hosts next item snugly is a
        // strong consolidation candidate regardless of progress.
        if dead_space >= 12.0 && dead_space < 30.0 && ds >= next_item_size && ds - next_item_size <= 3 {
            score -= 1.5 + 1.0 * (1.0 - progress);
        }
    }

    if !is_new_bin && post_residual >= 25 && post_residual <= 35 && next_item_size > 0 && next_item_size != post_residual {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if open_bins_count > 1 && next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0 * (1.0 - progress);
        }
        if progress < 0.3 && item_size < 50 && open_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 {
            let fresh = bin_capacity.saturating_sub(item_size);
            if fresh >= next_item_size && fresh - next_item_size <= 4 {
                score -= 5.0;
            }
            if fresh >= 2 * next_item_size {
                score -= 2.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_gap = mean_residual.min(next_item_size as f64);
            if best_gap <= 6.0 {
                score += 8.0;
            }
        }
        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // COMBINED: allow new bin when current item + next item would leave
        // near-zero residual in a fresh bin (pair-anticipation gate).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_rem = bin_capacity - item_size - next_item_size;
            if pair_rem <= 6 {
                score -= 4.0 + (6 - pair_rem) as f64 * 0.5;
            }
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // COMBINED: snug residual (post_residual within 3 of next item) is a
        // strong pair candidate late in the stream.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 1.0 + 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills
            score -= 15.0 * (1.0 - (post - nx) / cap);
        } else {
            // next item won't fit here: penalize wasted space that can't serve next item
            score += 10.0 * (nx / cap);
        }
    }

    // Penalize dead space relative to mean residual: creating residual far below mean
    // wastes capacity that other bins could use better
    if post < mean_residual {
        score += 0.5 * (mean_residual - post);
    } else {
        score -= 0.2 * (post - mean_residual);
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the tightest (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are all poor fits (large post_residual vs item scale)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening new bins early; late in stream, when item is large,
        // a fresh bin may be better than fragmenting
        let item_frac = item_size as f64 / cap;
        score += 30.0 * (1.0 - progress) - 10.0 * item_frac;
        // if mean residual is large (open bins are empty-ish), opening new bin is wasteful
        score += 0.3 * mean_residual;
    }

    // Slight penalty for tiny unusable remnants
    if post > 0 && post < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

