        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Mid-range dead space that can still absorb the next item: mild reward.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that can't fit typical future items (post_residual < 10 is dead).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual > 50 {
        score += 4.0; // large leftover is wasteful unless it's a fresh bin
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Penalize if next item almost fits (near-miss creates temptation/waste).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fresh-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = if fitting_bins_count > 0 {
            (item_size as f64 / bin_residual as f64) * 0.5 + (mean_residual / bin_capacity as f64) * 0.5
        } else { 1.0 };
        // Open new bin when mean residual is large (bins fragmented) or few bins open.
        score = 20.0 + 40.0 * (1.0 - avg_fit_quality) + 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 60.0; // don't abandon the only fitting bin
        }
        if next_item_size > 0 && next_item_size <= 50 {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing.
    if open_bins_count > 2 && mean_residual < item_size as f64 * 1.5 {
        score -= 5.0;
    }

    score
}

