        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: pair-fit anticipation — opening a new bin that can hold both
        // current and next item exactly is attractive only when few bins fit.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1)
            && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // NEW: graded dead-space vs next-item coupling — dead space that is a
        // near multiple of next_item_size is recoverable, otherwise penalize.
        if next_item_size > 1 && dead_space >= next_item_size as f64 {
            let drem = (dead_space as u32) % next_item_size;
            if drem > 0 && drem <= 3 {
                score -= 1.4 * (1.0 - progress);
            } else if drem >= next_item_size.saturating_sub(3) {
                score -= 0.9 * (1.0 - progress);
            }
        }
        // NEW: late-stream exact-fill anticipation.
        if progress > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 classes
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals 1..9 are hard to fill (min item 1..100 unknown, assume small)
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr == 10 {
        score -= 30.0; // exactly fills with smallest class item
    } else if class == 0 {
        score -= 15.0; // round residuals are reusable
    } else if class == 5 {
        score -= 8.0;
    }

    // Integer division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 10.0;
    } else if pr < 2 * quarter {
        score += 3.0;
    } else if pr < 3 * quarter {
        score -= 5.0;
    }

    // Next item lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0);
        } else {
            // next item won't fit here; prefer keeping larger residuals elsewhere
            score += 5.0;
        }
        // harmonic coupling: next_item_size mod 10 aligned with pr mod 10
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 12.0;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 80.0 + 50.0 * progress; // discourage opening when fits exist
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 20.0; // big next item: fresh bin useful
        }
        score += fragmentation * 0.1;
    }

    // Prefer tighter bins among fitting ones
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more harshly than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space relative to lookahead
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

