pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 45.0; // perfect two-item fill
        } else {
            score += gap as f64 * 0.8;
        }
        // Penalize post_residual that is small but nonzero (dead space unusable for next item)
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 12.0;
        }
