    // Tight fit reward relative to bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 15.0;
    } else if fill_ratio > 0.7 {
        score -= 6.0;
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

