    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and item is small
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0 + 0.15 * item_size as f64;
