        if next_item_size > 0 && item_size >= 70 && next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Early stream: be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score += 8.0;
    }

    score
}

