pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear penalty for awkward dead space (mid-range residuals are least useful)
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 18.0 * awkward * (0.5 + 0.5 * progress);
    // Reward tight fits more strongly as the stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
    // Interact with mean residual: penalize deviating from fleet average
    score += 0.15 * (mean_residual - pr).abs();
    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }
    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 10.0 * (1.0 - (ni / pr.max(1.0)).min(1.0));
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }
    // Mild pressure against bin proliferation early on
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fractions
    // of capacity (0, 25, 50, 75) and multiples of common item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill, always best
    } else {
        // quantize residual into capacity fractions
        let frac = (pr * 4) as f64 / bin_capacity as f64;
        let near_frac = (frac - frac.round()).abs();
        score += near_frac * 30.0; // penalize being between quarter-capacity marks

        // modulo classes: residuals divisible by 10 are more reusable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }

        // dead-space penalty: tiny residuals are unusable
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }

        // lookahead coupling: reward if next item fits exactly in post_residual
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size <= pr {
                score -= 10.0 + (pr - next_item_size) as f64 * 0.2;
            } else {
                // next item won't fit here: penalize wasting this bin's space
                score += 8.0;
            }
        }
    }

    // last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // mild pressure against bin proliferation when many bins are open
    score += open_bins_count as f64 * 0.5;

    // phase-based tuning: early stream, be a bit greedier about tight fits
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - phase) * (bin_residual - post_residual) as f64 * 0.1;

    // new-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 55.0 + post_residual as f64;
        if fitting_bins_count == 0 { score -= 30.0; }
        if next_item_size >= item_size { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
