pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Super-linear penalty on mid-range wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Tight fit reward: leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins
    // (penalize new-bin candidate relatively, reward reuse).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure-scaled penalty.
        score += 25.0 + pressure * 10.0;
    } else {
        score -= pressure * 3.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins used first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open new bins to build a pool.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

