                score -= 6.0 * (1.0 - progress);
            } else if slack_after <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if slack_after >= next_item_size {
                score -= 2.0;
            }
            if slack_after > 0 && slack_after % next_item_size == 0 {
                score -= 2.0 * (1.0 - progress);
            }
            // NEW: graded reward for slack that keeps future divisibility.
            if slack_after > 0 && next_item_size > 0 && slack_after >= next_item_size {
