    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: bonus if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.3 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Compare residual against mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // and nothing tight is available.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

