            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize small residuals slightly.
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a bin is attractive only if the fit
    // here would be poor (large post_residual) or the bin is nearly full.
    if bin_residual == bin_capacity {
        // Empty new bin: prefer it when the item is large or current bins are tight.
        let tightness = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, prefer filling existing bins; late, opening fresh bins is fine.
        score += 45.0 * (1.0 - progress) - 20.0 * tightness;
        if item_size > bin_capacity / 2 {
