        }
    } else {
        // Existing bin: reward using bins whose residual deviates favorably from mean.
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Prefer consolidating into bins with larger residual when item is small.
    if item_size < 20 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Mild penalty on bin count pressure to encourage reuse of open bins.
    if bin_residual < bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

