pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: bins whose residual falls into
    // "nice" residue classes (divisible by small integers) are more
    // likely to be exactly filled by future items.
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fits).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill: always prefer
    } else {
        // Harmonic divisibility bonuses: residual that is a multiple of
        // common item sizes (or divides evenly) is reusable dead space.
        let mut harmonic_bonus = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                harmonic_bonus += 4.0;
            }
        }
        score -= harmonic_bonus;

        // Penalize residuals in "awkward" classes: small odd leftovers
        // below the minimum item size are dead space.
        if post_residual < 10 {
            score += 50.0;
        }

        // Lookahead coupling: if the next item fits exactly into the
        // post residual, strongly favor this bin.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size <= post_residual {
                // next item fits but leaves another residue: mild reward
                // scaled by how harmonically the new residual behaves.
                let new_res = post_residual - next_item_size;
                if new_res == 0 {
                    score -= 150.0;
                } else if new_res % 10 == 0 {
                    score -= 20.0;
                }
            } else {
                // next item cannot follow in this bin: penalize slightly,
                // unless this bin is a "last chance" fit.
                score += 10.0;
            }
        }

        // Dead-space penalty: quadratic in smallness of post_residual
        // relative to item scale, but only for non-harmonic residuals.
        if post_residual % 10 != 0 {
            let frac = post_residual as f64 / cap;
            score += 30.0 * (0.1 - frac).max(0.0) * 10.0;
        }

        // Last-chance bin: if only this bin fits, strongly prefer using
        // it over opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 80.0;
        }

        // New-bin candidate: neutral baseline; prefer it only when all
        // open bins would waste a lot (large mean residual mismatch).
        if bin_residual == bin_capacity {
            // new bin gets post_residual = cap - item_size; add a mild
            // opening cost, discounted late in the stream or when open
            // bins are nearly full on average.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            let opening_cost = 25.0 * (1.0 - 0.5 * progress);
            let waste_pressure = ((mean_residual - (cap - item_size as f64)) / cap).max(0.0);
            score += opening_cost - 40.0 * waste_pressure;
        }

        // Prefer fuller bins overall: reward low residual fraction.
        score -= 0.05 * (cap - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item are pure loss; penalize them super-linearly.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement still accommodates the
    // lookahead item (keeps future options open).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage adding a new one;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins below the mean residual (filling emptier bins keeps
    // tighter bins available for small items).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

