            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if post_residual == 0 && progress > 0.4 {
            score -= 3.0 * progress;
        }
        // MUTATION: dead-space reuse bonus — bins whose dead space exactly
        // fits the next item with zero leftover get a mild reward.
        if next_item_size > 0 && (dead_space as u32) >= next_item_size && (dead_space as u32) % next_item_size == 0 && post_residual > 0 {
            score -= 0.8 + 0.8 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space quadratically.
    if post_residual < item_size {
        score += (item_size as f64 - post_residual as f64) * 1.5;
    }
    if post_residual < 10 {
        score -= 8.0; // near-perfect fit reward
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer tighter bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor keeping space flexible); late, prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 20.0 * progress - 10.0 * (1.0 - progress);
        if open_bins_count > 3 {
            score += (open_bins_count as f64 - 3.0) * 2.0;
        }
    } else {
        // Existing bins become more attractive as the stream progresses.
        score -= 6.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, scaled by a smooth progress-coupled factor
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: quadratic dead-space penalty that intensifies late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one deviates from mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Slight preference for fuller bins overall
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

