            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // New-bin leftover aligned with next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        // New-bin dead-space control.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.10;
        }
        // New-bin lookahead anticipation: leftover can absorb next item nearly exactly.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 3.0 * (1.0 - progress);
        }
        // BORROWED: reward a new bin that can host both current and next item.
        if fitting_bins_count > 0 && item_size <= next_item_size.max(1) && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score -= 5.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        // Dead space just below next item size gets graded penalty.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Fine-grained residual fitting combined with lookahead multiplicity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // NEW: mid-range dead space that still fits the next item is valuable.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes mod capacity fractions and reward "usable" classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 1: leftover fits a small item (<= 10) -> dead space, penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Class 2: leftover in [10, 30) — moderately reusable.
    else if post_residual < 30 {
        score -= 5.0;
    }
    // Class 3: leftover in [30, 60) — awkward mid-range, mild penalty.
    else if post_residual < 60 {
        score += 3.0;
    }
    // Class 4: large leftover (>= 60) — very reusable, reward.
    else {
        score -= 12.0;
    }

    // Modulo coupling: leftover divisible by common item sizes is reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Integer-division threshold: how many more items of typical size fit.
    let fits_more = post_residual / 20; // typical small item ~20
    score -= fits_more as f64 * 4.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: slightly favor bins whose leftover
            // is small so we don't strand capacity.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity or open-bin fits are poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // baseline: new bin costs roughly the wasted space it implies
        score = cap - pr - item_size as f64; // = 0 baseline, adjust below
        if frac > 0.5 {
            score -= 15.0; // big items fine in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, avoid hoarding many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && open_bins_count > 4 {
            score += 20.0;
        }
    }

    // Tie-break with mean residual: prefer bins below mean residual
    // (tighter bins get used first, keeping loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.65;
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
