        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
            if post_residual - next_item_size == 0 {
                score -= 1.2 * progress;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1,10] is nearly unusable
    // (min item size is 1, but tiny gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual cannot host next item: mild penalty scaled by wasted fraction
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the item would leave a
    // large, flexible residual or when current bins are crowded/poorly fitting.
    if bin_residual == bin_capacity {
        let tight_fit = fitting_bins_count == 0
            || (post_residual <= 10 && post_residual > 0)
            || mean_residual < item_size as f64 * 0.5;
        if tight_fit {
            score -= 30.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Prefer bins whose residual is close to the item (snug fit) over huge
    // residuals being consumed by small items.
    score += 0.15 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

