    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            score -= 50.0;
        } else {
            // next item cannot follow here; penalize dead space
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 80.0 + 2.0 * open_bins_count as f64;
    }

    // Waste penalty: unusable small leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Late in stream: consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

