pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    score -= 0.9 * (1.0 - (post_residual as f64) / cap) * (item_size as f64);

    // Penalize large dead space that few items can use
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.35; // big hole penalty
    }

    // Lookahead: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 4.0 + 0.5 * (nxt / cap);
        } else {
            score += 1.5 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (bin_residual as f64 / cap);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 3 && mean_residual > (item_size as f64) {
        score -= 2.0;
    }
    score += 0.15 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / cap));

    // New-bin candidate: keep it neutral-to-slightly-bad unless residual is full capacity
    if bin_residual == bin_capacity {
        score += 2.5 + progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
