pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (low post_residual), with non-linear sharpening over stream progress.
    let mut score = post * (1.0 + 1.5 * progress * norm_post);

    // Polynomial coupling of post_residual with progress: late in the stream,
    // dead space is penalized quadratically.
    score += 8.0 * progress * norm_post * norm_post * cap;

    // Reward using nearly-full bins: smooth cubic term favoring small residuals.
    score -= 6.0 * (1.0 - norm_post).powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits, scaled by fit tightness.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress) * (1.0 - norm_post);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation avoidance),
    // as a smooth quadratic deviation term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Lookahead: if the next item fits into the post residual, reward this placement;
    // otherwise penalize leaving a residual that is almost-but-not-quite usable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (1.0 - post / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.3 * (open_bins_count as f64) * progress;

    // New-bin candidate shaping: an empty bin gets a moderate score so it wins
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 0.5 * cap * (1.0 - progress) + 10.0;
    }

    score
}

