    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is tight/fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // prefer new bins early (spread load), penalize later
        score += 30.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs();
