    // Mild pressure to close nearly-full bins
    if post_residual <= 20 && post_residual > 0 {
        score -= 8.0;
    }

    // Tie-break: integer-division threshold on item size vs residual
    if bin_residual / (item_size.max(1)) >= 2 {
        score -= 3.0;
    }

