pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        // Dead space below minimum item size is pure waste.
        score += 60.0 * (1.0 + progress);
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 + progress);
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 50.0;
    }

    // Penalize large post-residuals mildly (wasted capacity).
    score += 0.15 * (post_residual as f64);

    // Open-bin pressure: discourage opening new bins when many bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count.
        score += 8.0 * (open_bins_count as f64);
        // Early in stream, opening bins is fine; later, prefer filling.
        score += 30.0 * progress;
        // If a fitting bin exists and it's a last-chance bin, strongly avoid new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // Reward using last-chance bins heavily.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Reward tight fits relative to mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty.
        score += 6.0;
    }

    score
}

