        if progress > 0.35 && progress < 0.75 && open_bins_count > 3 && avg_res > 40.0 {
            score += 5.0;
        }
        // MUTATION: resist new bins when item is small and open bins
        // collectively have enough slack.
        if item_size <= 20 && open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
            score += 4.0;
        }
    } else {
