            score += 0.8 * (next_item_size - post_residual) as f64;
        }
        // If next item fits exactly in the post residual, reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early,
    // acceptable late or when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        let mut penalty = 45.0 * (1.0 - t);          // early: avoid new bins
        penalty += 20.0 * (1.0 - pressure);          // plenty of residual space left: avoid waste
