    }

    // Mild preference for filling already-open bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Slight global balance: prefer bins whose residual is near the mean.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
