        // Reward near-full consolidation late in the stream.
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        // Dead-space ratio lookahead.
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        // Strong preference for bins that fit both current and next items with near-zero combined slack.
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        // Consolidation pressure when many bins are open.
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        // Penalize leaving large residuals in bins that could absorb the next item twice.
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-space ratio shaping.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        // Lookahead anticipation — chain of fits with small remainder.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
        }
        // Combined: reward bins whose dead space fits current + next item exactly.
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        // Mid-band dead space reusable by next item.
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        // New: combine fine-grained residual fitting with chain anticipation —
        // reward bins whose residual after fitting is a near-exact multiple of next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse buckets via integer division.
    // Residual classes of size 10 (capacity 100): 0 => near-perfect fit.
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,                       // perfect/near-perfect fit
        1 => score -= 12.0,                       // still very usable
        2 => score -= 5.0,                        // moderate
        3 => score += 3.0,                        // half-bin dead zone
        4 => score += 8.0,                        // poor
        _ => score += 14.0,                       // nearly empty bin wasted on small item
    }

    // Fine harmonic: reward even multiples (post_residual % 5 == 0) which
    // align with common item sizes drawn from coarse grids.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: penalize if post_residual cannot host the next item,
    // reward if it exactly or comfortably hosts it.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 10.0; // chain of perfect fits
            } else if slack < 10 {
                score -= 6.0;
            } else {
                score += slack as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins are badly fragmented
    // or the item is large relative to the best available residuals.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from being opened frivolously.
        score += 20.0;
        // Large items benefit from a fresh bin early in the stream.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If mean residual across open bins is small, open bins are crowded:
        // a new bin is more attractive.
        score -= (mean_residual / bin_capacity as f64) * 12.0;
        // Late in the stream, consolidation matters more: penalize new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins => prefer packing into existing ones.
        score += open_bins_count as f64 * 0.8;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
