pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 15 {
        score += 10.0;
    } else if post_residual <= 25 {
        score += 4.0;
    }

    // Reward near-perfect fits (small post_residual) more aggressively.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (creates a perfect follow-up fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use this tiny gap: dead space confirmed.
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading out; penalize slightly per open bin.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to item size or many bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A fresh bin is good when open bins are tight (mean residual low)
        // or there are no fitting alternatives; bad when open bins are roomy.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        } else {
            score += mean_residual * 0.3;
        }
        // Mild late-stream preference to keep bins consolidated.
        score += progress * 5.0;
    }

    score
}

