    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that
            let post2 = post_residual - next_item_size;
            score -= 150.0;
            score += post2 as f64 * 0.5;
        } else {
            // dead space: next item can't use it
            score += 80.0;
