    // Penalize creating tiny unusable residuals (below typical item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins with residuals below mean (tighter bins first), keep slack bins for later
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in stream: keep flexibility, discourage over-opening; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: mildly penalized so existing bins preferred unless poor fits
        score += 40.0 * (1.0 - progress);
    } else if open_bins_count > 1 {
        score -= 10.0;
    }

    score
}

