pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on residual waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits exactly in the post residual,
    // penalize if next item can't fit the leftover (dead space risk).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // leftover too small for next item: penalize proportionally
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // Many open bins: discourage fragmenting further; few open bins: allow slack.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 2.0;

    // Bin much tighter than average residual: good candidate.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.4;

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual > 0 { 0.0 } else { 0.0 };
        let _ = bad_fit;
        // cost of a fresh bin grows with stream progress and open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + progress * 40.0 + open_bins_count as f64 * 3.0
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
        // If this bin is a last resort (no other fitting bin), new bin is cheap.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
    }

    score
}

