        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        // New: reward bins whose dead space is exactly the next item (perfect chain).
        if next_item_size > 0 && dead_space == next_item_size as f64 {
            score -= 3.0 * (1.0 - progress);
        }
        // New: penalize mid-range dead space that no typical item can use.
        if next_item_size > 0 && post_residual > 0 && dead_space > 5.0 && dead_space < next_item_size as f64 {
            score += (next_item_size as f64 - dead_space) * 0.12 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;

    // Core: penalize leftover space non-linearly (quadratic + cubic saturation)
    let mut score = pr + 0.9 * (pr * pr) / cap + 0.4 * (pr * pr * pr) / (cap * cap);

    // Reward tight fits strongly (small post_residual relative to item)
    let tightness = 1.0 - pr / (it + 1.0).max(1.0);
    score -= 12.0 * tightness.max(0.0) * tightness.max(0.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let nxt = next_item_size as f64;
        let ratio = nxt / pr.max(1.0);
        score -= 8.0 * ratio * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many open bins exist
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins that reduce dispersion
    score += 0.3 * (pr - mean_residual).abs();

    // Late-stream: encourage compacting into existing bins
    score -= 5.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting dead space: coarse quantization of post_residual
    // into capacity-fraction bands. Small classes (tight fits) are strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class index: 0 = [0,10), 1 = [10,25), 2 = [25,50), 3 = [50,100)
    let class = if post_residual < 10 { 0 }
        else if post_residual < 25 { 1 }
        else if post_residual < 50 { 2 }
        else { 3 };

    match class {
        0 => score -= 60.0,                 // near-perfect fit
        1 => score -= 25.0,                 // good fit
        2 => score -= 5.0,                  // mediocre
        _ => score += 20.0,                 // half-empty bin: bad
    }

    // Modulo arithmetic on post_residual: residuals divisible by small harmonics
    // (e.g. 10, 20, 25) are more likely to be exactly filled by future items.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 8.0;
    }
    if post_residual > 0 && post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 7 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits EXACTLY into the post residual,
    // this placement is a two-item chain -> huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a new residual; reward proportional to
            // the tightness of that second-level fit.
            let second_residual = post_residual - next_item_size;
            score -= 20.0 * (1.0 - second_residual / cap);
        } else {
            // next item cannot use the residual: penalize large residuals slightly
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; encourage it only when the stream is
    // early (future flexibility matters) and current bins are quite full on average.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream and
        // when mean residual across open bins is small (all bins tight).
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - 15.0 * (1.0 - progress) - 35.0 * tightness;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage waste (dead space)
    // to keep the active set compact.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * pr * 0.05;

    // Slight preference for filling fuller bins overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
