    // plausible future item are heavily penalized.
    let dead_threshold = 9.0; // smallest useful residual
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave a residual still usable by the
    // lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // lookahead can't fit anywhere in this bin anyway; gap value lower
        score += 0.0;
    }

    // Penalize large leftover gaps that are unlikely to be exactly filled:
    // fragmented residual value decays non-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr * 0.09).exp() * (pr / 10.0).sqrt();

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, easier future packing).
    score += (mean_residual - pr).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly in all open bins. Base cost for a fresh bin:
    if bin_residual == bin_capacity {
        // fresh bin: post_residual = capacity - item_size, large gap penalty
        // applies naturally; add fixed opening cost.
        score += 12.0;
        // If many bins are open, prefer packing into existing ones.
        score += open_bins_count as f64 * 0.8;
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild bonus for filling bins that are already quite full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 40.0 * (post_residual as f64 / next_item_size as f64).ln().abs().min(1.0);
        } else {
            // dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Small post_residual generally good (tight packing)
    score -= 25.0 * (-post_residual as f64 / 25.0).exp();

    // Relative to mean residual: prefer bins with residual near/below mean (fill fuller bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 30.0; // fresh bin is fine if item nearly fills it
        }
    }

    // Late in stream: consolidate, prefer existing bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placement.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 80.0 * tightness * tightness;
    }

    // Penalize dead space: residual too small for any plausible item (min size 1).
    // Dead space relative to typical item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers
    }

    // Lookahead coupling: does the residual after placement still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize blocking the next item proportionally to how much it fails.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
        // If this bin could host BOTH current and next item, strongly favor.
        if bin_residual >= item_size + next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin has large post_residual; make it
    // attractive only when open bins would be badly fragmented or none fit well.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight penalty so tight fits in open bins win.
        score += 25.0;
        // Late in the stream or many open bins: prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 20.0;
        }
        // If next item is large and this item is small, opening fresh bin is fine.
        if next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Global state: many open bins with high mean residual -> discourage
    // spreading; prefer bins below mean residual (filler strategy).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Slight preference for bins with less residual overall (best-fit flavor),
    // scaled by stream progress to shift from exploration to consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial deepening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for mid-range dead space (worst around pr ~ cap/2), stronger late in stream
    let mid = (pr_norm - 0.5) * (pr_norm - 0.5);
    score += 30.0 * mid * (0.5 + progress);

    // Reward tight fits (near-zero residual) with smooth cubic falloff
    let tight = (1.0 - pr_norm).max(0.0);
    score -= 12.0 * tight * tight * tight;

    // Lookahead coupling: reward if next item fits smoothly into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).max(0.0);
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference to fill bins when many bins are open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual context: penalize bins far below mean residual (they hold scarce space)
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35);
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        // discourage new bins when open bins already have small residuals
        if fitting_bins_count > 0 && avg_res < 14.0 {
            score += 5.0;
        }
        if fitting_bins_count > 0 && item_size <= 10 && progress > 0.3 {
            score += 7.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable" residue
    // classes (small, or large enough to hold mid items) are rewarded.
    let pr = post_residual;
    let cls = (pr / 10) % 10; // decade class 0..9
    match cls {
        0 => score -= 12.0,            // near-perfect fit
        1 => score -= 6.0,             // still tight
        2 | 3 => score += 2.0,         // awkward mid gap
        4 | 5 => score -= 3.0,         // can host small items
        _ => {}                        // large residual, neutral
    }

    // Integer-division threshold: leftover divisible into halves/quarters of capacity
    if cap > 0.0 {
        let half = cap / 2.0;
        if (post_residual as f64 - half).abs() < 1.0 { score -= 4.0; }
        if post_residual as f64 == cap / 4.0 { score -= 3.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this leftover: penalize big leftovers proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // harmonic class match: next item size class equals leftover class
        if next_item_size / 10 == pr / 10 && pr > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // current bins would leave very awkward residuals, and early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 - progress * 8.0 - (fitting_bins_count as f64) * 2.0;
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the last fitting bin
        }
    }

    // Mild global pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.15 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps that no typical item can fill.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 4.0 } else if post_residual < 20 { 2.0 } else { 0.0 };
        score += dead * post_residual as f64;
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.4 * gap;
    }
    // If next item cannot use the residual, mild penalty for hoarding space.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Progress pressure: late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate: penalize moderately so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
