                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        // Reward bins whose dead space is exactly the next item (perfect chain).
        if next_item_size > 0 && dead_space == next_item_size as f64 {
            score -= 3.0 * (1.0 - progress);
        }
        // Penalize mid-range dead space that no typical item can use.
        if next_item_size > 0 && post_residual > 0 && dead_space > 5.0 && dead_space < next_item_size as f64 {
            score += (next_item_size as f64 - dead_space) * 0.12 * (1.0 - progress);
        }
        // New: strengthen high dead-fraction penalty late in stream.
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        // New: tiny post-residuals are near-perfect at end of stream.
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        // New: near-divisible remainder reward.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: waste ratio penalty
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Exact fit is gold
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: dead space if next item can't use the leftover
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover is reusable by next item -> reward
            score -= (next_item_size as f64) * 0.5;
            if post_residual == next_item_size {
                score -= 30.0; // perfect chain
            }
        } else {
            // dead space created
            score += (post_residual as f64) * 0.8;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize leaving residuals in the awkward zone (1..10 unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with smaller residual among comparable fits (best-fit core)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream: consolidate aggressively, avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    } else {
        // New-bin candidate: baseline penalty scaled by how many bins already fit
        score += 15.0 + 10.0 * fitting_bins_count as f64;
        // Opening a new bin early is fine; late is costly
        score += progress * 30.0;
        // Large items justify fresh bins
        score -= (item_size as f64 - 50.0).max(0.0) * 0.4;
    }

    // Many open bins: discourage proliferation
    score += open_bins_count as f64 * 0.2 * (if bin_residual == bin_capacity { 1.0 } else { -0.5 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, slightly convex to punish large leftover
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter fits matter more (dead space is costlier)
    let coupling = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += coupling * cap * (0.5 + 2.0 * progress) * 0.5;

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 10.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Prefer bins with lower residual among open bins (fill fuller bins first)
    score += 0.1 * (mean_residual - pr);

    // Mild penalty for too many open bins relative to progress
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // New-bin candidate: smooth penalty that decays with progress
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 / mod 5 define "dead space quality".
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;

    // Penalize post residuals in awkward harmonic classes (small nonzero residues are dead space).
    if pr > 0 && pr < 10 {
        score += 25.0 - mod10 * 2.0; // tiny unusable leftovers are bad
    } else if pr == 0 {
        score -= 30.0; // perfect closure: excellent
    } else {
        // Favor residuals that are multiples of 10 or 5 (likely reusable by future items)
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += mod5; // slight penalty for odd residues
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportional tightness of the follow-up fit
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize if we also leave dead space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the current
    // item would leave a poor harmonic class in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of a new bin (capacity worth of unused space, discounted).
        score = bin_capacity as f64 * 0.85;
        // If the item is large, a fresh bin is natural (it will dominate it).
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid opening yet another.
        score += (open_bins_count as f64) * 1.5 + mean_residual * 0.1;
    }

    // Mild pressure to consolidate: prefer bins with below-average residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Integer-division threshold on post_residual: classify leftover size tiers.
    let tier = pr / 25; // 0..4 tiers
    match tier {
        0 => score += 3.0,   // very small leftover: near-dead space unless 0
        1 => score -= 2.0,   // 25..49: decent
        2 => score -= 3.0,   // 50..74: good
        _ => score -= 1.0,   // 75+: mostly empty bin, fine
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
