            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 0.5 * pressure * (1.0 - progress);
            }
            if post_residual == 0 {
                score -= 2.0 * pressure * (1.0 - progress);
            }
        }
        // Mutation: reward bins whose residual after placement remains a
        // multiple of the next item (perfect tiling lookahead).
        if next_item_size > 1 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail % next_item_size == 0 && tail / next_item_size <= 3 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        // Mutation: combine fine-grained residual fitting with lookahead —
        // favor bins whose post-residual exactly equals a likely future
        // residual bucket (near mean residual), reducing dead-space variance.
        if post_residual > 0 {
            let bucket = (post_residual as f64 - mean_residual).abs();
            if bucket < 6.0 {
                score -= 1.5 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into clean
    // capacity fractions are "dead space resistant".
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class 0: post_residual divisible by 10 -> likely to accept future items
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Class 1: post_residual divisible by 5 but not 10
    if pr % 5 == 0 && pr % 10 != 0 && pr > 0 {
        score -= 5.0;
    }
    // Perfect fit: zero waste is ideal
    if pr == 0 {
        score -= 40.0;
    }
    // Tiny unusable sliver (dead space trap): penalize heavily
    if pr > 0 && pr < 5 {
        score += 25.0;
    }
    // Integer-division threshold: post_residual in (0,20) is a "low band"
    // likely to become dead space unless the next item fits it.
    if pr > 0 && pr < 20 {
        if next_item_size > 0 && next_item_size <= pr {
            score -= 15.0; // lookahead confirms usability
        } else {
            score += 18.0; // lookahead can't use it -> dead space
        }
    }

    // Harmonic fraction classes on post_residual vs capacity
    let frac = prf / cap;
    if (frac - 0.5).abs() < 0.01 {
        score -= 8.0; // half-full residual is versatile
    }
    if (frac - 0.25).abs() < 0.01 || (frac - 0.75).abs() < 0.01 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead pairing: reward if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == pr {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= pr && pr - next_item_size <= 10 {
        score -= 10.0; // near-exact pair
    }

    // Prefer tighter existing bins: penalize bins with large residuals
    // relative to the mean (they waste capacity elsewhere).
    score += 0.3 * (prf - mean_residual).max(0.0);

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Base penalty to prefer reusing open bins...
        score += 55.0;
        // ...unless the item is large and no good fit exists.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 60.0;
        }
        if progress < 0.1 && open_bins_count == 0 {
            score -= 40.0;
        }
        // If mean residual across open bins is too small to matter, new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Mild penalty for hoarding many open bins with small residuals
    if open_bins_count > 8 && prf > mean_residual {
        score += 5.0;
    }

    score
}

