        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        if open_bins_count > 5 && next_item_size > 0 && mean_residual > next_item_size as f64 * 1.3 {
            score += 3.0 + 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 2.5 + 3.0 * (1.0 - progress);
        }
        // Mutation: stronger new-bin resistance when an open bin's post-residual
        // could exactly tile the next item (lookahead consolidation).
        if fitting_bins_count > 0 && next_item_size > 1 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail % next_item_size == 0 {
                score += 4.0 + 2.0 * (1.0 - progress);
            }
        }
        // Mutation: penalize fresh bins whose leftover would be a "mean-bucket
        // mismatch" — leftover far from mean residual is likely future dead space.
        if post_residual > 0 && (post_residual as f64 - mean_residual).abs() > 12.0 {
            score += 3.0 * (1.0 - progress);
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
