        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if open_bins_count > 6 {
            let pressure = (open_bins_count as f64 - 6.0).min(8.0);
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 0.5 * pressure * (1.0 - progress);
            }
            if post_residual == 0 {
                score -= 2.0 * pressure * (1.0 - progress);
            }
        }
        if next_item_size > 1 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail % next_item_size == 0 && tail / next_item_size <= 3 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 {
            let bucket = (post_residual as f64 - mean_residual).abs();
            if bucket < 6.0 {
                score -= 1.5 * (1.0 - progress);
            }
        }
        // Mutation: fine-grained residual + lookahead coupling — reward bins
        // whose post-residual lands within a small window of mean residual
        // while still fitting the next item (keeps future fits dense).
        if next_item_size > 0 && post_residual >= next_item_size {
            let near_mean = (post_residual as f64 - mean_residual).abs() < 8.0;
            if near_mean {
                score -= 2.0 * (1.0 - progress);
            }
            // penalize leaving residual just below next item size (worst dead space)
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size / 2 {
            score += 3.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    // Treat gaps below ~10 (or below next item) as fully dead.
    if post_residual > 0 {
        let usable_threshold = if next_item_size > 0 { next_item_size.min(60) } else { 10 };
        if (post_residual as f64) < usable_threshold as f64 {
            // nearly-dead gap: heavy penalty proportional to how much of the bin is locked away
            score += (post_residual as f64) * 3.0 + 25.0;
        } else {
            // mild convex penalty on leftover space (worse the bigger the leftover)
            score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate and lightly penalize bins leaving big residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 8.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when nothing fits well.
        score += 15.0 + pressure;
        // If next item is large and this fresh bin is the only way to sequence well, soften slightly
        if next_item_size > 60 {
            score -= 8.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual deviates favorably from the mean (below mean = tighter bin).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the post-residual exactly accommodates the next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is an ideal pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 200.0 * tight;
        } else {
            // Next item will NOT fit in the leftover: penalize dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(80.0) * 2.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "large" bins; using them for small items wastes their flexibility.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 400.0;
        // Late in the stream, opening new bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 120.0;
        }
    }

    // Mild penalty for very tight bins early on (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 && progress < 0.5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit: post residual smaller than smallest possible item (1..100 unknown, use 10 as soft floor)
    if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if next item would fit better here after this item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Reward if this placement leaves residual unusable by next item (dead space risk)
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins have large residuals
        // (fragmentation) or many bins are open
        score = 40.0 + mean_residual * 0.5 + open_bins_count as f64 * 2.0;
        // But discourage opening new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 25.0;
        // Discourage new bin if current item nearly fills a bin anyway
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score += 30.0;
        }
    }

    // Fragmentation penalty: large residual relative to mean is wasteful
    let frag = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * frag;

    // Prefer bins with smaller residual for better packing (best-fit flavor)
    score += 0.1 * bin_residual as f64;

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
