        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual still accommodates both
        // next item and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // NEW mutation: fine-grained residual/lookahead compaction.
        // Reward bins whose dead space exactly equals a small multiple of the
        // next item (perfect tiling), penalize dead space just below next item.
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size && ds % next_item_size == 0 {
                score -= 1.8 * (1.0 - progress);
            } else if ds > 0 && ds < next_item_size && ds > 20 {
                score += 0.8 * (1.0 - progress);
            }
        }
        // NEW: when many bins are open, extra pressure to pick the bin with
        // minimal post-residual relative to mean, tightening consolidation.
        if open_bins_count > 6 && post_residual > 0 {
            let rel = post_residual as f64 / mean_residual.max(1.0);
            if rel < 0.5 {
                score -= 1.5 * (1.0 - progress);
            } else if rel > 1.5 {
                score += 1.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness reward: smooth polynomial in fill fraction.
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill * (1.0 + 0.5 * progress);

    // Penalize dead space non-linearly (cubic in wasted fraction),
    // but dead space shrinks in value as the stream progresses.
    let waste_frac = post / cap;
    score += 60.0 * waste_frac * waste_frac * waste_frac * (1.0 - 0.4 * progress);

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let ratio = next_item_size as f64 / post.max(1.0);
        score -= 12.0 * ratio * (1.0 - ratio) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize mildly, more early on.
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate handling: prefer it when open bins are crowded,
    // otherwise penalize so existing bins get used.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 20.0 * crowd * mean_tight;
        score += 15.0 * (1.0 - crowd) * (0.5 + 0.5 * (1.0 - progress));
        // Late in the stream, closing out is cheap: mild new-bin discount.
        score -= 5.0 * progress;
    }

    // Smooth coupling with mean residual: bins far below mean waste more.
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Perfect fit reward: post_residual is a "harmonic" multiple class
    if post_residual == 0 {
        score -= 1000.0; // exact fit is ideal
    } else {
        // Classify post_residual by capacity quarters / eighths
        let eighth = post / (cap / 8.0);
        let quarter = post / (cap / 4.0);
        // Dead-space penalty grows superlinearly for residuals below smallest plausible item
        if post < 10.0 {
            score += (10.0 - post) * 8.0; // unusable sliver
        } else if post < 20.0 {
            score += (20.0 - post) * 3.0;
        }
        // Reward residuals that are harmonic multiples of common item classes
        let harmonic_bonus = if post_residual % 10 == 0 {
            15.0
        } else if post_residual % 5 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Nonlinear coupling: small fractional eighth classes are risky
        score += (eighth.fract() * 6.0) * (1.0 + quarter.fract());
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let n = next_item_size as f64;
            // reward proportional closeness of next fit
            score -= 60.0 * (n / post).min(1.0);
            // penalize if next item would leave another tiny sliver
            let next_post = post - n;
            if next_post < 10.0 && next_post > 0.0 {
                score += 30.0;
            }
        } else {
            // next item cannot use this residual; residual may become waste
            score += 25.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is poor
    if bin_residual == bin_capacity {
        score += 40.0;
        // but late in the stream, opening fresh bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones
    score += 2.0 * open_bins_count as f64 * 0.1;
    // Mean residual coupling: penalize bins far from mean residual (fragmentation)
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    score
}

