            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // New mutation: fine-grained tightness — extra reward when post_residual is a near-exact
        // small remainder, combining residual fitting with lookahead anticipation.
        if next_item_size > 0 && post_residual > 0 {
            let rem = post_residual % next_item_size.max(1);
            if rem >= 1 && rem <= 3 && post_residual < 2 * next_item_size {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // New: penalize bins whose dead space is just below next item size (worst waste band).
        if next_item_size > 0 && dead_space > 0.0 && (dead_space as u32) < next_item_size && (dead_space as u32) + 6 >= next_item_size {
            score += 2.0 * (1.0 - progress);
        }
        // New: late-stream consolidation toward mean residual alignment.
        if progress > 0.65 && (bin_residual as f64) > mean_residual {
            score -= 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are almost unusable
    // for future items -> heavy penalty. Larger leftovers are more reusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; a very small post residual is dead space.
            score += 8.0;
        }
    }

    // New-bin candidate: empty bin should only win when no open bin offers
    // a decent fit; penalize it mildly by default, scaled by open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to typical residuals, allow fresh bin.
        if item_size as f64 > mean_residual + 30.0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins with residual close to the mean (balanced use).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
