pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end exactly full or nearly full.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into the post residual,
    // this placement sets up a perfect follow-up -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 120.0;
        }
        // Penalize leaving a residual that is just barely too small for the next item
        // (dead space from the lookahead's perspective).
        if post_residual > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Relative-to-mean residual: prefer bins whose post residual is below the
    // current mean residual (tightening loose bins rather than loose ones).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity (large items deserve their own space) or few bins fit.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 30.0 } else { 0.0 };
        score += 120.0 - large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in the stream: be more conservative, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small residuals are wasted unless they match the next item
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 150.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize when post_residual is slightly smaller than next item (near-miss dead space)
    if next_item_size > post_residual && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss < 20.0 {
            score += (20.0 - miss) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer tightest fit among many options: reward low bin_residual relative to mean
    if open_bins_count > 1 {
        score += (mean_residual - bin_residual as f64) * 1.5;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheap late
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 80.0 * (1.0 - 0.5 * progress);
        // Penalize opening new bin when open bins fit well (post_residual small)
        let fit_quality = post_residual as f64;
        score = open_penalty + fit_quality * 0.5;
        // If item is large relative to capacity, opening fresh bin is attractive
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Encourage packing many items into few bins when bin count is low
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small time-horizon modulation: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

