        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // Mutation: combine fine-grained residual fitting with lookahead —
        // reward bins whose post-residual plus item leaves room for item+next
        // exactly, and penalize mid-range unusable residuals harder late.
        if next_item_size > 0 && post_residual >= (item_size + next_item_size) {
            score -= 2.5 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= 20 && post_residual < next_item_size {
            score += 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let coupling = prn * prn * (1.0 - progress) * 30.0
                 - prn * (1.0 - prn) * progress * 20.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = (1.0 - prn) * (1.0 - prn) * (progress * 15.0 + 5.0);

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -25.0 - 10.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize opening a new bin when a good fit exists elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        20.0 + 30.0 * (1.0 - progress)
            + if fitting_bins_count > 0 { 15.0 } else { 0.0 }
    } else {
        0.0
    };

    // Lookahead: reward leaving post_residual that fits the next item
    let lookahead = if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            -8.0 * (1.0 - prn) * (1.0 - ns / cap)
        } else {
            4.0 * (ns - pr) / cap * 10.0
        }
    } else {
        0.0
    };

    // Dead space penalty: unusable residual (smaller than min plausible item)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };

    // Mild congestion effect: prefer spreading when many bins open
    let congestion = (open_bins_count as f64).ln() * prn * 2.0;

    base + coupling - tightness + new_bin_penalty + last_chance + lookahead + dead + congestion
}

