        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        // Borrowed refinements from best lineage.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // New mutation: prefer bins whose post-residual still accommodates both
        // next item and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // Mutation: fine-grained residual fitting — reward bins where the
        // post-residual leaves a remainder that small items (<= 10) can tile.
        if post_residual > 0 && post_residual <= 12 {
            score -= (12 - post_residual) as f64 * 0.4 * (1.0 - progress);
        }
        // Mutation: penalize bins whose post-residual is just above a large
        // next item but below 2x — a stranded sliver of dead space.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && next_item_size > 40 {
            score -= 2.5 * (1.0 - progress);
        }
        // Mutation: consolidation pressure when many bins are open and the
        // post-residual can absorb the next item plus a mid-size tail.
        if open_bins_count > 6 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 10 && tail <= 40 {
                score -= 1.5;
            }
        }
        // Mutation: late-stream preference for near-exact fills.
        if progress > 0.7 && post_residual > 0 && post_residual <= 6 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left

    // Penalize residual classes that are hard to fill (harmonic buckets)
    // Buckets: (0, 10] excellent, (10, 30] good, (30, 50] ok, > 50 poor-ish
    if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly favored
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    } else {
        score += 5.0; // large dead space penalty
    }

    // Integer-division harmonic classes: residual mod 10 bands
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 6.0; // round residuals pair well with 10-multiple items
    } else if harmonic >= 7 {
        score += 2.0; // awkward sliver class
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tightly it packs
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 8.0 + 10.0 * tight;
        } else {
            // Next item won't fit here: penalize more if leftover is small (dead space)
            if post_residual < 10 {
                score += 4.0;
            } else {
                score += (post_residual as f64) * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, adjusted by stream state
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early or when existing bins are messy
        score += 12.0;
        if frac > 0.0 {
            // empty bin has frac = 1; make it less attractive unless item is large
            if item_size >= 60 {
                score -= 10.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0; // room for lookahead pairing
            }
        }
        // Few open bins -> prefer consolidating into existing bins
        if open_bins_count > 3 {
            score -= 4.0;
        }
    }

    // Mean residual coupling: if open bins are generally loose, prefer filling them
    if bin_residual != bin_capacity {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Progress-based tightening: late in stream, waste matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10)
    // can use are pure waste; penalize small unusable gaps heavily.
    if post_residual > 0 {
        let unusable = post_residual < 10;
        if unusable {
            score += 60.0;
        }
        // Medium dead space: hard for typical items (10..80) to fill exactly.
        if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward bins whose residual after placement can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Gap too small for lookahead item: extra penalty scaled to gap.
            score += (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, use it to avoid
    // opening a new bin (reward strongly, scaled by open bin count).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 3.0 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.5 * open_bins_count as f64;
        // Early in stream, a fresh bin is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Prefer bins tighter than the fleet average (better fill quality).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for placing larger items into tighter bins.
    score += 0.1 * (item_size as f64 / 10.0) * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: minimize dead space aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable residuals (dead space) nonlinearly.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        }
        // Squared waste term for larger residuals.
        score += 0.05 * pr * pr / 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 == n {
            score -= 400.0; // perfect chain: next item exactly fills this bin
        } else if (post_residual as u32) >= next_item_size {
            let diff = (post_residual as f64 - n).abs();
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to shortfall
            let shortfall = n - post_residual as f64;
            score += 0.5 * shortfall;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad fits,
    // but relax late in the stream / when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 350.0 - 100.0 * progress - 20.0 * pressure;
        // If the new bin enables an exact next-item fit, soften the penalty.
        if next_item_size > 0 && next_item_size == item_size {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
