pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically, normalized by capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * dead * dead * (bin_capacity as f64);

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: strongly prefer bins where the next item also fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if next item fills the remainder well.
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * next_fill;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating residuals that are too small for the next item.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 3.0 * gap.min(40.0) / 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidation into existing bins.
    score -= (open_bins_count.min(50) as f64) * 0.3;

    // Pull toward the mean residual: avoid extreme residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 1.5 * dev / bin_capacity as f64;

    // Time horizon: late in the stream, favor tight packing; early, allow new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0; // early: mild penalty on all existing bins, favors new-bin option
    score -= progress * 5.0;

    // New-bin candidate handling: an empty bin gets a baseline cost that must be
    // beaten only when existing placements are poor.
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Small bonus for bins that become nearly full.
    if post_residual < 10 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

