        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.10 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Non-linear tightness: how well the item fills the bin (fraction of capacity used)
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = (fill * (1.0 - fill) * 4.0).powi(2); // peaks near fill=0.5, low at extremes

    // Reward tight fits more strongly as the stream progresses (pack harder later on)
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large dead space quadratically, scaled by progress (waste hurts more later)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits in the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let next_fit = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        score -= 8.0 * next_fit * next_ratio * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely the best option
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for bins below the mean residual (balance open bins smoothly)
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 create natural
    // "dead space" classes. Leftovers that are multiples of 10 (or tiny)
    // are far more reusable than awkward residues.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if pr <= 5 {
        score -= 10.0; // small dead space, acceptable
    } else if residue_class == 0.0 {
        score -= 15.0; // multiple of 10: highly reusable
    } else if residue_class <= 3.0 {
        score -= 3.0;
    } else if residue_class >= 7.0 {
        score += 6.0; // awkward large-but-not-round leftover
    }

    // Integer-division thresholds on post_residual: classify leftover size.
    let leftover_bucket = pr / 20; // 0..=4 harmonic buckets
    score += match leftover_bucket {
        0 => 4.0,          // tiny leftover: fine
        1 => 0.0,          // 20-39: neutral
        2 => -2.0,         // 40-59: decent space
        3 => -5.0,         // 60-79: good space
        _ => -8.0,         // 80+: nearly empty bin, keep it for big items
    };

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by tightness.
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / 60.0).clamp(0.0, 1.0);
        } else if pr > 0 && next_item_size % pr == 0 && pr >= 10 {
            // Harmonic divisibility: leftover exactly partitions next item
            score -= 6.0;
        } else {
            // Leftover cannot host the next item: penalize proportional to waste
            score += 5.0 * ((pr as f64) / 50.0).min(1.5);
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate handling: an empty bin is a strategic reserve.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, but reduce penalty when the
        // item is huge and mean residual across open bins is small.
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        score = 55.0 - 20.0 * pressure.clamp(0.0, 1.0);
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score += 5.0; // big item coming, keep reserve attractive
        }
    }

    // Slight preference to consolidate into fewer bins as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (open_bins_count as f64).ln().max(0.0).min(4.0);

    // Reward filling bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    score
}

