        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual still accommodates both
        // next item and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // NEW: dead-space ratio minimization — strongly favor bins where the
        // leftover dead space (item doesn't fill the residual) is minimal,
        // and integrate with open-bin consolidation pressure.
        if post_residual > 0 {
            let dead_ratio = dead_space / bin_residual.max(1) as f64;
            score += dead_ratio * 4.0 * (0.5 + 0.5 * (1.0 - progress));
            if open_bins_count > 3 && dead_ratio > 0.7 {
                score += (dead_ratio - 0.7) * 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: leftover after this placement exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the leftover (good 2-step chain)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space the next item cannot use
        score += 6.0 + 0.3 * post_residual as f64;
    }

    // Reward tight fits relative to current residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize bins whose residual is far from the mean (fragmentation pressure)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it beats tight reuse;
    // discourage when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.2 * open_bins_count as f64;

    score
}

