    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.35 };
        score += 9.0 * dead * (post_residual as f64 / 100.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to wasted chain potential.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones; penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln() * 3.0;
    if bin_residual == bin_capacity {
        // New bin candidate: acceptable early, increasingly costly as stream progresses.
        score += 6.0 + 20.0 * progress + crowding;
    } else {
        score -= 2.0 + crowding * 0.5;
    }

    // Global residual balance: prefer bins whose residual is near the mean (keeps fleet homogeneous),
    // unless a perfect fit exists.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream, be greedy: prioritize minimal post residual even harder.
    score -= 10.0 * progress * tightness;

    score
}

