        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        // NEW: resist opening fresh bins when an existing bin achieves exact or
        // near-exact fill with lookahead; penalize new-bin more in that case.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size
            && (post_residual % next_item_size) <= 2 {
            score += 5.0;
        }
        if open_bins_count > 2 && progress > 0.4 {
            score += 2.0 * progress;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        // Borrowed refinements from best lineage.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual still accommodates both next item
        // and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // NEW: combined fine-grained fit + lookahead — reward when the bin can
        // absorb the next item and the remainder stays highly reusable, scaled
        // by how many bins compete (scarce fits get a stronger pull).
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual % next_item_size;
            if rem2 > 0 && rem2 <= 5 {
                score -= (6 - rem2) as f64 * (0.6 + 0.4 * (1.0 - progress));
            }
            if fitting_bins_count >= 3 && rem2 <= 3 {
                score -= 1.5;
            }
        }
        // NEW: penalize leaving a residual slightly below the next item size
        // when many bins remain open (waste compounds across the stream).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && open_bins_count > 3 {
            score += 0.35 * (next_item_size - post_residual) as f64 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual weight grows smoothly with progress
    let prog2 = progress * progress;
    score += pr * (0.35 * progress + 0.65 * prog2);

    // Penalize large dead space quadratically, scaled by capacity
    let frac = pr / cap;
    score += cap * frac * frac * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - frac) * (1.0 - frac) * 8.0 * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: reward leaving space exactly matching next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * progress;

    // Coupling with mean residual: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs();
    score += 0.25 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
