            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match with lookahead item is excellent.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                let leftover = post_residual - next_item_size;
                if leftover <= 10 {
                    score -= 150.0;
                } else {
                    score -= 40.0;
                }
            }
        } else {
            // Next item won't fit here: penalize wasting residual capacity.
            let waste = post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter bins).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidates mildly so existing bins are preferred unless fit is poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin fits well (large post_residual waste), allow new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    }

    // Late-stream consolidation: fewer open bins relative to progress -> tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).sqrt() * 0.5;

    score
}

