pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item (min size 1) can use is moot;
    // instead penalize residuals that are small but nonzero (hard to fill).
    if post_residual > 0 {
        score += 8.0 / (post_residual as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins with high mean residual: encourage consolidating into
    // bins below mean residual (the emptier ones) to close bins sooner.
    if open_bins_count > 1 && mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0);
        }
    }

    // Time horizon: early in the stream, be more liberal (favor new bins less
    // aggressively); late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when item is large or few bins fit.
        let mut nb = 45.0;
        nb -= 0.25 * item_size as f64;
        if fitting_bins_count == 0 { nb -= 60.0; }
        if next_item_size > 0 && post_residual >= next_item_size { nb -= 10.0; }
        nb += 2.0 * open_bins_count as f64 * (1.0 - progress);
        score = nb + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement, normalized, with smooth non-linear penalty
    // that grows super-linearly for large residuals (dead space).
    let mut score = (pr / cap).powf(2.0 + 1.5 * progress) * cap;

    // Smooth coupling: residual quality relative to mean residual across open bins.
    // If this bin's post-residual is much worse than the mean, penalize.
    let mean_pr = mean_residual - item_size as f64;
    let deviation = pr - mean_pr;
    score += 0.35 * deviation * deviation / cap;

    // Lookahead coupling: reward if next item fits into post-residual (smooth, non-linear).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tightness = (next_item_size as f64 / pr).powi(2);
        score -= 12.0 * tightness * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (penalize opening a new bin), scaled smoothly by stream progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Early stream: mildly discourage opening new bins when few bins exist.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (8.0 - 4.0 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Small smooth preference for tighter fits overall.
    score += 0.05 * (item_size as f64 / cap) * (bin_residual as f64 - pr);

    score
}

