    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        // Avoid opening a fresh bin when an existing bin would chain perfectly.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == 0 || tail <= 3 {
                score += 8.0;
            }
        }
        // When mean residual is small, opening a new bin wastes consolidation.
        if fitting_bins_count > 0 && avg_res < 12.0 {
            score += 5.0;
        }
        // NEW: stronger late-stream resistance to opening fresh bins when any
        // existing bin can still chain-fit the next item.
        if fitting_bins_count > 0 && progress > 0.55 && next_item_size > 0 {
            score += 3.0 * progress;
            if post_residual >= next_item_size {
                score += 2.0 * progress;
            }
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual tail stays tileable.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // Fine-grained residual/lookahead compaction: reward dead space that
        // tiles exactly by the next item, penalize dead space just below it.
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size && ds % next_item_size == 0 {
                score -= 1.8 * (1.0 - progress);
            } else if ds > 0 && ds < next_item_size && ds > 20 {
                score += 0.8 * (1.0 - progress);
            }
        }
        // Pressure to pick the bin with minimal post-residual relative to mean.
        if open_bins_count > 6 && post_residual > 0 {
            let rel = post_residual as f64 / mean_residual.max(1.0);
            if rel < 0.5 {
                score -= 1.5 * (1.0 - progress);
            } else if rel > 1.5 {
                score += 1.0 * (1.0 - progress);
            }
        }
        // NEW: combine fine residual fitting with lookahead — when the bin can
        // absorb the item AND the next item with a near-zero tail, prefer it
        // strongly; when the tail after the next item is mid-range useless
        // (too big for tiny items, too small for the next), penalize it.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == 0 {
                score -= 4.0 * (1.0 - progress);
            } else if tail >= 12 && tail < next_item_size {
                score += 0.6 * (1.0 - progress) * ((tail as f64) / 12.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate detection
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: small unusable gaps are worse than large residual space.
    // A gap is "dead" if it's smaller than the smallest possible item (1) threshold
    // and smaller than the lookahead item.
    let dead_gap = post_residual > 0 && post_residual < next_item_size.max(1) && post_residual < 10;
    if dead_gap {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size)
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= item_size / 4 {
        score -= 10.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item could use this post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If post_residual is too small for the next item but not dead, mild penalty
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, avoid opening new bins;
    // when few bins are open, opening a new bin is cheaper.
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, new bins are more acceptable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits well (large post_residual elsewhere), new bin is ok
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly
        score -= 2.0;
        // Prefer bins with residuals close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post == nxt {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if nxt < post {
            let gap = post - nxt;
            // reward leaving just enough room for the next item
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // extra reward if after placing next item, residual would be tiny (<10)
            if gap >= 10.0 && post - nxt <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportional to slack
            score += 0.5 * (nxt - post);
        }
    } else {
        // last item: prefer tightest fit (smallest post_residual already base)
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when existing
    // bins would leave large dead space.
    if bin_residual == bin_capacity {
        // base attractiveness for a fresh bin
        score -= 10.0;
        // but if some open bin fits the item well (post_residual small), discourage new bin
        if next_item_size > 0 && (post_residual as f64) <= next_item_size as f64 {
            score += 25.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize creating residuals that are awkwardly small (dead space < 10 is waste,
    // but 0 is perfect). Non-linear dead-space penalty.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5;
    }

    // Slight preference to fill bins that are already more full than average
    // (keeps mean_residual low, consolidating waste).
    let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 8.0 * fullness;

    // Mild pressure to reduce number of open bins when many are open.
    if open_bins_count > 5 {
        score -= 0.5 * (open_bins_count as f64).min(20.0);
    }

    // Tie-break toward bins below mean residual (less-full bins get slightly favored
    // to balance, but only weakly so tight fits dominate).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

