            }
        }
        // NEW: late-stream, discourage new bins unless truly nothing fits.
        if progress > 0.65 && fitting_bins_count > 0 {
            score += 3.0 * progress;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size && ds % next_item_size == 0 {
                score -= 1.8 * (1.0 - progress);
            } else if ds > 0 && ds < next_item_size && ds > 20 {
                score += 0.8 * (1.0 - progress);
            }
        }
        if open_bins_count > 6 && post_residual > 0 {
            let rel = post_residual as f64 / mean_residual.max(1.0);
            if rel < 0.5 {
                score -= 1.5 * (1.0 - progress);
            } else if rel > 1.5 {
                score += 1.0 * (1.0 - progress);
            }
        }
        // NEW mutation: two-step lookahead compaction — reward bins whose
        // residual after next item still fits next item again with zero or
        // tiny remainder (perfect multi-tiling), scaled by stream progress.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= next_item_size {
                let rem2 = tail % next_item_size;
                if rem2 == 0 {
                    score -= 2.2 * (1.0 - progress);
                } else if rem2 <= 3 {
                    score -= 1.2 * (1.0 - progress);
                }
            }
        }
        // NEW: penalize dead space that is just barely below next_item_size
        // (unusable for lookahead), especially early when bins are plentiful.
        if next_item_size > 0 && post_residual > 0 && dead_space > 0.0 && (dead_space as u32) + 4 >= next_item_size && (dead_space as u32) < next_item_size {
            score += 1.6 * (1.0 - progress);
        }
        // NEW: reward bins whose residual is an exact multiple of the current
        // item size too (current+lookahead tiling synergy).
        if item_size > 0 && post_residual > 0 && post_residual % item_size == 0 && post_residual >= item_size {
            score -= 1.4 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    // Very small leftovers are cheap to tile with tiny items.
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Chain tiling: residuals divisible into multiples of next item.
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            // Dead-space-aware lookahead: reward leftover slack that is itself
            // a "useful" small residual, penalize mid-range useless slack.
            if slack_after > 0 {
                if slack_after <= 5 {
                    score -= 2.0 * (1.0 - progress);
                } else if slack_after > 10 && slack_after < next_item_size {
                    score += (slack_after as f64 - 10.0) * 0.25;
                }
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
            if open_bins_count > 4 && wasted < 15.0 {
                score += 1.5 * (1.0 - progress);
            }
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    // New-bin candidate handling.
    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        // Prefer existing bins when their post-residual leaves a near-zero tail.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail == 0 || tail <= 3 {
                score += 8.0;
            }
        }
        // When mean residual is small (bins are tight), lean on existing bins.
        if fitting_bins_count > 0 && avg_res < 12.0 {
            score += 5.0;
        }
        // NEW: penalize new-bin opening late in the stream when any existing bin
        // can still hold both this item and the next (consolidation pressure).
        if fitting_bins_count > 0 && progress > 0.55 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 6.0 * progress;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        if progress > 0.5 && post_residual > 0 && post_residual <= 15 {
            score -= 2.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && (dead_space as u32) < next_item_size {
            score += 1.2 + 2.0 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0;
        }
        // Dead-fraction shaping against lookahead.
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if fitting_bins_count >= 2 && post_residual == 0 {
            score -= 2.0 * (1.0 - progress);
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.5 && post_residual > 0 {
            score += (dead_frac2 - 0.5) * 6.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual still accommodates both next item
        // and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // Fine-grained residual/lookahead compaction: reward dead space that is
        // an exact multiple of the next item, penalize dead space just below it.
        if next_item_size > 0 && post_residual > 0 {
            let ds = dead_space as u32;
            if ds >= next_item_size && ds % next_item_size == 0 {
                score -= 1.8 * (1.0 - progress);
            } else if ds > 0 && ds < next_item_size && ds > 20 {
                score += 0.8 * (1.0 - progress);
            }
        }
        // Many open bins: extra pressure to pick minimal post-residual bins.
        if open_bins_count > 6 && post_residual > 0 {
            let rel = post_residual as f64 / mean_residual.max(1.0);
            if rel < 0.5 {
                score -= 1.5 * (1.0 - progress);
            } else if rel > 1.5 {
                score += 1.0 * (1.0 - progress);
            }
        }
        // NEW mutation: two-item lookahead tiling — reward bins that can host
        // the next item twice with zero or tiny tail (perfect chain), and
        // penalize bins whose post-residual would strand 1..3 units of slack.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let tail2 = post_residual - 2 * next_item_size;
            if tail2 <= 2 {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // NEW: pair-fit anticipation — when the next item is large relative to
        // capacity, reward bins whose post-residual is just below next item
        // (they are nearly reusable) less harshly than far-below bins.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let shortfall = next_item_size - post_residual;
            if shortfall <= 4 {
                score -= 2.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // next item can still fit here
        } else if post_residual > 0 {
            // dead space scaled by how far next item misses it
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
    } else {
        // Last item: any residual is pure waste; prefer fullest bin.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no real alternative, open the bin
        }
        // Early in stream, new bins are cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global residual pressure: if mean residual is high, prefer packing into
    // bins with residual far from the mean to consolidate fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Many open bins: encourage consolidation by rewarding bins below mean residual.
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight preference for bins whose post residual matches common small sizes.
    let pr = post_residual;
    if pr == 0 { score -= 50.0; }               // perfect fill
    else if pr < 10 { score -= 15.0; }          // near-perfect fill
    else if pr >= 10 && pr < 20 { score += 3.0; } // awkward sliver

    // Time-horizon coupling: late in the stream, prioritize exact fills more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr == 0 { score -= 20.0 * progress; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 20.0 * (x * x) * (1.0 + progress);
    score -= 30.0 * x * progress * (1.0 - progress);
    score += 10.0 * x.powi(3);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (10.0 + 25.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 15.0 + 20.0 * progress;
    } else if next_item_size > 0 {
        score -= 8.0 * (1.0 - (pr as f64 - next_item_size as f64) / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * x;

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    // Very small leftovers are cheap to tile with tiny items.
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Chain tiling: residuals divisible into multiples of next item.
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
