            // Dead-space-aware lookahead: reward leftover slack that is itself
            // a useful small residual, penalize mid-range useless slack.
            if slack_after > 0 {
                if slack_after <= 5 {
                    score -= 2.0 * (1.0 - progress);
                } else if slack_after > 10 && slack_after < next_item_size {
                    score += (slack_after as f64 - 10.0) * 0.25;
                }
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
