        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Prefer bins whose post-residual still accommodates both
        // next item and a small tail, reducing dead-space waste late in stream.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // NEW: fine-grained residual fitting combined with lookahead —
        // reward bins whose post-residual can tile the next item with
        // minimal leftover, scaled by how fragmented open bins are.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail < next_item_size {
                let waste_ratio = tail as f64 / next_item_size as f64;
                score -= (1.0 - waste_ratio) * 2.5 * (1.0 - progress);
            }
            if tail == next_item_size {
                score -= 1.8;
            }
        }
        // NEW: penalize post-residuals that are just barely below the next
        // item (guaranteed dead space) more strongly early in the stream.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
            score += (6 - (next_item_size - post_residual)) as f64 * 1.1;
        }
        // NEW: when many bins are open, favor the bin whose post-residual
        // best matches the mean residual (consolidation pressure).
        if open_bins_count > 4 && post_residual > 0 {
            let dr = (post_residual as f64 - mean_residual).abs();
            score -= 0.35 * dr * (1.0 - progress);
        }
        // NEW: late-stream exact-multiple bonus for two-item lookahead chains.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use this residual — penalize dead space
        score += 50.0 + (post_residual as f64) * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Tightness bonus: smaller post_residual relative to capacity is better
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

