    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: post residual too small to ever be useful
    let min_useful = 10.0;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 8.0 * (min_useful - post_residual as f64) / min_useful;
    }

    // Lookahead: reward if next item can fit into the post residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // leaving a gap that next item cannot use
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit_elsewhere = if fitting_bins_count > 0 {
            // worst-case existing fit slack unknown; approximate via mean residual
            (mean_residual - item_size as f64).abs()
        } else {
            100.0
        };
        score += 20.0 - 6.0 * progress;
        if bad_fit_elsewhere > 30.0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            // big item coming; keep fresh bin available
            score -= 5.0;
        }
    }

    // Global state: many open bins -> consolidate, favor filling existing bins
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (minimize waste)
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_gap * 10.0;

    // Mild time-dependent tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= tightness * progress * 5.0;

    score
}

