        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        // New: strongly prefer bins that will be left with near-zero residual after placing the item,
        // scaled by how many alternative bins exist (avoid starving sole candidates).
        if post_residual > 0 && post_residual <= 2 && fitting_bins_count > 1 {
            score -= 4.0 * (1.0 - progress);
        }
        // New: mild reward for leaving residual in the small-item-friendly band [10, 25] early on.
        if post_residual >= 10 && post_residual <= 25 && progress < 0.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Dead space that the lookahead cannot use: penalize proportionally.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64).min(1.0)
        };
        let threshold = 40.0 + 20.0 * (1.0 - progress);
        if item_size as f64 > mean_residual + threshold * 0.5 {
            score -= 30.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            score += 25.0 + 10.0 * open_bins_count as f64 * 0.1;
        }
        let _ = poor_fits;
    } else {
        // Prefer fuller bins among open ones (best-fit flavor with mean coupling).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Penalize leaving large residuals early when many bins are open.
        score += 0.05 * post_residual as f64 * (open_bins_count.min(20) as f64) / 20.0;
    }

    // Mild exploration coupling with stream progression.
    score += 3.0 * ((step_index as f64 / (total_items.max(1) as f64)) - 0.5);

    score
}

