}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic in post-residual, amplified by progress
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more than linearly
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize creating residual that can't fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * gap * gap + 4.0 * gap;
    }
    // Reward residual that exactly accommodates next item
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 * (0.5 + progress);
    }

    // Dampen proliferation of open bins late in the stream
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Attract toward mean residual (balance open bins) with smooth coupling
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * (item_size as f64 / cap);
    }

    score
}

