    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap * 0.25;
    let half = cap * 0.5;
    let three_quarter = cap * 0.75;

    // Penalize residuals in awkward harmonic classes (just above small-item sizes).
    if pr > 0.0 && pr < 10.0 {
        score += 40.0; // tiny sliver, nearly dead space
    } else if pr <= quarter {
        score += 8.0; // small but usable
    } else if pr <= half {
        score -= 4.0; // mid residual, flexible
    } else if pr <= three_quarter {
        score -= 8.0; // large residual, very flexible
    }

    // Integer-division harmonic classes: residuals congruent to common item sizes
    // are more reusable. Modulo coupling with next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 60.0; // perfect next-item fit
        } else if post_residual >= next_item_size {
            score -= 15.0; // can host next item
            // finer harmonic match: post_residual % next_item_size small => tight reuse
            let m = post_residual % next_item_size.max(1);
            score -= (next_item_size - m) as f64 * 0.3;
        } else {
            score += 25.0; // next item cannot fit here; this residual likely wasted
        }
        // penalize leaving exactly a bad class for the lookahead
        if post_residual < next_item_size && pr > 0.0 {
            score += 20.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowdedness = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 120.0 - 90.0 * crowdedness;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 50.0;
        }
    }

    // Progress pressure: late in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mild preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but avoid tiny dead space.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is gold
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // unusable sliver penalty
    } else if post_residual >= next_item_size as u32 && next_item_size > 0 {
        score -= 8.0; // residual still useful for lookahead item
    }

    // Exact match with lookahead item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins that deviate below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64).max(-40.0).min(40.0) * 0.2;

    // Late in stream: be greedier about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), slightly super-linear.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward when next item fits into post_residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize proportionally to overflow gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
        // Perfect 2-chain: post_residual == next_item_size exactly
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // Relative to mean residual: bins with residual below mean are scarcer, prefer filling them.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (unusable slivers) unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    // or no open bin is a good fit. Make empty bin moderately costly by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: perfect fill gets strong bonus
    if post_residual == 0 {
        score -= 100.0;
