        // Penalize large dead space quadratically
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 40.0;
        // If this bin is the only option, drop the penalty
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (more items to come to fill)
        score -= (1.0 - progress) * 25.0;
        // If mean residual is large, prefer reusing existing bins
        score += mean_residual * 0.5;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Perfect pairing: next item exactly fills remainder
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Dead space the next item can't use: mild penalty
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 5.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

