        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 5.0;
        }
        // New: avoid opening a fresh bin when existing bins are already tight.
        if fitting_bins_count > 0 && avg_res < 12.0 {
            score += 3.5;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
        // New mutation: reward bins whose post-residual is a near-exact multiple
        // of the next item, anticipating clean tiling with lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem3 = post_residual % next_item_size;
            if rem3 <= 1 || rem3 + 1 >= next_item_size {
                score -= 2.2 * (1.0 - progress);
            }
        }
        // New mutation: penalize leaving residuals in the awkward 15..25 band
        // that rarely fit medium items.
        if post_residual >= 15 && post_residual <= 25 && next_item_size > post_residual {
            score += 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: waste grows super-linearly with residual,
    // modulated by stream progress (dead space matters more later).
    let coupling = pr_norm * pr_norm * (0.5 + progress) * cap;
    score += 0.35 * coupling;

    // Reward tight fits smoothly via cubic term around small post_residual.
    let tight = 1.0 - pr_norm;
    score -= 12.0 * tight * tight * tight;

    // Last-chance bonus (smooth sigmoid-like weight).
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: penalize if next item can't use this residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.25 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * fit_quality * (1.0 - progress);
    }

    // Mild preference for filling bins with larger mean residual (smooth).
    score -= 0.1 * (mean_residual - pr);

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small leftover" classes are strongly preferred.
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds (0..=10)
    score += match class {
        0 => -25.0,               // near-perfect fill
        1 => -15.0,
        2 => -8.0,
        3 => -3.0,
        4 => 0.0,
        5 => 4.0,
        6 => 8.0,
        7 => 12.0,
        8 => 16.0,
        9 => 20.0,
        _ => 22.0,
    };

    // Modulo coupling: residual congruent to common item sizes (10,20,25,50)
    // means the leftover is reusable by typical future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 25 == 0 { score -= 4.0; }
        else if pr % 20 == 0 { score -= 3.0; }
        else { score += 2.0; } // awkward leftover
    }

    // Lookahead harmony: if next item exactly matches post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item still fits: mildly reward tight couplings
            let gap = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // next item won't fit in leftover: penalize by the wasted potential
            score += ((next_item_size - pr).min(bin_capacity) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen unless it beats bad fits.
        score += 30.0;
        // Late in the stream or many bins open: slightly prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        if open_bins_count > 3 { score += 6.0; }
    }

    // Dead-space penalty: leftover that no plausible item (>=10) can use.
    if pr > 0 && pr < 10 {
        score += 50.0;
    }

    // Mild tie-break toward bins tighter than the mean residual.
    let mean_gap = (post_residual as f64) - mean_residual;
    score += 0.05 * mean_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (<10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Perfect fill is highly rewarded
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead (k=2): dead space that cannot host the next item is penalized
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next < 10 {
                score += 5.0;
            } else {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin when open bins exist (open-bins pressure)
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
        // Allow a new bin only if the current item would leave a large unusable gap elsewhere
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0;
        }
    }

    // Coupling with mean residual: leaving more than the average residual wastes space
    if post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Mild late-stream tightening: near the end, avoid opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the residual left behind by this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement: strong bonus, maximal
            // when it fills the bin completely (two-item perfect chain).
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 40.0 + 60.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful (dead space trap).
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Penalize residuals far from typical useful sizes relative to mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    // Make the empty bin score mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins as the stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0; // next item forced elsewhere
        }
        // Perfect pairing: this item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer fullest packing, any residual is waste.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global state coupling: when many bins are open, discourage fragmentation;
    // when few are open, be more permissive.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (post_residual as f64 - mean_residual).abs();

    // Prefer bins below mean residual (fill the emptiest-but-fitting bins first
    // keeps a spread of usable residuals). Actually prefer bins ABOVE mean fill:
    // reward bins with residual below mean (they are already full-ish).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time horizon: late in the stream, be greedy (minimize residual now);
    // early, allow some slack to keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: a fresh bin has residual == capacity.
    // Make it attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 40.0 + 2.0 * open_f;
        // Cheaper to open a new bin early in the stream.
        new_bin_score -= 15.0 * (1.0 - progress);
        // If many bins are open, opening another fragments capacity: penalize.
        new_bin_score += 0.4 * open_f * open_f * 0.1;
        // If next item is large and this item is small, a fresh bin is useful.
        if next_item_size > 60 && item_size < 40 {
            new_bin_score -= 12.0;
        }
        // If this is the last chance bin, never open a new bin.
        if fitting_bins_count == 1 {
            new_bin_score += 60.0;
        }
        score = score.min(new_bin_score) * 0.0 + score; // placeholder keep
        // Apply: compare against real bins via explicit return path below.
        return score.max(new_bin_score) - 0.5; // new bin slightly disfavored on ties
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Reward tight fits: subtract a smooth non-linear term that grows as post_residual shrinks.
    let tightness = 1.0 - pr_norm;
    let tight_bonus = 18.0 * tightness.powi(3) * (1.0 + 0.5 * progress);
    score -= tight_bonus;

    // Penalize dead space non-linearly: large residuals become increasingly costly as the stream progresses.
    let dead = pr_norm.powi(2);
    let dead_penalty = 22.0 * dead * (0.4 + 1.2 * progress * progress);
    score += dead_penalty;

    // Exact fill reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: reward if the next item exactly fits the post-residual (smooth kernel around match).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let match_kernel = (-diff / 8.0).exp();
        score -= 14.0 * match_kernel * (1.0 + 0.4 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Fragmentation pressure: if this bin's residual is far below the mean residual, it is a straggler;
    // using it consolidates open bins (mild reward scaled by number of open bins).
    let straggler = (mean_residual - pr).max(0.0) / cap;
    score -= 8.0 * straggler * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral-ish base, penalize opening new bins early / when many bins are open,
    // but allow it late if residual would be very small (avoid cramming).
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress) + 3.0 * (open_bins_count as f64);
        if post_residual == 0 { score -= 5.0; }
        // Late stream: opening fresh bins is cheaper than scattering across stragglers.
        score -= 15.0 * progress * progress;
    }

    // Mild global regularization coupling post_residual with progress polynomially.
    score += 4.0 * pr_norm * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            // Combined: chain multiplicity with fine-grained gap anticipation.
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            if post_residual >= 3 * next_item_size {
                score -= 2.0;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if gap == 0 {
                score -= 5.0 * progress;
            } else if gap < 5 {
                score -= 3.0 * progress;
            }
            if gap >= next_item_size {
                score -= 2.0;
            }
            if gap >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
            if (post_residual as f64) < 0.35 * (next_item_size as f64) {
                score += 4.0;
            }
            if (post_residual as f64) < (next_item_size as f64) * 0.6 {
                score += 1.5 * progress;
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
        if fitting_bins_count >= 2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

