pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // classes (multiples of common small item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 or 25 -> highly reusable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 5 (mildly reusable).
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 4.0;
    }
    // Dead-space penalty: tiny odd residuals that can rarely be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 * (1.0 - pr / 10.0);
    }

    // Integer-division threshold: residual floor(cap/2) is a sweet spot.
    let half = bin_capacity / 2;
    if post_residual >= half && post_residual <= half + 10 {
        score -= 6.0;
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / cap);
            if slack % 5 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this residual: penalize leftover size.
            score += 4.0 * (next_item_size as f64 - pr).min(30.0) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - pr / cap;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Mean-residual coupling: prefer bins deviating below the mean (tighter packs).
    score += (pr - mean_residual) * 0.15;

    // Late-stream: tighten packing as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10 && next_item_size > post_residual);
        if desperate {
            score -= 20.0;
        } else {
            score += 15.0 + 3.0 * (open_bins_count as f64);
        }
    }

    score
}

