    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: a nonzero post_residual that is too small
    // for the lookahead item is unusable dead space -> strong penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.5;
        // Extra penalty if the gap is tiny (truly dead space)
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Open-bins pressure: opening a new bin is penalized by the number of
    // already open bins, so we reuse bins unless the fit is poor.
    if is_new_bin {
        score += 20.0 + open_bins_count as f64 * 4.0;
    } else {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Reward tight fits (large item relative to capacity) mildly.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Slight preference for bins whose residual is already below average
    // (keeps large residuals available for large future items).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    score
}

