pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits into post residual (2-step chain possible).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving dead space that nothing can use (post_residual < min plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Compare against mean residual: bins already tight are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer filling bins when many are open (reduce bin count pressure).
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current fit is very poor (large post residual).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score += 50.0; // keep existing last-chance bins attractive instead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible future item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += 2.0 * ((next_item_size - post_residual) as f64) / (bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling existing bins as fully as possible.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, consolidate into fewer bins (prefer fuller bins).
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score += open_pressure * (bin_residual as f64) * 0.05;

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling bins below mean residual (fuller bins) reduces fragmentation.
    score += 0.08 * ((bin_residual as f64) - mean_residual);

    // Progress horizon: late in the stream, be greedy about filling bins;
    // early on, keep flexibility by mildly penalizing very low post_residual.
    let progress = (step_index as f64) / ((total_items as f64).max(1.0));
    let flexibility_penalty = (1.0 - progress) * (post_residual as f64) * 0.10;
    score += flexibility_penalty;

    // New-bin candidate: make it moderately attractive only when it beats
    // badly fitting options, by anchoring it near the middle of the range.
    if bin_residual == bin_capacity {
        score = 35.0 - 10.0 * progress + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0; // next item needs a fresh bin anyway
        }
    }

    score
}

