pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Polynomial coupling: reward small post_residual more strongly as stream progresses
    let pr_norm = pr / cap;
    score -= (1.0 - pr_norm).powi(3) * (8.0 + 12.0 * progress);

    // Penalize mid-range dead space (awkward residuals) quadratically
    score += 6.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: favor bins whose post_residual can still take the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are all tight
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score += 6.0 + 14.0 * (1.0 - tight) * (1.0 - progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * pr_norm;

    score
}

