        // NEW: reward bins where the residual after next item still fits current-size items.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        // NEW: fine-grained small-residual shaping.
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        // NEW: lookahead for leaving a residual too small for the item after next.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: residues that are "dead space"
    // (too small for any item, sizes 1..=100) are heavily penalized.
    let dead_threshold = 1u32;
    if post_residual < dead_threshold + 9 {
        // post_residual below min item size => unusable dead space
        score += 60.0 * (dead_threshold as f64 - post_residual as f64 + 9.0);
    }

    // Modulo arithmetic on post_residual: classify into capacity fractions.
    // Quarters of capacity are the most reusable residual classes.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let residue_class = post_residual % quarter.max(1);
    if residue_class == 0 && post_residual > 0 {
        score -= 25.0; // post_residual aligns with quarter boundaries: reusable
    } else {
        score += 8.0 * (residue_class as f64 / quarter.max(1) as f64);
    }

    // Integer-division threshold: post_residual >= half capacity is valuable.
    if post_residual >= half {
        score -= 15.0;
    } else if post_residual >= quarter {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // guaranteed perfect follow-up fit
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: penalize large leftovers.
            score += 0.15 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are fragmented (high mean residual spread) or
    // few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 { score -= 200.0; }
        if next_item_size > 0 && next_item_size <= post_residual { score -= 30.0; }
        score += 0.1 * fragmentation;
    }

    // Slight preference for tighter (smaller-residual) bins overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Small-but-usable gaps (10..=20) are mildly risky as well.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins.
    score -= 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item would NOT fit in the leftover, penalize slightly (dead space for the future).
    else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: residual == capacity. Make it less attractive than decent fits,
    // but keep it viable when the item barely fits an existing bin (large post residual).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a fresh bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Deviation from mean residual: bins far below mean residual are "waste" bins; prefer filling them.
    score -= 0.5 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: nearly full bin is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize slack after the lookahead item lands
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item won't fit here; dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare residual to mean residual across open bins.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a large awkward residual relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = post_residual as f64 / bin_capacity as f64;
        score += 60.0;
        // late in the stream, be more conservative about opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * 40.0 * (1.0 - progress);
        // if many bins are open with small residuals, opening fresh is fine
        if mean_residual < 30.0 && open_bins_count > 3 {
            score -= 80.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that no plausible item (>=1) can use efficiently:
    // tiny residuals are fine (near-perfect fit), mid residuals are bad.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // residual is "wasted" if it's too small for typical items but nonzero
        if pr < 10.0 {
            score -= 5.0; // near-perfect packing
        } else {
            score += 0.3 * pr;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits: moderate reward scaled by snugness
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * snug;
        } else {
            // next item won't fit here; penalize more if the leftover is large
            score += 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or this item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        // penalty for opening new bins early / when open bins are roomy
        score += 20.0 + 15.0 * (1.0 - progress) + 30.0 * (1.0 - crowded);
        // but if the item is huge and mean residual is small, soften it
        score -= 0.15 * item_size as f64 * crowded;
    } else {
        // mild preference for reusing existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Global balance: prefer bins whose residual is near the mean (even filling),
    // slightly discourage picking outlier bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Many open bins: encourage consolidation into emptier bins
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * post_residual as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer tight fits moderately.
    // Late (progress ~ 1): strongly suppress wasted residual.
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;
    let residual_norm = pr / cap;

    // Smooth waste penalty growing with progress (cubic ramp).
    score += 24.0 * progress_cu * residual_norm * residual_norm;

    // Dead-space cliff: smooth quadratic term when residual becomes unusable
    // relative to the smallest plausible item (1..100 unknown distribution,
    // use next_item_size when available as a soft threshold).
    let min_next = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    let unusable = ((min_next - pr) / cap).max(0.0);
    score += 18.0 * (0.25 + 0.75 * progress) * unusable * unusable;

    // Lookahead coupling: reward bins whose post-residual still fits the next item,
    // with a smooth sigmoid-like weight via progress.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let weight = 10.0 * (1.0 - progress) + 4.0 * progress;
        score -= weight * fits_next * (pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild reward for bins tighter than the mean residual (best-fit flavor),
    // scaled by a smooth quadratic in progress.
    let tightness = ((mean_residual - pr) / cap).max(0.0);
    score -= (6.0 + 10.0 * progress_sq) * tightness;

    // Penalize opening new bins when plenty of open bins exist and the fit is decent,
    // expressed smoothly via residual_norm and open_bins_count.
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 8.0 * crowding * residual_norm * (1.0 - progress);

    // New-bin candidate bias: make empty bin slightly less attractive unless
    // current fit is very poor (smooth interaction).
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * (1.0 - residual_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: dead space analysis via modulo on capacity fractions
    let cap_frac = (post_residual * 10) / bin_capacity; // integer division: 0..10 tenths
    let class_penalty: f64 = match cap_frac {
        0 => 0.0,          // tiny residual, effectively closed
        1 => 40.0,         // 10% dead space - very hard to refill
        2 => 25.0,
        3 => 15.0,
        4 => 8.0,
        5 => 0.0,          // half-full residual is reusable
        6 => 5.0,
        7 => 10.0,
        8 => 20.0,
        _ => 30.0,
    };
    score += class_penalty;

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the next item, scaled by how snug
            let snug = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 * snug;
        } else {
            // post_residual cannot host next item: penalize proportional to wasted potential
            score += 12.0 * ((next_item_size as f64) - (post_residual as f64)).min(40.0) / 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity as f64) * 0.9;
        // cheaper to open new bin when few open bins relative to stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // discourage new bin if this item fits snugly somewhere (handled by other scores)
        if post_residual == 0 || post_residual <= 5 {
            score += 500.0; // never open new bin when a near-perfect fit exists elsewhere
        }
    }

    // Prefer bins whose residual is far below mean residual (tighter bins get used)
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.5;

    // Modulo harmonic tiebreak on post_residual: residuals that are multiples of common
    // small item sizes (10, 20, 25) are more refillable
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 5.0; }

    // Slight preference to keep many small residual bins consolidated as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        // penalize gaps too small to hold even the smallest item hardest
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // penalize gaps smaller than the lookahead item (unusable for next item)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.2 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // reward gaps that exactly accommodate the next item
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 40.0).max(0.0);
        }
    } else {
        // perfect fill: strongly rewarded
        score -= 40.0;
    }

    // reward tight fits relative to the residual before placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // open-bin pressure: prefer using existing bins over proliferating bins
    score += 0.35 * open_bins_count as f64;

    // last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // discourage leaving residual far below mean residual (fragmentation)
    if post_residual > 0 {
        score += 0.15 * (mean_residual - post_residual as f64).max(0.0);
    }

    // mild stream-progress coupling: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it only wins when all else is bad
        score += 45.0 - 10.0 * progress;
        // but allow new bin if item is huge and no open bin fits well
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Dead-space shaping.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            // NEW: combined-fit lookahead with item+next chaining.
            if (post_residual as u64) >= (item_size as u64 + next_item_size as u64) {
                score -= 2.0 * (1.0 - progress);
                let rest = post_residual - item_size - next_item_size;
                if rest < next_item_size && rest < item_size && rest > 0 {
                    score += 1.5;
                }
            }
            // NEW: residual just below 2x next item is awkward.
            let gap2 = post_residual as f64 - 2.0 * next_item_size as f64;
            if gap2 < 0.0 && gap2 > -6.0 {
                score += 2.0 * (1.0 - progress);
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            if post_residual >= 3 * next_item_size {
                score -= 2.0;
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
            if (post_residual as f64) < 0.35 * (next_item_size as f64) {
                score += 4.0;
            }
            if (post_residual as f64) < (next_item_size as f64) * 0.6 {
                score += 1.5 * progress;
            }
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
        if fitting_bins_count >= 2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
