        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 8 && tail <= 25 && tail < next_item_size {
                score -= 1.0 * (1.0 - progress);
            }
        }
        // NEW: combined dead-fraction shaping from best lineage.
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size as u32 {
                score -= 1.8 * (1.0 - progress);
            }
            if (post_residual - next_item_size) < item_size {
                score -= 1.4 * progress;
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits into post residual: good 2-step chain.
    if next_item_size > 0 && next_item_size < post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit: penalize proportionally to wasted potential.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Tight fits (small post residual) are good in general.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Compare against mean residual: bins with residual below mean are more precious.
    if mean_residual > 0.0 {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (large next item relative to typical residuals) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if next_item_size > 0 {
            ((next_item_size as f64) / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        score += 25.0 + 20.0 * progress - 50.0 * desperation;
        // Opening new bins when many are already open is wasteful.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins whose residual is nearly consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Exact / near-exact fills are gold.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining),
    // penalize if post-residual is a dead space that no plausible item (>=1) uses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Waste created relative to next item's needs.
            score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Dead-space penalty: small awkward leftovers are hard to fill later.
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 50.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If open bins have plenty of slack, discourage new bins.
        score += 0.2 * mean_residual;
        // Early stream with few bins: new bins are cheap and give flexibility.
        if open_bins_count < 3 && progress < 0.2 {
            score -= 45.0;
        }
    } else {
        // Slight preference for reusing bins with larger residuals (spread load evenly)
        // but only when the fit is loose; tight fits already rewarded above.
        if fit_ratio < 0.5 {
            score += 0.05 * (bin_residual as f64 - mean_residual);
        }
    }

    // Global balance: mildly prefer bins below mean residual to keep options open.
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

