        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        let new_dead_frac = dead_space / bin_capacity.max(1) as f64;
        if open_bins_count > 3 && new_dead_frac > 0.35 {
            score += (new_dead_frac - 0.35) * 14.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 3.0 * progress;
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 5.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= 2 * next_item_size {
            score += 4.0;
        }
        if post_residual > 0 && post_residual <= 10 {
            score += (11 - post_residual) as f64 * 0.9;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 5.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // New: strong dead-space penalty scaled by open-bin pressure.
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        // New: chainability into multiples of next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        // New: residual after next item can still hold current item class.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 2.5 * (1.0 - progress);
        }
        let tight_frac = dead_space / bin_capacity.max(1) as f64;
        if tight_frac > 0.55 && post_residual > 0 {
            score += (tight_frac - 0.55) * 10.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual > bin_capacity / 2 {
            score -= 2.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 && open_bins_count <= 3 {
            score += 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual modulo capacity fractions (C/4 = 25)
    let q = post_residual % (bin_capacity / 4);
    score -= q as f64 * 0.6; // small non-zero remainders are useful dead space? penalize large even classes

    // Integer-division threshold classes: post_residual / 25 harmonic band
    let band = post_residual / (bin_capacity / 4);
    score += band as f64 * 4.0;

    // Perfect-fit harmonic classes: post_residual in {0, 10, 20, 25, 50}
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual == 25 || post_residual == 50 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // Lookahead: next item fits harmonically into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 150.0; // chained perfect fit
        } else if slack % (bin_capacity / 4) == 0 {
            score -= 40.0;
        } else {
            score -= slack as f64 * 0.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space: next item can't use residual
        score += post_residual as f64 * 0.8;
    }

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Avoid spreading too many open bins when residuals are large
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late-stream conservatism: fewer new bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless residual classes are hopeless
        score += 45.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Small gaps (< ~half the minimum item) are almost unusable dead space.
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // huge penalty for tiny gaps
        } else if pr < 25.0 {
            score += 25.0 * (25.0 - pr) / 15.0; // moderate penalty
        } else {
            // Larger leftovers are reusable; mild reward scaled by usefulness.
            score -= 8.0 * (pr / bin_capacity as f64);
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score = 70.0 + 4.0 * open_bins_count as f64;
        // If no open bin can fit the item, a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the next item would fit into the fresh bin's eventual residual, slight bonus.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // mean residual is already low (bins are nearly full).
    if bin_residual != bin_capacity {
        let mean_gap = (mean_residual - pr).abs();
        score += 0.5 * mean_gap;              // prefer bins near the mean residual
        score += 0.3 * open_bins_count as f64; // slight pressure to close bins out
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
