        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 2.5 * (1.0 - progress);
        }
        let tight_frac = dead_space / bin_capacity.max(1) as f64;
        if tight_frac > 0.55 && post_residual > 0 {
            score += (tight_frac - 0.55) * 10.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual > bin_capacity / 2 {
            score -= 2.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 && open_bins_count <= 3 {
            score += 2.0 * (1.0 - progress);
        }
        // New: prefer bins whose post-residual tiles exactly into multiples of the current item.
        if post_residual > 0 && post_residual % item_size.max(1) == 0 {
            score -= 1.6 * (1.0 - progress);
        }
        // New: penalize near-mean residuals slightly to spread dead space evenly.
        if post_residual > 0 {
            let dev_p = (mean_residual - post_residual as f64).abs();
            score += 0.05 * dev_p * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills bin exactly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover after chaining next item
            score += gap * 0.6;
            if gap == 0.0 { score -= 0.0; }
            // reward small gaps (good chain quality)
            if gap <= 10.0 { score -= 25.0 * (1.0 - gap / 10.0); }
        } else {
            // next item cannot follow into this bin; penalize by shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 8.0 + shortfall * 0.35;
        }
    }

    // Dead-space penalty: post_residual too small to ever be useful (< 10 assumed min item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize slightly so tight fits win,
        // but keep it competitive when open bins have large residuals.
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (use bins with less residual first to consolidate small ones).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Late in the stream: be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: penalize residual quadratically to prefer near-exact fills.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for a chained fit (post_residual - next small too).
            let chain = post_residual - next_item_size;
            score -= (chain as f64 / bin_capacity as f64) * 6.0;
        } else {
            // Dead space if next item cannot use the leftover.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when many open bins fit the item,
    // but allow it when existing residuals are large/wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (mean_residual - item_size as f64).max(0.0);
        score += 25.0 + waste * 0.3 - progress * 10.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer filling larger-residual bins early in the stream, tighter bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
