pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate large residuals less (keep space flexible);
    // later, compact fills (small post_residual) are rewarded more.
    let coupling = x * (1.0 - x) * (0.5 + progress);
    score += 24.0 * coupling;

    // Quartic penalty on very small residuals (dead space) scaled by progress
    score += 18.0 * x.powi(4) * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (1.0 - pr / cap);
        } else {
            score += 4.0 * (pr / cap);
        }
    }

    // Prefer bins below mean residual slightly (balance load smoothly)
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for opening a brand-new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (mod-10 classes) ---
    // Leftovers that are "harmonic" (multiples of common item classes) are reusable.
    let post_i = post_residual as i64;
    let harmonic_bonus = if post_i == 0 {
        -60.0 // perfect closure: best possible outcome
    } else if post_i % 10 == 0 && post_i >= 10 {
        -25.0 // leftover matches the 10-class ladder
    } else if post_i % 20 == 0 {
        -30.0
    } else if post_i % 25 == 0 {
        -22.0
    } else if post_i % 50 == 0 {
        -35.0
    } else {
        // awkward leftover: penalize small dead space (< 10 unusable)
        if post_i < 10 { 18.0 } else { 0.0 }
    };
    score += harmonic_bonus;

    // --- Integer-division thresholds on post_residual ---
    let q = post_residual / 10; // which 10-bucket the leftover falls into
    score -= q as f64 * 2.0;    // bigger reusable leftover is generally better
    if q == 0 && post_residual > 0 {
        score += 12.0; // tiny sliver, dead space
    }

    // --- Lookahead coupling: leftover should harmonize with next item ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits exactly or near-exactly: strong reward
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 45.0;
            } else if gap < 10.0 {
                score -= 28.0;
            } else {
                score -= 10.0 * (1.0 - gap / cap);
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += 6.0 * (1.0 - (post_residual as f64) / n);
        }
        // harmonic match on mod classes between leftover and next item
        if post_i > 0 && next_item_size as i64 % 10 == post_i % 10 {
            score -= 8.0;
        }
    }

    // --- Fit scarcity: last chance bin should be strongly favored ---
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes (cap - item) immediately; only attractive
        // if item is huge (poor fit anywhere) or many bins already open.
        let frac = item_size as f64 / cap;
        if frac >= 0.5 {
            score -= 30.0 * (frac - 0.5) * 2.0; // big items: fresh bin OK
        } else {
            score += 55.0 * (1.0 - frac);       // small items: keep packing open bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        score += 3.0 * (open_bins_count as f64).min(20.0); // mild consolidation pressure
    }

    // --- Waste-avoidance: penalize leaving more than half-capacity used poorly ---
    let usage = 1.0 - (post_residual as f64) / cap;
    score -= 15.0 * usage * usage; // reward tight fills quadratically

    // --- Mild stream-phase adaptation ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * usage; // later in stream: favor tighter bins more

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
