            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            if post_residual >= 3 * next_item_size {
                score -= 2.0;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            // Two-step lookahead: can the item after next also tile?
            if slack_after >= next_item_size && slack_after % next_item_size == 0 {
                score -= 1.5 * progress;
            }
            if slack_after >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
            if (post_residual as f64) < 0.35 * (next_item_size as f64) {
                score += 4.0;
            }
            if (post_residual as f64) < (next_item_size as f64) * 0.6 {
                score += 1.5 * progress;
            }
            if (next_item_size - post_residual) <= 4 {
                score += 2.5 * (1.0 - progress);
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    if post_residual == 0 {
        score -= 15.0;
        if fitting_bins_count >= 2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        let new_dead_frac = dead_space / bin_capacity.max(1) as f64;
        if open_bins_count > 3 && new_dead_frac > 0.35 {
            score += (new_dead_frac - 0.35) * 14.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 3.0 * progress;
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 5.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= 2 * next_item_size {
            score += 4.0;
        }
        if post_residual > 0 && post_residual <= 10 {
            score += (11 - post_residual) as f64 * 0.9;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 5.0;
        }
    } else {
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Dead-space ratio shaping (combined feature).
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 2.5 * (1.0 - progress);
        }
        let tight_frac = dead_space / bin_capacity.max(1) as f64;
        if tight_frac > 0.55 && post_residual > 0 {
            score += (tight_frac - 0.55) * 10.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual > bin_capacity / 2 {
            score -= 2.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 && open_bins_count <= 3 {
            score += 2.0 * (1.0 - progress);
        }
        // New: pair-fit lookahead — reward residuals that exactly absorb next item plus current item's successor chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 {
                score -= 2.2;
            }
            if after == item_size {
                score -= 2.5 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item leaves a tiny dead gap, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins are very full or few options
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fits the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item can't use the leftover; penalize dead space that is
            // too small for typical items (unusable fragment).
            if post_residual < 10 {
                score += 25.0;
            }
            score += 5.0;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
        // But if item is huge relative to capacity, opening fresh is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    } else if progress > 0.7 {
        score -= 8.0;
    }

    // Mild penalty per open bin to encourage closing out bins.
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual too small for typical future items.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: mild penalty proportional to wasted potential.
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    if open_bins_count > 2 {
        let pressure = mean_residual / cap;
        score += 3.0 * pressure * (open_bins_count as f64).ln();
    }

    // Time horizon: early in stream, tolerate opening new bins (penalize new bin less);
    // late in stream, strongly prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 4.0 + 8.0 * progress;
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    // Prefer bins whose residual is closest to the item (perfect packing granularity).
    let granularity = ((bin_residual - item_size) as f64 / cap).abs();
    score += 1.5 * granularity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: polynomial in normalized post-residual
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 40.0 + norm_pr * 60.0;

    // Stream-progress modulation: later in stream, prefer tighter fills
    let progress_term = progress * norm_pr * 30.0;

    // Dead-space penalty: very small post-residual is good (tight fit)
    let tight_fit_bonus = -25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize if next item cannot use post residual
    let lookahead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        -12.0 * (1.0 - gap / cap).exp() * (next_item_size as f64 / cap)
    } else {
        0.0
    };

    // Mean residual divergence: prefer bins far from the mean (diversity of gaps)
    let diversity = 8.0 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strongly reward using it to avoid opening new bins
    let last_chance = if fitting_bins_count == 1 { -40.0 } else { 0.0 };

    // New empty bin candidate: penalize mildly, more so early in stream
    let new_bin = if bin_residual == bin_capacity && bin_capacity > 0 {
        55.0 - 35.0 * progress
    } else {
        0.0
    };

    // Open bins count pressure
    let open_pressure = open_bins_count as f64 * 0.5 * norm_pr;

    pr + poly + progress_term + tight_fit_bonus + lookahead + diversity + last_chance + new_bin + open_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: dead space quality.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual in 1..=10 -> small unusable sliver, mild penalty.
    // Class 2: post_residual in 11..=30 -> moderate, still usable for small items.
    // Class 3: post_residual > 30 -> large, flexible.
    let post_u = post_residual;
    let class: f64 = if post_u == 0 {
        -60.0
    } else if post_u <= 10 {
        25.0
    } else if post_u <= 30 {
        5.0
    } else {
        -5.0
    };
    score += class;

    // Modulo arithmetic on post_residual: residuals near multiples of common
    // small item sizes (10, 20, 25, 50) are "reusable" slots.
    let reusable = (post_u % 10 == 0) || (post_u % 25 == 0) || (post_u % 50 == 0);
    if reusable {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this is a chained perfect fit -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 45.0;
        } else if next_item_size <= post_u {
            // next item fits: residual quality matters less
            score -= 8.0;
            // harmonic check: post_residual - next_item_size lands in a good class
            let post2 = post_u - next_item_size;
            if post2 == 0 || post2 % 10 == 0 || post2 % 25 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: penalize tight residuals more
            if post_u <= 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: only perfect fills matter.
        if post_u == 0 {
            score -= 80.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_u <= 10 && post_u > 0 {
            score += 20.0; // don't waste last fitting bin on a sliver
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the current item leaves a
    // clean harmonic residual (e.g. exactly half or a modulo-friendly chunk)
    // and there are alternatives available.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to stream progress
        // (early on, consolidation matters more; later, fresh bins are cheap).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 25.0 * progress;

        // Reward opening a new bin when the item creates a harmonic residual.
        if post_u == 0 || post_u % 10 == 0 || post_u % 25 == 0 || post_u % 50 == 0 {
            score -= 20.0;
        }
        // If next item is large and would fit in a fresh bin alongside nothing,
        // a fresh bin gives flexibility when open bins are congested.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count >= 3 {
            score += 25.0;
        }
    }

    // Slight preference for filling bins tighter than the mean residual.
    if post < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Small gaps (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space penalty
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Non-linear tightness reward: quadratic in post_residual so tight fits dominate.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // ---- Last-chance pressure ----
    // If this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- Open-bins pressure: discourage proliferation of many open bins ----
    let open_pressure = 0.8 * (open_bins_count as f64).powf(1.3);
    score += open_pressure * (post_residual as f64) / (bin_capacity as f64);

    // ---- Lookahead: favor bins whose leftover can host the next item ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0; // leftover too small for lookahead item
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins are badly fragmented
        // or none fit well. Penalize opening mildly; the last-chance reward above
        // makes existing usable bins win.
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual - post_residual as f64).abs() / mean_residual.max(1.0)
        } else {
            0.0
        };
        score += 20.0 - 10.0 * fragmentation;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: item + next item exactly fill the bin
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement; reward proportional closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will not fit in the leftover; penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 15.0 + waste * 0.3;
        }
    } else {
        // Last item: any leftover is pure waste
        score += 20.0;
    }

    // Relative to mean residual: bins with residual far below mean are "tight" candidates
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    } else {
        score += (resid - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good alternatives exist
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64 * 0.5);
        // But if no open bin fits well (large post_residual elsewhere), new bin is fine
        if post_residual == bin_capacity {
            score += 5.0;
        }
    }

    // Mild stream-progression adaptation: be more conservative early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

