pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover; mild penalty for wasting space.
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64).min(1.0).max(0.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state: when many bins are open, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as more bins are open and stream progresses.
        score += 8.0 + 3.0 * (open_bins_count as f64) + 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., we are filling the emptier-relative bins well).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for filling bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

