            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
            if (next_item_size - post_residual) <= 4 {
                score += 2.5 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        let tight_frac = dead_space / bin_capacity.max(1) as f64;
        if tight_frac > 0.55 && post_residual > 0 {
            score += (tight_frac - 0.55) * 10.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual > bin_capacity / 2 {
            score -= 2.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 && open_bins_count <= 3 {
            score += 2.0 * (1.0 - progress);
        }
        // Mutation: fine-grained residual + lookahead coupling — reward bins whose
        // post-residual after the next item is a tight but usable remainder.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail < 8 {
                score -= 2.2 * (1.0 - progress);
            }
            if tail >= item_size && tail < item_size + 6 {
                score -= 1.6 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer tight fits (small post_residual), smoothly scaled.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // dead space matters more as the stream progresses.
    let prn = pr / cap; // normalized post residual in [0,1]
    let dead_penalty = prn * prn * (0.5 + 2.5 * progress) * cap;
    score += dead_penalty;

    // Perfect/near-perfect fit reward, stronger late in the stream.
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness.powi(3) * (1.0 + progress);

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize opening new bins mildly, more when many open
    // bins already have usable residual space and early in the stream.
    if is_new_bin {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 3.0 + 4.0 * (1.0 - progress) + 1.5 * crowding;
        // But if residuals across bins are fragmented, a new bin is fine.
        score -= (mean_residual / cap).max(0.0) * 2.0;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((pr - nx).abs() / cap);
        score -= 4.0 * match_term.max(0.0).powi(2);
    }

    // Slight preference for fuller (more utilized) bins among open ones.
    score -= (bin_residual as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
