pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus: f64 = if pr % 50 == 0 {
            40.0
        } else if pr % 25 == 0 {
            30.0
        } else if pr % 20 == 0 {
            25.0
        } else if pr % 10 == 0 {
            20.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead space penalty: small odd residuals are hard to reuse
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 && pr % 10 != 0 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize slightly
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, scaled by
    // how many open bins could fit the item and stream progress.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // new bin leaves room for lookahead
        }
    }

    // Tie-break by tightness: prefer bins with smaller residual overall
    score += (bin_residual as f64) * 0.05;

    // Mean residual coupling: when open bins are already loose, discourage
    // wasting another bin's space.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Early stream: be slightly more conservative (keep options open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (>= 10, or next_item_size) fits.
    if post_residual > 0 {
        let min_future = if next_item_size > 0 { next_item_size.min(100) } else { 10 };
        if (post_residual as f64) < min_future as f64 {
            score += 60.0 + 0.5 * post_residual as f64; // tiny unusable gap
        } else {
            // Reward leaving a gap that exactly or nearly fits the lookahead item.
            if next_item_size > 0 && post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                score -= 25.0 * (1.0 - slack as f64 / 100.0);
            }
        }
    } else {
        // Perfect fill: strongly rewarded.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bins pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins whose residual is near/below the mean
    // (i.e., already well-filled bins), penalize draining the fullest bins.
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large and open bins are nearly full.
    if bin_residual == bin_capacity {
        let open_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // There is an alternative; make new bin costly unless item is huge.
            score += 45.0 - 30.0 * fill;
        } else {
            // No open bin fits: new bin is necessary; mild base score.
            score += 10.0;
        }
        // Late in stream, opening new bins is more acceptable (future waste is low).
        score -= 20.0 * progress;
        let _ = open_fullness;
    }

    // Lookahead: if next item is large and this bin would be left with a gap
    // too small for it, penalize.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 0.3 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but don't leave tiny slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty: unusable sliver
    }

    // 2-step lookahead: reward if the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            let new_residual = post_residual - next_item_size;
            if new_residual < 10 {
                score -= 10.0; // chain leaves sliver: mildly good now, bad later
            } else {
                score -= 15.0 * (1.0 - new_residual as f64 / bin_capacity as f64);
            }
        } else {
            // next item can't fit here: this bin becomes cold after this placement
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * gap;
        }
    }

    // Compare against mean residual of open bins: placing into a below-average
    // residual bin (already tight) keeps big residual bins available.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res).min(40.0);
    } else {
        score += 0.3 * (res - mean_residual).min(40.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrink late in stream.
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 70.0 - 30.0 * progress;
        // If many open bins can fit the item, opening new bin is wasteful.
        new_bin_cost += 10.0 * (fitting_bins_count as f64).min(5.0);
        // But if open bins are fragmented (high mean residual spread), a fresh
        // bin is attractive for large items.
        if item_size > 50 && mean_residual < item_size as f64 {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    // Early stream: consolidate aggressively to keep bins dense.
    if open_bins_count > 0 && step_index < total_items / 4 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer reusing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual / bin_capacity as f64).sqrt() * (1.0 + progress);
    }

    // Penalize opening a new bin when open bins fit well, more so late in stream.
    if bin_residual == bin_capacity {
        let best_open = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 15.0 * best_open * (0.5 + progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // reserve fresh bin for huge next item
        }
    }

    // Mild preference for filling fuller bins (smaller residual) early.
    score += 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Waste penalty grows non-linearly as the stream progresses (late waste is costlier).
    score += norm_post * norm_post * (40.0 + 80.0 * p2 + 60.0 * p3);

    // Tight-fit reward: smooth polynomial of (1 - norm_post), stronger early.
    let tight = 1.0 - norm_post;
    score -= 30.0 * tight * tight * (1.0 - progress) + 20.0 * tight * tight * tight;

    // Exact-fill bonus via smooth term.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly reward using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 35.0 * (1.0 - progress);
        // If the next item would fit exactly in the residual left here, favor this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 + next_item_size as f64 * 0.2;
        }
    }

    // Lookahead: reward bins whose post-residual still accommodates the next item,
    // with a smooth quadratic decay of the bonus as residual shrinks toward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size as u32) as f64 / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // Residual becomes dead space relative to next item: penalize smoothly.
            let miss = (nxt - post) / cap;
            score += 18.0 * miss * miss;
        }
    }

    // Coupling with mean residual: prefer bins deviating favorably (smaller residual used first).
    let dev = (mean_residual - post) / cap;
    score -= 8.0 * dev * (1.0 - 2.0 * progress);

    // Mild penalty for spreading across too many open bins early.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes in small-item increments
    let harmonic_class = post_residual % 10;
    let harmonic_quotient = post_residual / 10;

    // Reward residuals that sit in "usable" harmonic classes (multiples of 10)
    if harmonic_class == 0 {
        score -= 6.0;
    } else if harmonic_class <= 3 {
        score += 4.0; // tiny dead space class
    } else if harmonic_class >= 8 {
        score += 2.0;
    }

    // Depth of usable space: integer division thresholds on post_residual
    if post_residual >= 50 {
        score -= 3.0;
    } else if post_residual >= 30 {
        score -= 1.0;
    } else if post_residual >= 10 {
        score += 1.5;
    } else if post_residual > 0 {
        score += 5.0; // nearly dead bin
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: bonus scaled by how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - (snug / 10.0).min(4.0);
            // harmonic match: next_item_size shares class with post_residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize wasting the residual
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // base penalty so a decent existing fit beats opening a new bin
        score += 20.0;
        // but if residuals across bins are fragmented, opening fresh is attractive
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 15.0;
        }
        // early stream: slightly favor consolidating instead of new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer tighter existing bins relative to the mean residual
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.08;

    // Mild pressure against bin sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
