pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are pure waste.
    // Penalize unusable gaps hard; reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // dead space: unusable for typical min item sizes
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits generally (small post_residual relative to item size)
    if item_size > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are open and stream is early/mid
        score += 30.0 + 8.0 * pressure + 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

