        score -= 10.0;
    }

    // Reward exact-fit relative to mean residual (tightness vs. average).
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * (post_residual as f64 - mean_residual).min(40.0) / 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (would leave a small residual in any open bin) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
