            score -= 2.2 * (1.0 - progress);
        }
        // Penalize post-residuals that are dead zones: too small for mean-sized items.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be pickier (penalize loose fits more);
    // late in stream, just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with below-average residual (consolidate).
    if open_bins_count > 0 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or bins are scarce.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let scarcity = open_bins_count == 0 || (fitting_bins_count <= 1 && fit_ratio < 0.7);
        if poor_fit || scarcity {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

