    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits strongly (post_residual minimization).
    // Late: residual waste matters even more (amplify quadratic term).
    let amp = 0.5 + 1.5 * progress;
    score += amp * (pr * pr) / cap;

    // Reward bins whose residual is "used up" relative to mean residual.
    let mean_term = (mean_residual - pr) / cap;
    score -= 2.0 * mean_term * mean_term * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving residual that fits the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        if diff >= 0.0 {
            score -= 5.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 0.05 * (-diff);
        }
    }

    // Penalize opening a brand-new bin when other bins fit, unless the fit
    // elsewhere would be terrible (large post_residual).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0 * (1.0 - progress);
    }

    score
}

