pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Prefer bins that are already fairly full.
    score += 0.35 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // Strong reward for tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.5 * tightness;

    // Dead-space shaping: penalize residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 7.0;
    }
    if post_residual > 0 && post_residual < 9 {
        score -= 2.0 + (9 - post_residual) as f64 * 0.3;
    }

    // Mod-25 bucket shaping.
    let q = post_residual / 25;
    let r = post_residual % 25;
    if post_residual == 0 {
        score -= 18.0;
    } else if r <= 5 {
        score -= (5 - r) as f64 * 1.55;
    } else if r >= 20 {
        score -= (r - 20) as f64 * 1.55;
    } else {
        score += 3.0 + q as f64;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead coupling with multiplicity counting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack_after = post_residual - next_item_size;
            if slack_after > 0 && slack_after < 14 {
                score += slack_after as f64 * 1.15;
            }
            if slack_after >= 1 && slack_after <= 22 {
                score -= 2.5;
            }
            if slack_after >= next_item_size {
                score -= 5.0;
                if (slack_after - next_item_size) < 14 {
                    score -= 3.5;
                }
                if slack_after % next_item_size == 0 {
                    score -= 4.5;
                }
            }
            if slack_after > 0 && slack_after < 6 {
                score -= 4.0;
            }
            if slack_after >= 6 && slack_after < next_item_size {
                score += 2.0;
            }
            if slack_after >= 2 * next_item_size {
                score -= 3.0;
            }
            if slack_after == 0 {
                score -= 8.0;
            }
            let k_fits = slack_after / next_item_size.max(1);
            if k_fits >= 1 {
                score -= (k_fits.min(3) as f64) * 1.8;
            }
            if k_fits >= 2 && slack_after % next_item_size == 0 {
                score -= 1.5;
            }
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
            if (post_residual / 20) == (next_item_size / 20) {
                score -= 6.0;
            }
            if next_item_size > 60 {
                score -= 5.0;
            }
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size <= 3 {
                score -= 2.5 + chain.min(4) as f64;
            }
            if post_residual >= 3 * next_item_size {
                score -= 2.0;
            }
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.0 * (1.0 - progress);
            } else if rem <= 4 {
                score -= 1.0 * (1.0 - progress);
            }
            let gap = post_residual - next_item_size;
            if gap <= 2 {
                score -= 6.0 * (1.0 - progress);
            } else if gap <= 8 {
                score -= 2.5 * (1.0 - progress);
            }
            // Combined-fit anticipation: after next item, room for current-size class again.
            if slack_after >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
            if slack_after < item_size && slack_after > 0 {
                score += 1.4 * progress;
            }
        } else if post_residual > 0 {
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * (0.65 + 0.35 * (1.0 - progress));
            score += 1.2 + 2.0 * progress;
            if post_residual >= 12 {
                score += 3.0;
            }
            if (post_residual as f64) < 0.35 * (next_item_size as f64) {
                score += 4.0;
            }
            if (post_residual as f64) < (next_item_size as f64) * 0.6 {
                score += 1.5 * progress;
            }
            if (next_item_size - post_residual) <= 4 {
                score += 2.5 * (1.0 - progress);
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 20.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
        if fitting_bins_count >= 2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Time horizon: late in stream, consolidate into nearly-full bins.
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> consolidate early.
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Usable dead-space ratio: penalize bins wasting more than half capacity.
    let dead_space = (bin_residual - post_residual) as f64;
    let usable_dead = dead_space / bin_capacity.max(1) as f64;
    if usable_dead > 0.5 {
        score += (usable_dead - 0.5) as f64 * 9.5;
    }

    if is_new_bin {
        let awkward = post_residual > 0 && post_residual < next_item_size && post_residual > (bin_capacity / 3).max(8);
        let tight = fitting_bins_count <= 1;
        score = (bin_capacity - post_residual) as f64;
        score += mean_residual * 0.3;
        score += 1.0 + progress * 6.0;
        if awkward || tight {
            score -= 10.0 + 0.05 * (post_residual as f64);
        } else {
            score += 14.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual == 0 {
            score -= 6.0;
        }
        if progress > 0.7 && awkward {
            score -= 2.5;
        }
        if open_bins_count > 6 && next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 3.0;
        }
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 8.0;
        }
        if progress > 0.5 && next_item_size > 0 && (bin_capacity - post_residual) < next_item_size && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
        if next_item_size > 0 && (bin_capacity - post_residual) >= next_item_size && (bin_capacity - post_residual) < 2 * next_item_size {
            score -= 7.0;
        }
        if open_bins_count > 4 && post_residual >= next_item_size {
            score += 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 4.0;
        }
        let avg_res = mean_residual.max(1.0);
        if open_bins_count > 3 && avg_res < 18.0 && item_size >= 40 {
            score -= 6.0;
        }
        if avg_res > 45.0 && item_size < 30 {
            score += 5.0;
        }
        if open_bins_count > 5 && avg_res > 25.0 && item_size <= 50 {
            score += 6.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0;
        }
        if progress > 0.6 && open_bins_count > 2 && mean_residual > next_item_size as f64 {
            score += 6.0 * progress;
        }
        if fitting_bins_count > 0 && progress < 0.5 && next_item_size > 0 && open_bins_count > 1 {
            score += 4.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_capacity - post_residual) >= (item_size + next_item_size) {
            score += 5.0;
        }
        if fitting_bins_count > 0 && post_residual <= 8 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.35 * (next_item_size as f64) {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
            score -= 2.0;
        }
        // Stronger dead-fraction penalty for fresh bins when consolidation pressure exists.
        let new_dead_frac = dead_space / bin_capacity.max(1) as f64;
        if open_bins_count > 3 && new_dead_frac > 0.35 {
            score += (new_dead_frac - 0.35) * 14.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 3.0 * progress;
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 5.0 * progress;
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= 2 * next_item_size {
            score += 4.0;
        }
        if post_residual > 0 && post_residual <= 10 {
            score += (11 - post_residual) as f64 * 0.9;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 5.0;
        }
    } else {
        // Mild late-stream alignment with mean residual.
        score -= progress * (mean_residual - post_residual as f64).abs() * 0.25;
        let frag = (post_residual > 0 && post_residual < 6) as i32;
        score -= frag as f64 * 3.0 * (1.0 - progress);
        if progress > 0.6 && post_residual < 10 {
            score -= (10 - post_residual) as f64 * 0.35;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = (post_residual - next_item_size) >= next_item_size;
            if two_fit {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 1.5 * (1.0 - progress);
        }
        if dead_space > 0.0 && dead_space < 12.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 1.2 + 2.0 * progress;
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.16 * (1.0 - progress);
            if post_residual >= 12 {
                score += 3.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let combined = post_residual - next_item_size;
            if combined == 0 {
                score -= 5.0 * progress;
            } else if combined < 5 {
                score -= 3.0 * progress;
            }
        }
        if open_bins_count > 5 && post_residual > 0 && post_residual < next_item_size.max(10) {
            score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let dead_frac = dead_space / bin_capacity.max(1) as f64;
            if dead_frac > 0.25 && dead_frac < 0.6 && dead_space < next_item_size as f64 {
                score += (dead_frac - 0.25) * 8.0;
            } else if dead_frac <= 0.25 {
                score -= (0.25 - dead_frac) * 4.0;
            }
        }
        if next_item_size > 0 && (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 1.2 * progress;
        }
        if dead_space >= 12.0 && dead_space < 30.0 && next_item_size > 0 && (dead_space as u32) >= next_item_size {
            score -= 0.8 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 1.5 * progress;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 1.5 * progress;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual % next_item_size) <= 2 {
            score -= 1.0 * progress;
        }
        // Escalating dead-space penalty scaled by open-bin pressure.
        let dead_frac2 = dead_space / bin_capacity.max(1) as f64;
        if dead_frac2 > 0.45 && post_residual > 0 {
            score += (dead_frac2 - 0.45) * (7.0 + 3.0 * (open_bins_count.min(8) as f64)) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual / next_item_size;
            if chain >= 2 && post_residual % next_item_size == 0 {
                score -= 1.5 * progress;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 >= item_size {
                score -= 1.8 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 16 {
            score -= (16 - post_residual) as f64 * 0.22 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < item_size {
            score -= 1.4 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 2.5 * (1.0 - progress);
        }
        let tight_frac = dead_space / bin_capacity.max(1) as f64;
        if tight_frac > 0.55 && post_residual > 0 {
            score += (tight_frac - 0.55) * 10.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual > bin_capacity / 2 {
            score -= 2.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 && open_bins_count <= 3 {
            score += 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets (capacity fraction classes)
    let post_class = post_residual % 10;
    // Dead-space penalty: small nonzero residuals are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Reward residuals that land on "friendly" class boundaries (multiples of 10/20)
    if post_class == 0 {
        score -= 8.0;
    } else if post_class == 5 {
        score -= 3.0;
    } else {
        score += post_class as f64 * 0.8;
    }

    // Integer-division thresholds: post_residual relative to capacity fractions
    let cap_q = post_residual * 4 / bin_capacity; // 0..3 quarter classes
    score -= match cap_q {
        0 => 6.0,          // <=25% residual: near-full bin, excellent
        1 => 2.0,
        2 => -1.0,
        _ => -4.0,         // mostly empty bin
    };

    // Lookahead coupling: next item should fit the post residual (harmonic match)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward when next item divides nicely into post residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize wasted large residuals
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize lightly early, more when many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 40.0 * progress + open_bins_count as f64 * 2.0;
    }

    // Mild pull toward mean residual (balance load across bins)
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps are worse than large leftovers.
    let dead_zone_start = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone_start {
        // Gap too small for the minimum item (size 1..100 interface, but tiny gaps
        // are hard to fill): penalize proportionally to how close to zero it is.
        score += (dead_zone_start - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are still large; encourage using existing bins as open_bins_count grows.
    let pressure = open_bins_count as f64 * (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere,
    // mildly penalize wasting this bin's residual on a bad split.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * post * post / cap;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match for next item is highly desirable.
        score -= 18.0 * (1.0 - slack / cap);
        // Extra reward for near-exact match.
        if slack <= 5.0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving residual that nothing useful follows into.
        score += 6.0;
    }

    // Compare residual against mean residual of open bins: prefer bins below mean residual
    // (tighter bins) to keep large residuals available for future big items.
    if post < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0 * (post - mean_residual) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize opening a brand-new bin when open bins exist and fit reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        // But allow new bin if the item is huge and would leave tiny dead space elsewhere anyway.
        if item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
    }

    // Mild preference early in stream to keep bins flexible; later, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the smallest possible item (1) is worthless; cap effective dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize post-residual that can't fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the next item: reward chainability.
            score -= 0.35 * next_item_size as f64;
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer fuller ones (smaller residual).
        score -= 0.10 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: empty bin gets a base penalty that decays
    // as the stream progresses (late in stream, prefer closing out bins).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 3.0 * open_pressure - 6.0 * progress;
        // If no existing bin fits well and next item is large, opening fresh
        // is attractive: reduce penalty when post_residual is large.
        if post_residual >= 60 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Global residual balancing: penalize bins far from mean residual
    // (prefer symmetric packing), scaled by how many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - 0.5 * progress);

    // Mild reward for using bins as stream advances (encourage consolidation).
    score -= 0.02 * (item_size as f64);

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_post * norm_post;
    score -= tightness * (2.0 + 4.0 * progress) * cap * 0.05;

    // Penalize dead space quadratically, scaled by progress
    score += norm_post * norm_post * cap * (0.5 + 1.5 * progress);

    // Cubic interaction: favor moderately filled bins mid-stream
    let fill = 1.0 - norm_post;
    score -= fill * fill * fill * cap * 0.3 * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth sigmoid-ish)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = (pr as f64 - next_item_size as f64) / cap;
        let smooth = 1.0 / (1.0 + (-fit_next * 8.0).exp());
        score -= smooth * nxt * cap * 0.6;
        // penalize wasting residual when next item is large but doesn't fit
        let miss = (nxt * cap - pr as f64).max(0.0) / cap;
        score += miss * cap * 0.15 * progress;
    }

    // Last-chance bonus: only fitting bin should be strongly favored
    if fitting_bins_count == 1 {
        score -= cap * 0.4;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Prefer bins below mean residual slightly (balance load)
    score += (pr as f64 - mean_residual) * 0.05;

    // New-bin candidate: penalize mildly, more when good fits exist or early stream
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * (1.0 - progress)) + norm_item * cap * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "dead zones"
    // (residuals that few item sizes can fill), reward nice divisible residuals.
    let pr = post_residual as i64;
    if pr > 0 {
        // Divisibility harmony: residuals divisible by small item classes are reusable.
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d as i64 == 0 {
                harmony += 8.0;
            }
        }
        score -= harmony;

        // Dead-zone penalty: residuals that are too small for typical items (1..=100 range)
        let dead = if pr < 10 { 25.0 } else if pr < 20 { 12.0 } else { 0.0 };
        score += dead;

        // Modulo-class coupling with next item: reward residuals that can host
        // the lookahead item in a "harmonic" split.
        if next_item_size > 0 {
            let ni = next_item_size as i64;
            if pr >= ni {
                // next item fits after this placement: strong reward
                score -= 15.0;
                // extra harmony if post_residual minus next item is again well-classed
                let pr2 = pr - ni;
                if pr2 % 10 == 0 || pr2 % 25 == 0 {
                    score -= 6.0;
                }
                if pr2 == 0 {
                    score -= 20.0; // perfect double fill
                }
            } else {
                // lookahead won't fit: penalize proportionally to waste
                score += (ni - pr) as f64 * 0.5;
            }
        }
    } else {
        // Perfect closure of a bin: maximal reward.
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is poor
    // and residual is large/valuable relative to item.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline, penalize slightly so it's used only
        // when open bins create big dead space.
        score += 5.0;
        // But if the item is large and mean residual is small, opening fresh is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if (mean_residual < item_size as f64 * 0.5) && open_bins_count > 0 {
            score -= 10.0;
        }
        if progress > 0.9 {
            score -= 3.0; // late stream: keep bins tight
        }
    }

    // Slight preference for tighter existing bins (smaller residual before placement)
    score += bin_residual as f64 * 0.05;

    // Mild exploration-free pressure: keep number of open bins low
    score += open_bins_count as f64 * 0.1;

    score
}

