    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize bins whose residual is only slightly larger than the item (awkward fit),
    // reward bins with ample slack.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: prefer using existing bins when many are open,
    // but allow new bins when few are open (fresh capacity flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 30.0 + 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus wasted-capacity accounting.
        score += new_bin_penalty;
        // If only one fitting bin exists, strongly discourage abandoning it.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor placing here to avoid opening a bin.
        score -= 70.0;
    }

    // Prefer bins with residual close to the item (minimize fragmentation),
    // measured against mean residual of open bins.
    let frag = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * frag;
    score -= 0.15 * (mean_residual - item_size as f64).abs();

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits but not quite, mild penalty (near-dead space).
    if next_item_size > post_residual && next_item_size - post_residual.min(next_item_size) <= 5 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

