    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild preference for opening new bins early in the stream (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

