pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero.
    if post_residual > 0 && post_residual <= 10 {
        score -= 12.0;
    }
    // Penalize awkward dead space that likely cannot be reused (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64 - ni).abs() < 1.0 {
            score -= 25.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            score -= 6.0;
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += (ni - post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    }

    // Prefer bins tighter than the mean residual (more filled bins first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(30.0) * 0.3;
    } else {
        score += (residual_f - mean_residual).min(30.0) * 0.2;
    }

    // Time horizon: early on, be conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 40 && progress < 0.5 {
        score += 5.0;
    }

