pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * post_norm * post_norm * (0.5 + t);
    score -= 9.0 * post_norm * (1.0 - t) * (1.0 - t);
    // dead-space penalty: small post residual late in stream is bad
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (0.5 + t);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - t);
    }
    // lookahead fit reward
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 5.0 * (1.0 - post / cap);
        } else {
            score += 3.0 * (next_item_size as f64 - post) / cap;
        }
    }
    // coupling with mean residual across open bins
    score += 0.05 * (post - mean_residual).abs() * (1.0 + t);
    // mild pressure to prefer existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - t) + 0.1 * open_bins_count as f64;
    }
    score
}

