pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 as "dead space classes".
    let post = post_residual;
    let residue = (post % 10) as f64;
    score += residue * 0.35;

    // Perfect fits (post_residual in {0, 10, 20, ...} multiples of 10) are golden.
    if post % 10 == 0 && post != bin_capacity {
        score -= 12.0;
    }

    // Exact fill is best possible.
    if post == 0 {
        score -= 25.0;
    }

    // Tiny unusable slivers are penalized (dead space < 10 is nearly worthless).
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Integer-division threshold classes on post_residual.
    let q = post / 25; // 0..4 quarter classes
    match q {
        0 => score += 3.0,   // very tight leftover
        1 => score -= 1.0,
        2 => score -= 2.5,
        3 => score -= 1.5,
        _ => score += 2.0,   // nearly empty bin used wastefully
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 6.0 + slack * 0.1;
            // Harmonic pair: next item exactly consumes the remainder mod 10.
            if (post - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize more if this bin
            // was the item's only option (last-chance dynamics).
            if fitting_bins_count == 1 {
                score += 6.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when no open bin harmonizes well,
    // i.e., when mean residual is large relative to item size or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        score = 55.0
            + mean_residual * 0.25
            - open_pressure * 1.2
            - progress * 5.0
            - (item_size as f64) * 0.15;
        // If item is large, opening fresh is more reasonable.
        if item_size > 50 {
            score -= 6.0;
        }
    }

    // Mild preference to fill fuller bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Progress-scaled tightness pressure: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post as f64 * (0.05 + 0.10 * progress);

