pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size ~1..100, but typical useful
    // threshold around 10) are heavily penalized dead space.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Non-linear reward for tight fits (small post_residual is good).
    score -= 40.0 * (-post_residual as f64 / 25.0).exp();

    // Penalize leaving exactly residual sizes that commonly cause waste
    // (odd gaps like 1..=9 already handled; also penalize gaps that match
    // no likely combination, e.g. > 50 wasted space in a nearly-full bin).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward; if next item would leave another dead gap,
    // penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < dead_threshold as u32 {
                score += 15.0;
            } else {
                score -= 10.0 * (-nxt_post as f64 / 25.0).exp();
            }
        }
    }

    // Open bins pressure: discourage spreading across many open bins when
    // the item fits well somewhere; encourage closing bins (post_residual 0).
    if post_residual == 0 {
        score -= 30.0;
    }
    score += open_bins_count as f64 * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the
    // alternative is a truly bad fit. Empty bin has post_residual == capacity
    // minus item; judge by wasted capacity relative to item size.
