        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Mild progression awareness: early in the stream, keep bins open
    // (favor filling existing bins); late, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Alignment with mean residual: prefer bins whose post residual brings
    // them closer to the mean (balanced packing).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

