pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact/near match of post_residual with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits in the leftover: mild bonus scaled by closeness
            score -= 25.0 / (1.0 + diff / 10.0);
        } else {
            // leftover too small for next item: penalize dead space, worse if tiny
            let waste = next_item_size as f64 - post_residual as f64;
            score += 15.0 * (waste / 20.0).min(1.5);
        }
        // if post_residual would be unusable (<10) but next item could have used residual
        if post_residual < 10 && bin_residual >= next_item_size {
            score += 20.0;
        }
    }

    // Penalize creating very small unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer tighter bins (small residual before placement) slightly
    score += (bin_residual as f64) * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins with decent fit,
    // but allow opening a new bin when remaining open bins have large mean residual mismatch
    if bin_residual == bin_capacity {
        score += 55.0;
        // open new bin early in stream or when mean residual is high (open bins are fragmented)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if mean_residual > 45.0 {
            score -= 20.0;
        }
        if progress < 0.1 {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // balances the pool, slight reward
    if bin_residual as f64 > mean_residual + 30.0 {
        score -= 8.0;
    }

    score
}

