        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward medium gaps
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

