        score = 100.0 - consolidation + 0.3 * mean_residual;
        // Early on, opening a new bin is cheap; late, it's expensive.
        score += 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 20.0;
        }
