pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" size classes
    // (multiples of 10, or large enough) are preferred; tiny dead space is penalized.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if class == 0 {
        score -= 12.0; // round leftover, reusable by decile-sized items
    } else if pr < 10 {
        score += 25.0; // dead space
    } else {
        score += (class as f64) * 0.8; // ragged leftover penalty
    }

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size;
        if fits_next {
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else {
            // leftover nearly matches next item -> near miss, small penalty
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.3;
        }
        // Harmonic match: pr and next_item share a residue class mod 10
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score += 0.0;
    }

    // Last-chance bonus: only one open bin fits, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of alternatives, be picky
    }

    // New-bin candidate handling: empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
