pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are still usable, but gaps that can
    // never fit a meaningful item are wasted. Penalize tiny nonzero gaps
    // heavily (they trap capacity), with a hard cliff below 10.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to the bin residual (fill ratio of the gap).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Penalize leaving a gap just above next_item_size (it will be consumed
    // anyway, so wasting a good bin on a slightly-too-large gap is bad).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score += 8.0;
    }
    // Reward gaps that exactly fit the lookahead item (chain friendly).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading into
    // fresh space; when few bins are open, allow more freedom.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e. filling down the fuller bins first keeps many medium gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well. Make the
    // empty bin moderately expensive so we exhaust open bins first, but let
    // it win when the best alternative leaves a dead gap.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // If the current item is large relative to capacity, a fresh bin is
        // relatively more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

