pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but zero dead space is special.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that is too small for the smallest possible item (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // Next item can follow in this bin: reward tight sequential packing.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the overshoot.
            score += 6.0 + 10.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Relative to mean residual: prefer bins tighter than the average (best-fit flavor),
    // penalize bins with unusually large residuals (fragmentation risk).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += 10.0 * rel;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // If the item is large relative to capacity, opening a new bin is less wasteful.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill_ratio;
        // If other bins fit, discourage new bin more when fits are tight.
        if fitting_bins_count > 0 {
            let best_gap = post_residual as f64;
            if best_gap < 20.0 {
                score += 35.0; // a tight fit exists elsewhere; do not open new bin
            }
        }
    }

    // Late in the stream: consolidate, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for fewer open bins (consolidation pressure).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

