pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;
    let norm_item = it / cap;

    // Smooth polynomial core: reward small post-residual with quadratic coupling
    let mut score = 2.0 * norm_pr * norm_pr + 1.0 * norm_pr;

    // Non-linear interaction between post-residual and stream progress:
    // later in the stream, dead space matters more
    let coupling = norm_pr * (0.5 + 2.0 * progress * progress);
    score += 2.0 * coupling;

    // Penalize post-residual that cannot fit the lookahead item (smooth soft gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 3.0 * gap * gap;
        // Reward post-residual that still accommodates the next item smoothly
        let fit = (pr - nxt).max(0.0) / cap;
        score -= 1.5 * fit * (1.0 - fit);
    }

    // Mild bonus when this is the last fitting bin (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 - norm_item);
    }

    // Encourage consolidation relative to mean residual across open bins
    score += 0.5 * (norm_pr - mean_residual / cap).abs();

    // Slight penalty for opening a brand-new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 1.2 + 2.0 * progress;
    }

    score
}

