pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item (1) are always waste, but gaps that can
    // still hold a typical next item are valuable. Penalize "nearly full"
    // leftovers that are below a usable threshold, scaled by how much of
    // the bin was just consumed.
    let usable_threshold = 12.0; // typical small-item scale
    if (post_residual as f64) < usable_threshold {
        // Dead space: penalize hard, proportional to how close it is to zero.
        score += (usable_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / ((post_residual as f64) + 1.0);
    }

    // If this is the last fitting bin, strongly prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing ones rather than opening new bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has a huge residual; make it
    // moderately attractive only when no open bin fits well. If the best
    // existing-bin post_residual would be dead space, allow opening a new bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.8;
        // If the current item would leave dead space in every existing bin,
        // a fresh bin is better: relax the new-bin penalty.
        if next_item_size > 0 {
            let next_would_fit = post_residual >= next_item_size;
            if !next_would_fit {
                // Item leaves a gap the lookahead can't use -> favor new bin.
                score -= 20.0;
            }
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to distribute); later, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    } else {
        // For existing bins, if post_residual cannot fit the lookahead item,
        // slightly penalize (wasted opportunity), unless it's near full anyway.
        if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 5.0;
        }
        // Prefer bins whose residual is below the mean (consolidate fuller bins).
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

