    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual is better (already baseline).
    // Penalize dead space relative to smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
