        score += 40.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty proportional to spread from mean residual (prefer balanced bins)
    score += 3.0 * ((pr - mean_residual).abs() / cap);

    score
