pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantized into bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: perfect fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: post residual too small for the smallest possible item (<= 1..small)
    // treat near-zero residuals as "sealed" bins: reward proportional to smallness.
    if post_residual > 0 && post_residual < 10 {
        score -= 60.0 - post as f64; // smaller dead space = better sealing
    }

    // Class C: harmonic quarters of capacity. Residuals that are a multiple of
    // a quarter-capacity chunk are more reusable by future items.
    let quarter = bin_capacity / 4;
    let harmonic_bonus = match post_residual % quarter {
        0 => 25.0,
        1 | 3 => 8.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division band of post_residual (eighths of capacity).
    let band = post_residual / (bin_capacity / 8);
    score -= (band as f64) * 2.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward proportional to how tightly next item fills the leftover
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 30.0 * tight;
        } else {
            // next item cannot use this residual: penalize large leftovers slightly
            score += 0.05 * post;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it a
    // fallback unless the fit into an existing bin is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream or when
        // existing bins are fragmented (high mean residual spread).
        score = cap * 0.9;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
        if mean_residual < 15.0 {
            // existing bins nearly full -> new bin is fine
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            // big item coming: keep fresh capacity available
            score -= 30.0;
        }
    }

    // Mild pressure against many open bins with scattered residuals.
    score += 0.01 * open_bins_count as f64;

    // Small nudge toward bins whose residual is close to the mean (balanced use).
    score += 0.1 * (post - mean_residual).abs();

    score
}

