            // mild penalty proportional to the trapped space.
            score += 0.25 * post_residual as f64;
        }
    }

    // --- Last-chance pressure ---
    // If this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // --- Open-bins pressure ---
    // Mild reward for packing into already-open bins, scaled by how many
    // bins are active (consolidation pressure grows with bin count).
    if bin_residual != bin_capacity {
        score -= 0.15 * open_bins_count as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: only wins when existing fits are poor.
        score = bin_capacity as f64
            + 0.8 * open_bins_count as f64
            + 0.4 * mean_residual
            - 6.0 * progress;
