pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post - next).abs();
        if diff <= 1.0 {
            // Perfect match: chain placement, heavily reward.
            score -= 40.0;
        } else if next <= post {
            // Next item fits after this placement: partial reward,
            // stronger when the leftover after the chain is small.
            let chain_left = post - next;
            score -= 25.0 * (1.0 - chain_left / cap);
        } else {
            // Next item won't fit: penalize creating unusable dead space
            // relative to the next item.
            score += 8.0 * (next - post) / cap;
        }
    }

    // Compare against mean residual: a bin already below mean residual
    // is "well-used"; penalize dumping into bins with large residuals
    // (spread items evenly instead).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and
    // residual capacity is plentiful.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins are nearly full.
        let avg_fill = cap - mean_residual;
        score += 10.0 + 0.5 * avg_fill;
        if next_item_size > 0 && post >= next {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Late in the stream, consolidate aggressively (fewer wasted bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post / cap);

    score
}

