pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if this bin's post-residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size >= bin_residual && bin_residual >= item_size {
            // last chance: item exhausts bin nicely
            score -= 8.0;
        }
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep base high, allow opening when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 6.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // open a new bin rather than force a bad fit
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large items pair well in fresh bins
        }
    }

    // Global state: many open bins with low mean residual -> prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) > mean_residual && open_bins_count > 2 {
        score += 4.0 * (open_bins_count as f64).ln();
    }
    score -= 6.0 * progress * tightness;

    // Prefer bins whose residual is close to item size (near-exact usage).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

