pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit).
    let mut score = post;

    // Normalized post-residual and item fraction for smooth coupling.
    let x = post / cap;                      // wasted-space fraction
    let f = item / cap;                      // item size fraction

    // Non-linear polynomial coupling: waste penalized super-linearly,
    // and the penalty grows with stream progress (less slack tolerance late).
