pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-exact fills (post_residual in small harmonic classes).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Penalize dead space via integer-division thresholds on post_residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > half {
        score += 4.0; // still half-empty after placement: wasteful
    } else if post_residual > quarter {
        score += 1.5;
    }

    // Modulo arithmetic on capacity fractions: residuals in the "unfillable"
    // class (post_residual < 10, min item size) are heavily penalized.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 25.0; // dead space: nothing can ever fill it
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward; if next item cannot fit but could elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (next_item_size as f64 / post.max(1.0)));
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: prefer a fresh bin only when the current
    // fit would be terrible (large post residual or dead space).
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score so it wins only over bad fits.
        score = 30.0 + mean_residual * 0.05 - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 && post_residual == bin_capacity {
            score -= 5.0; // fresh bin useful for large next item
        }
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - post / cap);

    score
}

