        let poor_fit = (bin_residual - item_size) < 10;
        if poor_fit {
            score -= 30.0; // opening a new bin beats leaving a sliver
        } else {
            score += 35.0; // prefer existing bins for reasonable fits
        }
    }

    // Lookahead: if the next item could use this bin's post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // residual too small for the known next item
    }

