            }
        }
    }

    // Compare against mean residual: bins with residual far above mean
    // are good hosts for large items; penalize placing in already-lean bins.
    let res = bin_residual as f64;
    if res > mean_residual + 1.0 {
        score -= (res - mean_residual) * 0.3;
    } else if res < mean_residual - 1.0 {
        score += (mean_residual - res) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is huge and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
