pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving medium gaps.
            let gap_waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * gap_waste * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    if pressure < 0.25 {
        score += 15.0 * (0.25 - pressure);
    } else {
        score -= 5.0 * (pressure - 0.25);
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Slight preference for fuller bins overall.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

