pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer small post-residual (tight packing), with non-linear emphasis.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits smoothly: bonus grows as post-residual approaches 0.
    let tightness = 1.0 - (post / cap);
    score -= 6.0 * tightness * tightness * tightness;

    // Dead-space penalty: residual too small for the smallest plausible item (<=10).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0;
    }

    // Lookahead coupling: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > nxt {
            // residual still fits next item -> mild waste of opportunity
            score += 0.08 * (post - nxt);
        } else if nxt > post && nxt <= cap {
            // next item won't fit here; slightly reward having used space now
            score -= 0.05 * (nxt - post).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // or no open bin fits (fitting_bins_count small) or stream is early.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let new_bin_penalty = 8.0 + 0.5 * openness * (1.0 - progress);
        let escape_valve = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        let big_item_bonus = fit_ratio * 10.0 * progress;
        score += new_bin_penalty - escape_valve - big_item_bonus;
    } else {
        // Slight preference for existing bins scaled by how many fit.
        score -= 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: when open bins are generally full (low mean residual),
    // conserving residual capacity matters more.
    let mean_norm = mean_residual / cap;
    score += 2.0 * (1.0 - mean_norm) * (post / cap) * (1.0 + progress);

    // Smooth stream-progress modulation: later in the stream, tolerate larger
    // post-residuals slightly less (finish tight).
    score += 4.0 * progress * (post / cap) * (1.0 - fit_ratio);

    score
}

