pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals that are "nice"
    // fractions of capacity (exact quarters) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual == quarter {
        score -= 25.0;
    } else if post_residual == half {
        score -= 18.0;
    } else if post_residual == 3 * quarter {
        score -= 10.0;
    } else {
        // penalize dead space that is too small to hold typical items
        if post_residual < 10 {
            score += 35.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5;
        }
    }

    // Modulo-class coupling: reward residuals divisible by common item classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for stranding space
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mild pressure toward consolidating into existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // New-bin candidate: make empty bin attractive only when existing residuals
    // are on average poorly matched to the item.
    if bin_residual == bin_capacity {
        let mismatch = (mean_residual - item_size as f64).abs();
        score = cap * 0.8 + mismatch * 2.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= cap - item_size as u32 {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: allow new bin
        }
    }

    // Tie-break with mean residual alignment.
    score += (mean_residual - pr).abs() * 0.05;

