pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 {
        score += 40.0; // unusable sliver
        if post_residual > 0 {
            score += (10 - post_residual) as f64 * 2.0;
        }
    } else if post_residual <= 20 {
        // Semi-usable gap: mild penalty scaled by how little room remains.
        score += (20 - post_residual) as f64 * 0.8;
    } else {
        // Larger residuals are flexible; reward keeping them.
        score -= (post_residual as f64 - 20.0) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fitting the next item too (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocking lookahead item in a tight gap
