    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual.min(30) as f64) * 0.3;

    score
}

