pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor bins where the next item also fits (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: subtract proportionally to how well the leftover
            // after the next item is also small (tight packing chain).
            let after_next = post_residual - next_item_size;
            score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
            if after_next == 0 {
                score -= 25.0; // exact double fit is excellent
            }
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 15.0 + 0.3 * next_item_size as f64;
        }
    }

    // Tight fit reward relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64
            && (fitting_bins_count == 0 || mean_residual < item_size as f64);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 50.0 + 0.4 * mean_residual;
        }
    }

    // Mild preference for balancing residuals against the mean.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly more willing to open bins (spread risk).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

