pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
    score -= 30.0 * (1.0 - fit_ratio);

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: reward bins whose residual after placement can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: residual exactly matches next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global pressure: many open bins -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 - progress);
    score += pressure * 3.0;

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits terribly everywhere else (large item, low fill efficiency)
    if bin_residual == bin_capacity {
        let efficiency = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 35.0 * efficiency;
        // Late in stream, opening new bins is cheaper than fragmenting
        if progress > 0.7 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual close to item + next item combo
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        score -= 5.0;
    }

    score
}

